/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140415-8","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"建設委員会","time":"午後１時００分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件整理しています。","topics":[{"id":"topic-01","title":"品川区地域交通検討会の開催状況","agenda":"品川区地域交通検討会の開催状況","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"それをどういうふうに今度は行政に活かしていくおつもりなのかということと、例えば２年区切ってやるのか、その辺のこともあわせてお答えください。お願いします。","respondent":"中村都市計画課長","answer":"実際に実現できるかどうかの検討をさらに庁内でも進めて、どちらが諮問する、いろいろな意見をこの中から出していただいたものを検討して。こういったものは、その期間も含めて検討会の中であわせて継続して検討していくような形になると思います。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"品川区から例えばこういうようなことをこの検討会に何か区長名で諮問をされたのかどうかの確認と、それから年に２回ということなのですか。それはもう少し回数を増やして、私は品川区の税金を使ってやる以上はこうして進めていくべきだと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"改めてご検討をお願いしたいのと、もっと言えば、これは短い時間にまとめたほうがいいのではないでしょうか。出会手当も払ったりするのでしょうから、非常に内容が薄くなりそうな気がするのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"委員ご指摘のとおり、まず第１回目としまして、包括的な検討をしたところですが、今後、この会で出されました個々の内容につきまして、具体的な検討にこれから入っていきたいと考えております。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３月２５日には傍聴にも参加させていただいたのですが、ホームページをあけたら、開かれた会議であるということでは本当に評価したいと思います。何のための会議かをまず明らかにしていただきたいと思うのが一つ要望ですけれども、私たち、どこがどう違うのかをまず教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"それが実現可能かどうかを実際に具体的に検討して、それを道路管理者、そういった法律に基づく厳密な解決を個々について議論することになります。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どこまで、この先どういうふうなところを見越しながらやっていくのかというところも含めて、今後のところもご報告いただきたいと思っています。新たにそういう手立てもとってほしいというところですけれども、あと、それがどうここに活かされているのかも説明を求めました。","respondent":"中村都市計画課長","answer":"そういった個別の対応もあるでしょうし、そういったものが現実的に実際に可能かどうか、その辺はこれから検討していく余地があると考えております。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どういう住まい方を、ぜひアンケートはやっていただきたいと思っていますので、具体化をしてほしいと求めました。その辺はこの調査に入っているのか、把握されているのかどうか、そこもわかったら説明を求めました。","respondent":"あべ委員長","answer":"今の議題が「交通検討会の開催状況について」という報告ですので、検討そのものではないので、その点も踏まえてのご答弁ということでいいですね。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"そう、調査の中で入っているかどうかという意味ですとの意見を述べました。","respondent":"中村都市計画課長","answer":"アンケートを行うかどうか、その方法につきましては、なるべく広く細かくわかるような形の方法を考えていきたいと考えております。具体的な交通量の調査ができるか、あるいは統計的な問題、それらは検討してまいります。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"確認したいのですが、この意見は、構成メンバーの中の「住民または利用者の代表」という方々からのご意見と受けとめてよろしいのでしょうか。そこをお願いします。","respondent":"中村都市計画課長","answer":"一つは、陳情・請願などもご紹介いたしまして、その中でコミュニティバスという話がございまして、それの紹介・ご報告をいたしました。それからあと、この会での意見ということではなく、それまでさまざま区に要望がございましたものをまとめたものを報告いたしました。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、この会議の中で「住民または利用者の代表者」はお三方いらっしゃいますけれども、この方からはどういう意見が出ているのでしょうか。この方たちはどういう意見をお持ちだったのかということで、まだほかのものが出ているのか、特徴的なものがあれば教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"区民としてのメンバーからの意見ですけれども、これは今、お手元にお配りさせていただいた資料の「主な意見」は、当日、この会議で出たものですが、その中で、区役所の付近の５差路の立会道路と三間通りの逆走が、この中から意見として出されました。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"そして、各町会長は本当に地域のいろいろな状況を知っているわけですから、そういう意見がかなり集まるのではないかと思います。そこはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"この会の参加に当たりまして、当然、この会全体の中でのそれぞれの会の中で意見を吸い上げていただく認識は持っていただいているとは思います。あるいは商店街、観光協会についてまた意見をお伺いしたようなときに、改めてこちらからお願いをしてまいりたいと考えております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"せっかくの会なので、もったいないので、そこは徹底してほしいと求めました。この調査は、誰が、どのように進めていくのかについてお願いします。","respondent":"中村都市計画課長","answer":"この第１回目に出されましたさまざまなご意見に対して、これから具体的に、また、本会においても検討していきたいと考えております。それに当たりまして、それを改めてこの会に諮って検討していくというようなことでお願いしていくというようなことで考えております。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"２回では少ないのではないかと私も思いますので、２年とか３年とかというスパンで、ある程度の成果を出していただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"原委員","kind":"意見","question":"どういった形で１回目、河川もどうか、その辺をご意見をほしいと求めました。","respondent":"中村都市計画課長","answer":"事務局ですけれども、これは私、都市計画課長以下、都市計画課の職員で構成しております。","id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"構成員の方は見させてもらうと、かなり多忙な方々が多いものですから、その中で説明する。その辺も、今の時点で何か漠然とですけれどもあれば、お教えいただきたいのですが。","respondent":"中村都市計画課長","answer":"必要な調査を踏まえて第２回目に臨みたいとは考えておりますが、特に何回と最初から決めていることにはしないようにしたいとは考えてあります。その区民の方が非公開を望んでいるとか、そういったものを除いては、今のところは考えられないと考えています。","id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"公開、皆さんにこれはいち早く、今回は本当にホームページに早く上げてよかったと私も思っております。交通の問題ですから、ですから、今の時点でお持ちになっている考えがあればお教えほしいと求めました。","respondent":"中村都市計画課長","answer":"輸送手段を考える上では非常に重要な要素だと思いますけれども、また、本会の目的もそういったところにあるのかという認識をしております。構成員ですけれども、これも、これは先ほどの道路運送法に基づいた目的の会議ではないというところの利点を活かせればと考えております。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問","question":"だからといって品川区が受け入れていく仕組みではどうもないような気がしていくとなると、当然、全ての議員は。それがなかなか見えないので質問しているのだけれども、この検討会の位置づけを品川区はどうお考えなのですかというところでお伺いしているのですが。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"バス停のバリアフリーならバリアフリーで一つの解決方法を検討していかなければいけない、こういったものが列挙されたのかなと考えております。今後、いつまでも漠然とした検討では解決に当たれませんので… この地域交通検討会ですけれども、先ほど担当の課長からも、目的を述べさせていただきました。わかりにくいということではあったかと考えていますが、２回目以降については、実のある開催になるように進めていきたいと考えています。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問","question":"１年、２年、そういうふうにしていくべきであると思うのです。この検討会だけがずっと続いていって、何かだらだらと重ねていくようなことであってはいけないと思うのですが、そのところはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"地域の交通に関しましては、その中で、この検討会のメンバーの方がそれぞれの専門の立場から意見を言っていただく。これを区だけで検討するよりも、区の責務だと考えていますので、そのような形で進められたらと考えています。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめますけれども、事務局が品川区の方がやられるわけですから、それはやり方としては、この検討会の方向性をいろいろリードできると思うのです。そういう方向へ持っていっていただきたいのと、検討した結果がこうだったということについては、ぜひ議会への報告をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「地域交通に関する区民からの要望事項について」という資料が出されましたけれども、住まわれていらっしゃる方の思いが込められていると思うのです。","respondent":"中村都市計画課長","answer":"こういった個々の意見全てに対応することはなかなか難しいことだと思います。コミュニティバスのあり方そのものも、今ある路線バスとのすみ分けも整理をしていく必要があると考えておりますので、引き続き検討してまいります。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"既に出ている課題について、各課でそれを検討する時間に割いたほうが、私は進みぐあいが全然違ってくると思います。新規事業にするよりは、既にある事業をもう１回ローリングして見直して、それについてご意見をお伺いいたします。","respondent":"中村都市計画課長","answer":"質疑応答の中で方向性が見えてくるというようなのは、一堂に集まるものの意味も必要なのかなというところでこの会議を設けたところです。解決方法については継続して検討しておりますので、この会議だけが検討の場ではないというところをご理解いただければと考えています。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"むしろ現状あるものをもう１回見直しをしっかりやっていくことが大事なのではないかと私は思ったので、こういうふうな質問をさせていただきましたので、ご答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"こんの副委員長","kind":"確認","question":"これまで議会の中でも一般質問で、たしか議事録を確認すると、地域公共交通会議という形で進んでいくものと認識しておりました。その課題が出た後、地域公共交通会議という具体的な形にしていくことが必要かなと思いますが、そこら辺の見通しはどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"そういった非常に多くの時間をかけてまだ検討、あるいは広範囲な影響について検討していかなければいけないものもありますので。迅速に解決する努力はしてまいりますが、なかなか見通しは、非常に今の時点で難しいと考えております。","id":"exchange-022"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"より進めていただきたいという要望ですけれども、東京都で招致されたこともあると、安全・安心なまちづくりにもかかってくることだと思います。ある見通しができるのかなとイメージをしておりましたので、その辺のところをもう一度ご答弁がございましたら、お聞かせ願いたいと思います。","respondent":"中村都市計画課長","answer":"検討会のメンバー、こういったさまざまな機関の意見を踏まえて、そして迅速に解決していく必要があると考えております。今後、例えば法律上の地域公共交通会議を設置する必要があれば、そこへ設置していくようなことも考えていかなければいけないと考えておりますので。","id":"exchange-023"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"あるいはお考えというところでの確認はさせていただきましたので、機会あるごとに議会にもご報告をということを私も要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"あべ委員長","kind":"質問","question":"私からも２点、お伺いしたいと思います。今後、区の中では都市計画課が中心になって取り扱っていくことになるのだという理解でよろしいかどうかということを１点お伺いしたい。","respondent":"中村都市計画課長","answer":"なかなか地域に密着した検討ができるかというと、その辺は、区の役割のほうが大きいかと考えています。必要に応じて福祉担当部署と一緒に連携して図って検討を進めていきたいとは考えておりますが、今後、検討させていただきたいと考えております。","id":"exchange-025"}]},{"id":"topic-02","title":"平成２６年５月都営住宅入居者募集について","agenda":"平成２６年５月都営住宅入居者募集について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"区内の募集戸数は現段階でまだわかっていないということですが、わかるのはいつか教えてほしいのと。これ以前にはわからないのですか、発表するときでしか。","respondent":"矢木住宅担当課長","answer":"１点目です。もう１点目、定期使用住宅と申しますのは、期間を区切りまして使用の許可を与えるといった形式の形態になっております。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"定期使用住宅のところですが、これはいろいろなタイプがあって、それによって使用期間が違うということですか。ここにとりあえず若年ファミリー向けとか多子世帯向けとあるのですが、どういう区切りがあるのか、説明を求めました。","respondent":"矢木住宅担当課長","answer":"こちらはさまざまな段階がございまして、世帯員の年齢、構成等に応じまして使用期間が限られているものと認識しております。","id":"exchange-027"}]},{"id":"topic-03","title":"中延二丁目旧同潤会地区防災街区整備事業準備組合設立について","agenda":"中延二丁目旧同潤会地区防災街区整備事業準備組合設立について","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"５７名の方が加入されていますが、準備組合に入っていらっしゃらない方がどういう状況なのか、との意見を述べました。","respondent":"品川木密整備担当課長","answer":"地権者数は８４名ですが、大体、棟数として８４棟程度、８０棟から９０棟ぐらいあるとご認識していただければと思います。夫婦間で割れている方については、今回の準備組合はまだ発足の状況ということで、見合わせているというような状況です。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺の到達点を教えていただきたいのと、入っていらっしゃらない方もいらっしゃるという意味ではどう、ニュースとかそういった面でどういうふうにしていくのかを説明を求めました。","respondent":"品川木密整備担当課長","answer":"今後は、できれば今年度中に都市計画決定をとっていきたいとは考えてあります。大体の概算の規模となりますけれども、一応、それを計画して都市計画決定をとっていくというような流れになっていると考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"２回目をしているのですけれども、どういう変化があって、どうしても難しいという課題があるのかどうか。そういうところもあると思うのですけれども、全部が共同建て替えとかいろいろな形での対象になってしまうのか、そこはいかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"それからあと、それ以外のケースでということでありますと、いろいろな状況があります。当然、家を建てたばかりなのに共同建替えとはどういうことですかということで、反対という意思を表明されている方もいらっしゃいます。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"新しく新築されている、大分前から視察へ行ったりすると、結構、建替えされている方がいらっしゃるのです。ここは、その対処法があるのかどうかわかりませんが、保護法はいずれはというようなところはなかったのかというそこだけを説明を求めました。","respondent":"品川木密整備担当課長","answer":"ここが共同建替えを考えているのは認識しての建て替えという形で建替えられていらっしゃる方もいらっしゃいます。それまでは待てないというようなことで建て替えに踏み切る方も、現在、この地区の中にはいらっしゃいます。","id":"exchange-031"}]},{"id":"topic-04","title":"百反ずい道周辺道路の交通規制変更の周知について","agenda":"百反ずい道周辺道路の交通規制変更の周知について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"不都合がないかどうか、そこを一つお伺いしたいのが、人が通るとき。新設の歩道橋は、エレベーターで自転車も行けるのか尋ねました。","respondent":"溝口都市開発課長","answer":"２.５ｍの通行部分、階段閉鎖となりますので、今回の交通規制の変更時期に合わせて閉鎖するような形で考えております。新たに設置する歩道橋につきましては、車路つき階段になりますので、エレベーターの中にも自転車が乗れるようなエレベーターを設置しますので。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"確認","question":"そこを一つ確認したいのと、百反の通りからずい道を通って、今まで右に行けましたね。だから、第一三共とか、貨物とか、工業団地等があるあの地域は、右側を通って行く地域の利便性がどう変化するのか説明を求めました。","respondent":"溝口都市開発課長","answer":"ただ、鉄道の高架下が３.４ｍという高さ制限がかかっている兼ね合いがありますので、そういう安全対策がとれなかったという現状があります。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"車は結構使っていらっしゃる方が多いので、その辺の遠回りをしてうんと時間がかかってしまうようなことがないようにしていただきたいと思うのですが、その辺のコミュニケーションは既にできているのか尋ねました。","respondent":"溝口都市開発課長","answer":"この後ご説明しますけれども、かなり私ども、地権者の中に入っています。そういったことでいきますと、ご迷惑が一番かかるであろうところには、十分周知しながら進めてきているものです。","id":"exchange-034"},{"speaker":"伊藤委員","kind":"質問","question":"例えば信号をつけることができるかどうかわからないけれども、そういうことでもして安全対策をしていくべきだと思うのですが、いかがでしょうか。その二つを説明を求めました。","respondent":"溝口都市開発課長","answer":"この歩道設置と、うちの中でも平成１６年からずっといろいろ検討していく中で、最終的にこの案でということをしております。今までも相互通行の中でも、中に信号とまではなかなかいかないのですが、そういったところで車の安全対策はしっかりとっていきたいと考えております。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"単純に車の量が二倍になるわけです。だから、そういう見通しでいいのでしょうかという心配があるのですが、そのことについてのご答弁をあわせてお願いします。","respondent":"溝口都市開発課長","answer":"説明が悪くて申しわけありません。例えば信号現示の変更とか、そういった対応をまた警視庁に求めるとか、そういったものは必要になってくるとは考えているものです。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"まとめますけれども、この周知ですけれども、町会とか地元に言っているのは当然なのだけれども、運転する方々、ここを常時通る方々に対しては、例えば一つの期間のチラシか何かを配って、いつからこうなりますよとか、もっと利用者の目線に合ったＰＲをするべきと思うのですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"引き続き検討していかなければいけない部分でありますが、そういった見えるような、見やすいような形での周知を考えていきたいと考えています。","id":"exchange-037"}]},{"id":"topic-05","title":"広町一丁目周辺地区地区計画について","agenda":"広町一丁目周辺地区地区計画について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"Ｃ地区の地権者の方が何人いらっしゃるのか、また、そのほかの方がどのくらいいらっしゃるのかと、あと、この地域でものづくりが多いと思うのですが、どういった業種があるのか、その辺を説明を求めました。","respondent":"溝口都市開発課長","answer":"一番面積としては、権利者としては、Ａ地区は第一三共が１社と、あと東京電力が一部あります。変電所の関係で持っているという形になっておりますけれども、そういった土地利用の現状です。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"Ａ４判に、平成２５年１２月１２日に「Ｃ地区の地区整備計画策定に向けての意向把握」と書いてあるのですが、この「意向把握」の中身がどのようなものなのか説明を求めました。","respondent":"溝口都市開発課長","answer":"今回、資料の中で１枚、Ａ３判の２ページ目をご覧いただきたいと思います。ご納得いただけるのか、そういったところでの意向把握をするために説明会を開催したものです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"現段階においていろいろな意見を伺っていると思うのですけれども、慎重な意見とか、困るというような反対の意見とか、いろいろあるのでしょうか。その辺を説明を求めました。","respondent":"溝口都市開発課長","answer":"説明会等を行っていく中、また、この説明会を開催するに当たっては、全戸に個別で配布をうちの職員がしております。今回説明している説明会の中で一番多かったのは、どのような形になるのですかとか、そういった質問が多かったということです。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問","question":"ご存じですか、日本で初めてペンキがつくられたところ、これは品川区の教育委員会のお願いで日本ペイントが保存されているわけです。だから、そういうものは当然、残してほしいということを品川区から言っていくべきだと思うのです。","respondent":"溝口都市開発課長","answer":"将来、しっかりと工場地域として保全していく地域というふうに考えておりますので、そういったものに資する用途制御をかけるのが今回の目的です。そのときにもあわせてお願いしていきたい、また、あと教育委員会との連携はしっかり図っていきたいと考えております。","id":"exchange-041"}]},{"id":"topic-06","title":"続きまして、(6)「環境マネジメントシステム再構築について」","agenda":"続きまして、(6)「環境マネジメントシステム再構築について」","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ＩＳＯ１４００１ですけれども、これは区独自でということになるのですが、これは何が不足していてこういう経緯になったのか。どうしてそういうふうになっているのか、その理由をまず説明を求めました。","respondent":"三ツ橋環境課長","answer":"環境マネジメントシステムというものがございまして、その中の一つの手段がＩＳＯ１４００１でした。それが、今はもう職員の意識なども大分統一されまして、環境への意識を図ってまいりましたので、区独自でも大丈夫だと考えております。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"ＩＳＯを取るということは、例えば、対外的にＩＳＯはそれなりの認識度が高いと思います。どういう形で、返上までするわけですから、その辺はいかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"現在、２３区中、品川区以外でＩＳＯを取っているところは、３区のみになっております。１９区は、ほかの独自のＥＭＳになっております。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"それが要らないということはどういう意味なのか。むしろ自治体独自のＥＭＳのほうが、世の中では認められる世界になってきているのか、そこら辺はどういう考え方なのか尋ねました。","respondent":"三ツ橋環境課長","answer":"従来のＩＳＯのすぐれたプロセスは継承しつつ、区独自の効率化、実効性を進めていこうと考えています。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"では、品川区がどういう基準にあるのかは、ほかの人はわからないわけです。そういう基準から返上してまでというところがよくわからないのですけれども、どういうことなのか尋ねました。","respondent":"三ツ橋環境課長","answer":"説明不足で申しわけありません。その法律にのっとったものに関しては、区独自で行った場合、そちらの方向にもきちんと対応できるという形になっております。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちゃんと守られていきますよというものを、これからだと思いますが、きちんと示していただきたい。どこでどういうふうに管理をしていくのですかという、あと、財政面でどう変化をしていくのかというあたりも説明を求めました。","respondent":"三ツ橋環境課長","answer":"実際に実行計画なり省エネ法について帳票をつくっていきたいというものが１点と、そちらでも区独自で大丈夫だということがあります。費用面に関してですけれども、費用面に関しては、今年度のコンサルティング代のみで、次年度以降はかからない予定です。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"よそなどはそういう感じでやっているところが多いということなのでしょうか。このコンサルティング業者がどういうところなのか、そこも説明を求めました。","respondent":"三ツ橋環境課長","answer":"コンサルティング業者につきましては、知識研究所というところで実際にプロポーザルを行った中で選定いたしました。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問","question":"お金をかけずに、１４００１審査に基づく規格を新たにつくって利用することで、返上してこれにしていくのだということでよろしいのですよね。答弁をお願いします。","respondent":"三ツ橋環境課長","answer":"委員のおっしゃるとおりです。","id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問","question":"そうしたら、ぜひ改めてそういうふうな施政をしたということは、先ほど西本委員がおっしゃったように、進んだわけじゃないですか。しかも、税金を節約したということであるから、それはぜひさまざまな形でＰＲしていっていただけないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"原委員","kind":"質問","question":"そうしますと、先ほど、もう１回すみません、コンサルティング業者名をお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"原委員","kind":"意見","question":"単純な話、これはＥでenvironment、まさに環境ですよね。再構築についてというご説明なので、入り口部分で結構なので、その辺のところを環境課長としてお話しほしいと求めました。","respondent":"三ツ橋環境課長","answer":"効率化と実効性の両立ということを考えておりますので、実際にＩＳＯよりも退化しているとはみなさず、充実しているのだということをうたっていきたいと考えています。","id":"exchange-051"},{"speaker":"原委員","kind":"質問","question":"区の経費を使って税金を無駄にしないでいくわけですから。ただ、方向性を間違えないでお願いしたいということなので、その辺についてお考えがあればお願いします。","respondent":"三ツ橋環境課長","answer":"じっくりと検討していって、方向性を間違えないような体制にしていきたいと思いますので、よろしくお願いいたします。","id":"exchange-052"}]},{"id":"topic-07","title":"エコライフアイデア・コンテスト等について","agenda":"エコライフアイデア・コンテスト等について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"低公害車の買換え支援事業ですけれども、これの窓口はどこにあるのか。予算的なものも教えていただけますか。","respondent":"三ツ橋環境課長","answer":"予算につきましては、２００万円程度となっております。２００万円ぐらいです。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"買換えの時期、新たな低公害車への買換えの支援ということですが、前回がいつごろだったか、よくわからないのですが、この利用はどのくらいあるのか、わかったら説明を求めました。","respondent":"三ツ橋環境課長","answer":"新たな買換えの時期ですが、前回、利子補給や保証料、低公害車利子補給、買換え利子補給を、平成１５年から１９年に実施しておりました。〔「利用状況を」と呼ぶ者あり〕 利用状況ですが、利子補給の利用状況です。予定額ですけれども、それから平成２７年度については５０万円程度となって、実績については今すぐに把握しておりません。","id":"exchange-054"},{"speaker":"大沢委員","kind":"質問","question":"サマールックキャンペーンですが、表紙は広告代理店に頼んだのか尋ねました。","respondent":"三ツ橋環境課長","answer":"広告代理店に依頼いたしました。","id":"exchange-055"},{"speaker":"大沢委員","kind":"質問","question":"まとまる質問ではないのですけれども、どうもサマールックキャンペーンでも、そこのところはどういうふうにお考えですか。何を基準にしてこれを選ばれたのか。","respondent":"三ツ橋環境課長","answer":"地球を基準にして、地球のところで、例えば北極にいる北極熊が地球にとってよいように、品川区から節電をしていけば環境によいというイメージです。","id":"exchange-056"},{"speaker":"大沢委員","kind":"意見","question":"西アジアのところに北極熊がいる、おかしな絵のような気がするのです。もう少し脈絡があるような絵図柄を選んでいただいてもよかったのではないかという気がするのですけれども、どう感じられますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]},{"id":"topic-08","title":"大井火力発電所 ガスタービンについて","agenda":"大井火力発電所 ガスタービンについて","exchanges":[{"speaker":"西本委員","kind":"質問","question":"廃止理由の中で、今後新たな電源の営業運転、試運転が順調にということですが、どういう形になっていて、どこから順調になっているのかという、その辺をもう少し詳しく説明を求めました。","respondent":"三ツ橋環境課長","answer":"営業運転につきましては、広野火力発電所６号機、常陸那珂火力発電所２号機が平成２５年１２月に運転開始をしております。試運転につきましては、鹿島火力発電所７号系列、千葉火力発電所３号系列が、平成２５年１２月から３月にかけて順次開始しております。","id":"exchange-058"}]},{"id":"topic-09","title":"３、その他","agenda":"３、その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"このフェンスが３ｍというのはすごく威圧感があると思って、心配なのは、劇団四季がありますね。雰囲気的にあそこに３ｍでどーんとなってしまうと、そういう景観を配慮していただけないものかと思いますが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"そういったものが決まってくると、建物を壊して更地、すぐその後に建築工事に入ってくるという形の流れになってくると考えているものです。３ｍの鋼板の関係ですが、劇団四季との連携も含めて区からお願いしていますが、まだそれに対しての回答はない状況です。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"その目途を言える範囲でお願いしたいことと、劇団四季のことを考えると、強く言っていただきたいです。そこは協力していただかないと、ということはかなり強烈に強めに言っていただきたいところがありますが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"方針が例えばこの平成２６年度中に決まれば、また、少しでも早く社宅の現状の建物を解体できるように協議を進めていきたいと考えているものです。","id":"exchange-060"},{"speaker":"木村委員","kind":"質問・要望","question":"劇団四季の土地が区の持ち物ということでありますから、ＪＲ東日本と品川区が主に協議をして、何か一つの大きなまちをつくっていくということになろうかと思いますけれども、そこに東急電鉄が横にありますから、これとの関係というものがわかれば教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"その後も東急電鉄から同じような商店街の連続性を確保するという観点からも、同じような店舗として使えるような形で整備していくということです。東急電鉄を含めて、しっかりと大井町のにぎわい・発展を考えるべく、しっかりとした協議をしていきたいと考えているものです。","id":"exchange-061"},{"speaker":"木村委員","kind":"質問","question":"東急電鉄の下、今は大体半分ぐらいが工事が終わって、地震のためのあれでしょうけれども、残りは全部、今、ほとんどおくれています。これに合わせて計画が進んでいきそうなのかどうか、そこのところは品川区からもＪＲ東日本に対しての強い意見が言えるのかどうかも説明を求めました。","respondent":"溝口都市開発課長","answer":"一つのキーとしては２０２０年を目指すというのはあると思いますので、そういった中で何ができるのかは、引き続き検討していきたいと考えています。お互い協議をしていますので、関係としては良好な関係を築きながら、よりよいまちについて検討しているというのが今の状況です。","id":"exchange-062"},{"speaker":"伊藤委員","kind":"意見","question":"１点だけですけれども、写真を見て気になったのですけれども、向かって左側、「万能鋼板による閉鎖」という緑のところがあります。だから、何なのか、それだけのことですけれどもとの意見を述べました。","respondent":"溝口都市開発課長","answer":"すみません、説明が不十分で申しわけございませんでした。跡地利用については、今後、どのようになるのかは、ＪＲ東日本で検討しているというのが今の状況です。","id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問","question":"万能鋼板を張るだけで、果たしてそれで安全面が担保できるのかという心配ができたので、それはどうなのか尋ねました。","respondent":"溝口都市開発課長","answer":"委員ご懸念のように、要は敷地の中に、一部にしろ不特定の方が入るような形になります。例えば３ｍの万能鋼板だけでは不十分で、そういったものについては新たな対策等を考えていきたいと考えていると、ＪＲ東日本からは聞いております。","id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問","question":"ここにいる議員は同じ気持ちだと思うけれども、万々が一、ここから火事が出たら大変なことではないですか。それに伴うさまざまなリスクについては抑え込むようなことを、本来は品川区としてきちんと申し入れしていくべきだと思いますが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"さらに足りない部分等については、しっかり要望していきたいと考えております。消防と協議していく中で、より安全な市街地に向けて、しっかりとＪＲ東日本にはさらなる安全対策については要望していきたいと考えております。","id":"exchange-065"},{"speaker":"伊藤委員","kind":"意見","question":"それはきちんと品川区として強く申し入れをしていただいて、安全策をとるようにお願いしておきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけですが、跡地利用が決まるまで撤去しないということですけれども、現存している建物の耐震性がどうかはわからないですけれども、６強とか、７とか、大きな地震が来たときに、倒壊の危険性とか、周囲に与える影響とか、その辺はないのか、考えられているのかどうか、１点だけ説明を求めました。","respondent":"溝口都市開発課長","answer":"そういった意味でいきますと、耐震性は低いものであるというのは事実だと思います。とはいえ、これだけの広大な空地がありますので、それなりの避難地域の確保ができると考えているところです。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"でも、その辺は検討されて、ＪＲ東日本においては大丈夫であるというところの判断なのですか。もう１回、そこのところだけお願いします。","respondent":"溝口都市開発課長","answer":"そういった中で、一定の検討をしていく中で、広域避難所としての機能は確保できると考えてきているものです。とはいえ、ないほうが安全なのは確かですから、少しでも早く建物の除却ができるように協議を進めていきたいと考えております。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"鉄道は、ＪＲ東日本の場所ですね。ＪＲ東日本にしっかり伝えるためには、どのように向き合うべきだと考えているのか、そこのところを最後に決意だけ説明を求めました。","respondent":"溝口都市開発課長","answer":"これまでも社宅の跡地については、ＪＲ東日本本社と定期的な協議を持ちながら進めてきております。一つは、区のほうから安全対策について検討ということで文書を出して、そういった形で要望していきたいと考えているものです。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"補助２９号線と放射２号線の沿道でアンケート調査が行われたと思いますけれども、このアンケート調査の中身とか結果を議会にご報告してくださるのかどうか、また、地域の住民の方にどのように返していかれるのか、その辺をお伺いします。","respondent":"品川木密整備担当課長","answer":"その報告を行う直前ぐらいに議会にもご報告したいと考えています。その辺、今、東京都とタイミングを調整しながら進めているような状況です。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"まだ時期的にはいつと言う状況ではない、近々ではないのですね。なので、いつぐらいに、どういった中身が報告されるのかが知りたかったのと、用途変更ということでは、地区計画の変更が出されるということか尋ねました。","respondent":"品川木密整備担当課長","answer":"用途変更のほうも、地区計画をやるのか、やらないのかというあたりも、東京都と現在、調整している段階です。ですので、説明会等はいついつと申したいのですけれども、まだ現状では、未定という段階ではあります。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/978343?Template=document&Id=4102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":48250,"voices":217}},{"id":"h26-20140415-9","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"文教委員会","time":"午後１時００分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"(1)平成２６年度学級編制","agenda":"(1)平成２６年度学級編制","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ずっと５クラス、キャパが５クラスでいっぱいいっぱいだろうという想像をするんですけれども、そのあたりの関係でそういう判断になったのかどうか。具体的な内容について教えてほしいと求めました。","respondent":"野呂瀬学務課長","answer":"例えば３５人以上になったとしても、例えば１クラスを２人の先生で見るとか、あくまでも東京都のほうから教員の加配が保証される。そういう制度です。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"教員を１人加配しているのかなというふうに私は理解したんですけれども、伊藤学園ではそういうことではないわけですか、というのが一つ。１年間なり何年間か学ぶ環境にとって、やはりどうなのかなと見たときには、そういう質問をしました。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"７年生、８年生、９年生と学級数を揃えたほうがいいというのが大きな一つの判断材料になるということが一つあります。学校経営を考えていったときに、イコール学級数の展開を単純に増やす… 補足しますけれども、当然学校の規模ありますけれども、それも含めて校長がいろいろ総合的に判断して、この学級数を決めたというものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"やはりよりよい教育環境を整えてほしいという思いの中で質問をしているんですけれども、よしというふうには私はならないと思うんですよね。そういう考え方でしっかりと判断をしていっていただきたいというふうに思っておりますので、意見としてそれは言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"小学校で５校、中学校で１校、これだという部分を説明をしていただきたいのと。校長判断と区の判断というのがありますけれども、この弾力的判断は区が判断するということなんですけれども、その辺の仕分け方というんか尋ねました。","respondent":"野呂瀬学務課長","answer":"２年生、例えば中学校でも８年生になったらもう４０人学級なんだからとか、そういう考えも総合的には学校長の判断の中には入っていると思います。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"１８人、１９人にする部分、その説明と言うんでしょうか。その児童目線であれば、そんな少ないよりも多いほうがいいと思うんですけれども、その辺の説明をしてほしいと求めました。","respondent":"渋谷指導課長","answer":"それこそ本当に学校、学級の状況に応じて、例えば何らかで特別な支援の必要のあるお子さんが非常に多い学級の場合には。","id":"exchange-005"}]},{"id":"topic-02","title":"平成２６年度移動教室について（小・中）","agenda":"平成２６年度移動教室について（小・中）","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"二つ行き先があって、これはどういうふうにしてそれぞれの学校がどっちへ行くというふうに決めているのかというところ。それだけ教えてほしいと求めました。","respondent":"渋谷指導課長","answer":"もともと中学校は裏磐梯の福島のほうを中心に進めていたところでありますが、先の事故を受けまして、中学校の校長会のほうの意向です。中学校のほうで実地踏査を福島も改めて行って、保護者の理解が得られているところから順次福島のほうに移っているというふうな状況です。","id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"わかりました。やはり安全が確認できないというのは何かなと思ったんですが、ある意味、よく酌んでいただくという形で進めていただければというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"荏原文化センター耐震改修他工事に伴う荏原図書館の休館","agenda":"荏原文化センター耐震改修他工事に伴う荏原図書館の休館","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"理解を求める説明だとかも含めてちょっと確認したいのと、１０ヶ月にわたっての閉館になるので、それで聞いたんですけど。","respondent":"中元品川図書館長","answer":"通常この規模の工事規模ですと、周辺住民説明会等は開催をするものではないということで聞いております。それで、また、周辺の学校等には個別に私どもから施設長としてご挨拶は参りますが、住民の方への説明会は考えておりません。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"それはそれとして伺っておきたいと思うんですけれども、果たしてそういう体制だけでいいのかどうか、改めて主張はしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-04","title":"品川区臨時給付金","agenda":"品川区臨時給付金","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そこをちょっと確認したいのと。そのあたりを教えてほしいと求めました。","respondent":"福島臨時給付金担当課長","answer":"特に、１２月中旬までの受付期間でありますので、未申請者勧奨などしていく予定です。１０月ないし１１月ぐらいで申請されていない方には再度はがきによる案内をするかどうか、その辺のところについても検討しています。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"そういうたった１回の支給をしたから、だからいいんだというふうになるわけです。したがって、本当に生活を守るという点からも、漏れがないように対応していただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"高橋委員","kind":"意見","question":"わからないのでちょっとお尋ねするんですけど、本来の目的と違うものに使うわけですね、税の情報を。今回の給付金に税情報を使うというのは、どのような仕組みになっているのかというところを、すみませんとの意見を述べました。","respondent":"福島臨時給付金担当課長","answer":"６月中旬に、こちらは税務課のほうで、あなたは平成２６年度税が課税されていませんという情報を区民の方に提供します。国のほうからもそれで大丈夫だというふうに説明を受けていますので、品川区としてもそういうものをつくりまして申請書をお送りする予定です。","id":"exchange-012"},{"speaker":"高橋委員","kind":"確認","question":"そういう税の情報を確認したので、支給される方に知らせるということなんですね、その仕組みでいいということで。それを使っていいですか、どうですかという本人の承諾を得たりするという手続きをする自治体もあるとお聞きしているんですけれども。","respondent":"福島臨時給付金担当課長","answer":"区としましては、特にその確認をすることは行いませんで、あくまでも課税されていない方を対象に、課税されていないという情報とともに申請書を送るという形をとりたいと考えています。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"今の税情報との関係なんですけれども、この通知を発送するにあたっての、ちょっと私、予算書を見てこなかったので単純な質問なんですけど、費用的にはどのくらい経費がかかるんか尋ねました。","respondent":"福島臨時給付金担当課長","answer":"〔「その額はいくらかと」と呼ぶ者あり〕 まず、臨時福祉給付金のほうで、申請書のほうで１，５９７万８，０００円を予定しています。もう一つの子育て世帯臨時特例給付金のほうで６００万円を想定しています。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"発送費用というのは２、０００万円ちょっとぐらい、２，２００万円ぐらいですかね。そういうことを改めて思って、そういうふうな印象を持つものですから、その私の印象を改めて表明をしたところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-05","title":"父親のための親育ちワークショップの実施","agenda":"父親のための親育ちワークショップの実施","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"そういうお父さんたちというのは、一方で、お父さんたちに参加してもらいたいというお母さん方の思いというのが一方であったりしての事業なのか。その辺のニーズの兼ね合いというのは、ちょっと背景を少しご説明いただければと思うんですけれどもとの意見を述べました。","respondent":"伊崎子育て支援課長","answer":"先ほど申し上げました、児童センターでは、ここ５年、６年、父親のための子育て支援事業をやっております。ですので、幅広くそういった層の方にご参加いただけるというような事業を考えております。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"今回は１５人を１クールで２クール実施するということなんですけれども、どんどん他の児童センターに展開していくということは可能なのか。その辺だけちょっとお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"今回、初年度ですので、モデル事業として２カ所実施をいたします。ここでの実施の状況を見ながら、今後の展開は検討してまいります。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"いわゆるニーズがもしあった場合に各児童センターにもっと広げていくという場合に、ハード面とかあるいはソフトの人材面とかというところでの課題はそれほどないという認識でよろしいか尋ねました。","respondent":"伊崎子育て支援課長","answer":"そこで、児童センターの行事がやはり土曜日、日曜日にありますので、その辺の兼ね合い、調整は必要となると考えています。児童センターの職員も長い親育ち支援の経験がありますので、やっていただく、例えば講師などは目的によって選定が必要になってくると考えております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"「父子での参加とし」というふうになっているわけですから、０歳なり１歳の子どもさんも一緒に参加をするということですよね。単純に児童虐待をする人がどうこうということではないんですけれども、その辺の見解を説明を求めました。","respondent":"伊崎子育て支援課長","answer":"それから、今後の展開ですが、先ほども申し上げましたとおり、この２カ所での事業の実施状況を検討いたしまして、年内中には考えてまいります。家庭の中での自分のあり方を見つめ直すということで、虐待に向かう道を絶っていくということも、当然のことながら一つの目的です。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと聞き漏らしたかもしれないので、もう一度、なぜここだったのかというのをご説明いただきたいのと。曜日の設定で日曜日１日だけということで、日曜日だと難しい理由があれば、そこのご説明をもう一度お願いします。","respondent":"伊崎子育て支援課長","answer":"非常に難しいところなんですが、日曜日はできれば家族で過ごす時間にしていただきたいなという思いもございまして、土曜日を中心にしております。１０日にそれを家族を呼んで披露するというプランを考えておりますので、ここは日曜日が入っているところです。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問","question":"場所については地域バランスを見て、比較的今まで行ってきたワークショップ等の父親の事業についての参加が多かったということで、人数もそういった参加のバランスを見て１５人ということになったんか尋ねました。","respondent":"伊崎子育て支援課長","answer":"ワークショップですので交流ができる人数ということで、あまり多い人数は難しゅうありますので、１５人が適当であろうということで１５人といたしております。","id":"exchange-021"},{"speaker":"大倉委員","kind":"意見","question":"まず、初めの事業だということで、ぜひ成果を残していただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-06","title":"事業所型家庭的保育事業（保育ママ）の新規開設","agenda":"事業所型家庭的保育事業（保育ママ）の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"初歩的な質問で恥ずかしいのですけれども、保育ママの広さだとか、そういう施設的な基準というのを説明を求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"家庭的保育事業につきましては、３．３かける３で９．９m2が１人の保育ママと３人のお子さんの広さの一つのパターンです。ママが１人増えるごとに、そのお部屋といいますか、区画が増えていくというイメージです。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、例えば調乳だとか離乳食も対象としてあるわけですけど、そういった施設設備というのは、あまり細かく定められていないのかどうか。広さしかさっき伺わなかったんですけど、ちょっとそのあたりのことが気になっているので、施設的なところを教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"調乳の設備ですとか、あと０歳から２歳ですので沐浴のスペースですね、こういうものを必ず置くようにという形で指導しております。３．３かける例えば保育ママ３人ですと、本来ならば３０m2あれば一定広さ、大体５０m2以上の広さで保育ママ３人の場合は実施しています。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"その開設準備経費として１施設当たり３００万円なんですが、その３００万円で、例えば調乳のいろいろな調理台も含めて必要なものをそろえるとか、沐浴に必要な器具、設備をそろえるとかと、そんなふうな考え方でこの開設準備経費というのが充てられるというふうに考えていいんですかね。","respondent":"今井制度改革・待機児童対策担当課長","answer":"委員ご指摘のとおり、この１施設当たり３００万円の中では、例えばベビーバギーですとか、今お話がありました沐浴のコーナーですとか、そういうものも全て含めまして１施設当たり３００万円という形で助成しております。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"大体３人ですから、そういうところが設備されているというのは確認してきたところはあるんだけれども、改めて確認したいんですけど。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現行ではこちら、家庭的保育事業のほうは原則お弁当持参です。委員ご指摘のとおり、調理設備と沐浴スペースですね、こちらについては全て備わっております。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"全部で３３人の定員増ということですけれども、なかなかお答えするのは難しいかもしれませんけれども、答えられる範囲でちょっとお伺いしたいのと。その基準の面で可能なのかということと、もしそうだとしたら今回１５人としたという理由をお伺いしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"施設(2)の裏面の予定地を見ていただきますと、奥のほうに２つの保育室という形で、レイアウトを考えております。品川区では今、家庭的保育事業は１５人までの制限となっておりますので、品川区としては１５人が開設の上限の人数です。","id":"exchange-027"},{"speaker":"沢田副委員長","kind":"確認","question":"改めて確認をしたいんですけれども、今のところ３施設が開設されるということですけど、こういう３つの施設ができるのか。ますますこういう状況が、飽和状態になってきてもっともっと開設しなければいけないとなったときに、どういうふうにこの働きかけを行っているのか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"やはり１施設だけですと、もう１施設開設したいというふうな状況の中で、この３事業者が積極的にご提案いただいた事業者です。そこの事業者でもう１施設開設することができるか、私どもから電話等なりをして、積極的に開設のご支援をするということをお知らせしております。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"４月入園にかなわなかった方たちが再度５月の募集に応募してこられているというふうに思うんですけど、その数が何人ぐらいいらっしゃるのか。ちょっとそのあたりのことも含めて教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"４月１０日に締め切りをいたしまして、今、数としては申込みの総数のほうは手持ちにございません。ただ、こちらのほう、審査が終わりまして、実際に決定したときに周知するときに、その通知の中に保育ママのご案内を同封する予定です。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"やはり４月１０日に締め切って、今日は１５日ですから、今わからなければ時間をとって後ででもいいからぜひ教えていただきたいと。わからないで私は納得できないから、ぜひ教えていただきたいというふうに思っていますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"委員長が今、適宜適切にとおっしゃった、それはそのとおりだと思うんですけど、でも、時期がね、５月には委員会は予定されるんですか、文教委員会。では具体的には今日は４月１５日ですから、３日とか今週中とか、そういうことで受けとめていいということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-07","title":"(3)のその他","agenda":"(3)のその他","exchanges":[{"speaker":"南委員","kind":"意見","question":"業者とのいろいろな関係があって５月３０日からの日程になったんだろうと思うんですが、休館が続くゴールデンウィークなどのような、その辺について。とりわけオアシスルームの利用状況がどうなっているのか、こういうふうになったのかというあたりを聞きたいと思いますとの意見を述べました。","respondent":"伊崎子育て支援課長","answer":"工事期間につきましては、やはり事業者との関係がありますので、この期間となっております。なるべく短期間に終わらせたいということで安全確保をするため、土日も含めてこの期間に工事を予定しております。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"５月に公募を予定するというふうになっていたと思うので、することになりましたので、突然のことでよろしくお願いしたいと思います。業務要求水準書というのはそれに基づいてつくられるべきだというふうに思っているんですけれども、あえて確認をさせてほしいと求めました。","respondent":"中元品川図書館長","answer":"最初のプロポーザルの方式ですが、現在、これはまだ調整中ですが、方向性としましては公募型プロポーザル方式ということで検討を進めております。こちらについては、ホームページ等で公表しますので、議会等に改めてご報告する予定はございません。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう視点をぜひ入れて募っていただきたいというふうに思っているんですけど、そのあたりの点について。もっといっぱいあるんですけど、今日はこのあたりで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/510624?Template=document&Id=4820#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":31055,"voices":120}},{"id":"h26-20140415-5","meetingId":"h26-cm04","date":"2014年4月15日","dateIso":"2014-04-15","committee":"総務委員会","time":"午後１時００分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"品川区長期基本計画の改訂および品川区総合実施計画（第３次）の策定","agenda":"品川区長期基本計画の改訂および品川区総合実施計画（第３次）の策定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はそれぞれの分野別に各常任委員会で３年間でこういうふうな方向でいくというところでのご報告をいただいて質疑ができるというようなことにぜひし…この本編のほうはどういうふうにしたら手に入るのか、そのことについてちょっと説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"細かく内容をどこまで説明するかというのはあるかと思いますが、一旦はこちらの場でトータルの説明をさせていただいたところで。ホームページに掲載させていただいてありますので、ダウンロード等は可能ですので、どちらかの方法でご利用いただけると考えています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この長期基本計画の分厚い改訂版というのも、そういう形で資料コーナーのほうで販売するということになるのでしょうか、欲しい場合は。それからこの概要版は、その部数というのはいただけるということでいいんでしょうかということを、まずちょっと説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"ちなみに、実施計画のほうが５００円ということになってあります。あまり一遍に大きな数となるとちょっと対応が難しい場面もありますけれども、そういったところでお申し出いただければと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは第３次ということでのダイジェスト版ということで、この見開き、この中身そのものも第３次ということで捉えるものなんでしょうか。それとも、この品川区長期基本計画の中身についての説明ということなんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"これが第３次の実施計画ということで、細かく書いてある項目そのものが実施計画事業ということになってございまして、これが第３次分の実施計画の２９０事業がここに項目として出ているといった内容です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ありがとうございました。４カ所、３カ所だととても足りないのではないかと思いますけれども、その考え方についてもお聞かせほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"そういったところのニーズであるとか、取っていくというところでございまして、この総合実施計画事業のさらに個別の予算事業という中身が出てきます。この実施計画事業におきましては、この３年間、さらには年度途中も含めて見直しというのは常にかけていくといったところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ありがとうございました。今聞き漏らしてしまったんですけれども、待機児童解消というところで対策をとっていくという考え方でいいのかだけちょっと確認いたします。","respondent":"柏原行財政改革担当課長","answer":"言葉のあれになってしまいますけれども、品川区といたしましては、待機児童に対してはそういったことがなるべく出ないような形で対策を総合的にとっていきたい、そういう姿勢だと。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は認可保育園に申し込んでいる子どもたちが全て入れるという形にしていただきたいと希望させてほしいと求めました。各常任委員会での報告をして、議論もできるような形でこういうことを今後ぜひご検討いただきたいということで要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"歳入について平成２８年度はまたぐっと出ている、伸びているということですが、これは何かそういう根拠があってあれなんでしょうか。一般の区民が見られたときに何かこれだけ急に伸びるということは何かあるのかなと思いますが、ちょっと中身を、どういうことなのか説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"平成２８年度につきましては、計画を進めていく中で、例えば再開発の事業、こういったところの建設ですね。こういったところが大きな要因で、平成２８年度は事業費が多くなっているといったものです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"もう一つなんですが、特別区税を含めて交付金、国・都支出金は事業費に対して伸びていくんだからそれはそれでいいと思いますが、こういうふうに第３次を見る限りにおいては、若干でこぼこはあるにせよ、伸びていくというような予測を立てているということで考えていていいんですねとの意見を述べました。","respondent":"柏原行財政改革担当課長","answer":"こういった財政のフレーム等々は予測を立てるときに、その先まで正確にどうかというのはありますけれども、現段階での状況を見ながら、緩やかな景気の回復基調にあるといったところを見込みながら、こういった予想を作成するといったものです。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"ちょっと質問がかぶる部分もあると思いますけれども、ご容赦ほしいと求めました。５００円ということですけれども、販売量があるのかないのかちょっとお伺いしたいのと、概数で結構ですので説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"申しわけありません、実施計画にいたしましても、数十冊程度です。それから、実施計画のダイジェスト版は３年分ということでございまして５,０００部つくってございまして、周知のやり方にもよりますけれども。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"大体どのぐらいの数字かなということでお伺いしたかったので、わかりやすくできている概要版ですとかダイジェスト版などは。総合実施計画のほうが第２次しか出てこなかったので、この件は確認をしておいていただきたいのと、イメージが湧くような形で説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"実施計画のほうのホームページです。申しわけございません、ちょっと数字のほうは今手元にございません。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"今お伺いしようと思ったことをお話しいただいたんですけれども、今年度の長期基本計画ですとか実施計画とか、こういうことに関して、実際に区民からどのようなご意見、また問い合わせがあるものなのか、件数とか概要とか、もしわかればということで教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"平常時といいますと実施計画が動いている中ではあまりこのことについては個別具体に何かということはございません。あまり区民の方から直接この内容の中身ということのお問い合わせはあまりないというのが現状です。","id":"exchange-011"},{"speaker":"浅野委員","kind":"意見","question":"なるべく区民の方の目に触れるような形をこれからもつくっていっていただいて、また幅広くご意見をいただけるような、ある意味ではコミュニケーションがとれるような状況をつくってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"区長が「第３次の策定にあたって」、ご挨拶をしていて、区民の皆さまのご理解とご協力をお願い申し上げます」という形で改訂をしていると。ぜひ皆さんの意識の中でもやっぱり実行していくのが使命なんだし、よりよいことをやるんで、ぜひそこら辺のことをしっかり打ち出してほしい。","respondent":"柏原行財政改革担当課長","answer":"名称変更、端的に申しますと再編でございまして、平成２７年度に子ども・子育て支援新制度になってまいります。いじめや不登校等々の学校現場で起こる課題に迅速に対応していくといった観点から、学校支援担当という担当課長ポストを新設しています。","id":"exchange-013"}]},{"id":"topic-02","title":"ないので、以上で本件を終了いたします。 ──────────────────────────────────────────── (2) 平成２６年度組織改正…","agenda":"ないので、以上で本件を終了いたします。 ──────────────────────────────────────────── (2) 平成２６年度組織改正…","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっとわからないので教えていただきたいんですが、オリンピック・パラリンピック推進担当課長というのができたわけですよね。何か意味合いがあるのかどうか、何でかなとちょっと思ったので、それを教えていただきたい。","respondent":"柏原行財政改革担当課長","answer":"ただ、直接的にこれで書かなくちゃいけない決まりではありませんので、今後こういった際にはちょっとわかりやすい表記を考えていきたいと思います。考え方としては、そういう表記の仕方をしています。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"それがよくわかんないなと思ったんで聞いたんで、今の説明はちょっとよくわかんなかったなと思ってるんですけれども。いいんですよ、担当課長がいてもいいけれども統括するんですよという理解でいいのかどうか、そこら辺の理解の感じを教えてもらえるかな。","respondent":"柏原行財政改革担当課長、秋山情報システム課長","answer":"説明が少なくて申しわけありません。あくまでも担当課長のほうはそこから抜き出したものをやっていくという、切り分けていきますという形になってあります。１枚おめくりいただきまして、マイ・ポータル（情報提供等記録開示システム）というのを設置する予定です。","id":"exchange-015"}]},{"id":"topic-03","title":"ますので、以上で本件を終了いたします。 ──────────────────────────────────────────── (3) 社会保障・税番号制度…","agenda":"ますので、以上で本件を終了いたします。 ──────────────────────────────────────────── (3) 社会保障・税番号制度…","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"何ですかね、もう１回そこを詳しく。任意なのかどうなのかというのを説明を求めました。","respondent":"秋山情報システム課長","answer":"実現したとき、ちょっと私からはお話しできませんけれども、当然そういう方向で検討は進めていると考えております。すみません、ちょっと説明をはしょってしまったのですけれども、通知カードをまず平成２７年１０月以降に全区民の方に発行いたします。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問","question":"３０％、４０％多分いっているのか、何％でしたっけね、今、この間お伺いしたときに。すみません、この個人番号カードを申請してもらわないと、何かそこにデメリットが発生するのかどうなのかとか、そういうあたりを説明を求めました。","respondent":"秋山情報システム課長","answer":"個人番号カードの利用が、申請が多くなるようなＰＲを国としてもこの平成２８年１月に向けて全国的にＰＲをしていく予定ですので。持たないことによるデメリットというのは、特段これがないとできないというものではないので、ないというふうに考えています。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本当に高齢者の人たちはおそらく何が何だかわからない部分だと思いますので、いろいろなところでカードの周知徹底を図っていっていただきたいなと。できれば、普及率というか発行率が５０％超えるのが妥当なのかどうかわかりませんが、それを目指してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的な中身としてどれとどれがどういうふうに簡素化できるのかというところをちょっと１点教えてほしいと求めました。区としてはこのシステムづくりではどれぐらいのお金がかかるかというところもちょっと説明を求めました。","respondent":"秋山情報システム課長","answer":"それから、費用ですけれども、平成２６年度予算では、１,０００万円の予算をつけていただいております。平成２７年度以降、概算で、品川区でどのぐらいかかるかというのは若干ちょっとそれとは相違してくるのかなと考えております。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区１自治体で１億ぐらいかかるという感じだということなんでしょうか。年金手帳の番号と、そういうふうな仕組みになっていくのかどうか、この仕組みの大もとのところをちょっとお聞かせほしいと求めました。","respondent":"秋山情報システム課長","answer":"１点目なんですけれども、医療に関しては今後の検討ということでご理解いただければと思います。今厚生労働省において、医療関係についてはどうするかということは検討されているというふうに。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"例えば介護保険の保険給付の支給とか、そういうふうなものも全部ここの中には書かれているんですか、利用範囲ということで。保険料の徴収に関する事務、そういうようなところは書かれているんですけれども、保険証とか何かは全く関係ないんか尋ねました。","respondent":"秋山情報システム課長","answer":"照会、提供を個々の番号について行うことまで可能になるという仕組みだけですので、一元的な管理ということにはならないと考えています。税であるとか、税の調書等には個人番号は記載をされますけれども、医療の関係の健康保険組合等については、番号が記載されることには……。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３年後にまた見直して、個人的なところの保険証の番号とか、そういうものではないんでしょうか。年金番号もあり、給付の状況も確認できると、そういうふうな状況につながっていくというのがこのマイナンバーということではないのか尋ねました。","respondent":"秋山情報システム課長","answer":"番号を使って、例えば所得情報ですとか世帯情報を地方自治体とか行政機関で問い合わせをすることが可能になるというのがメーンであります。そういうことだというふうに私は理解しています。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だって、そのところに聞きにいったときにその番号の人の情報を教えてくださいと言ったって、情報をとることができないわけではないですか。同じ番号で、例えば私だったならば鈴木ひろ子の番号ということで年金にしてもそういうふうに管理されるというふうなことになるのではないのか尋ねました。","respondent":"秋山情報システム課長","answer":"そこの説明を今からしますけれども、個人番号を符号というのに変換をして、相手方の自治体にその符号で取りにいきます。その途中に、ちょっとその辺の説明は私のほうではしょってしまったので、分散管理だというふうな説明をさせていただきました。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どちらにしても、個人番号ということで管理をされるということで理解をしていいのかということを確認をさせてほしいと求めました。そこのところは具体的にどういうことになっていくのかということも、ちょっとお聞かせほしいと求めました。","respondent":"秋山情報システム課長","answer":"限定されて使っていいことになりますので、番号を使って、総背番号制につながるものではないというふうには考えてあります。特定個人情報ファイルですけれども、ちょっと説明は省いてしまって申しわけないんですが、それを特定個人情報というふうに番号法では規定しています。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと本当に今の、また改めてそういうふうな機会ごとにわかりやすく説明していただきたいなと思っているところです。そういうものに対してのセキュリティというか防止策というのはどうしていくのかということについてもお聞かせほしいと求めました。","respondent":"秋山情報システム課長","answer":"番号のみであれば成りすましということが発生しますけれども、日本の場合は本人確認の義務づけがありますので、そういうことはないということ。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"アメリカや韓国は顔写真ついてないんでしょうか。今後品川区の庁舎内の体制というところでは、職員の体制というのはどういう体制でこれを整備していくのか、その点についても説明を求めました。","respondent":"秋山情報システム課長","answer":"それは私ではちょっとお答えができませんので、番号のみでの本人確認は番号法ではできないという規定をしております。先ほど、組織改正のところでご説明をいたしましたけれども、番号制度調整委員会が各部会を立ち上げてしていくという形になります。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さまざまな方が、既に世界ではこういうふうな犯罪ですとか情報の流出とかそういうふうなところがこれだけ大きく起こっているわけですから。施行されていくというふうな状況になるわけですから、そこのところも踏まえた対応をしていただきたいということと、そういうところの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"顔写真でその人が間違いなく本人かどうかという本人確認、相当難しい問題が起きるのかなというふうに、ちょっと非常に心配なんですね。１回撮ればもういいのかということと、そういう判断の難しさはあると思いますが、その辺についてちょっとご見解だけ説明を求めました。","respondent":"秋山情報システム課長","answer":"有効期限ですけれども、一応１０年を今想定していますので、１０年たったら写真が入れかわる。若年者については、変化が激しいだろうということで５年という有効期限をつくっているというふうにしておりますので、可能かと考えています。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"でもそこではないとちょっと明確な危機管理の判断もできないということだと思いますが、なかなか区役所に皆さん来てくれというのもどうなのかな。かえってマイナンバーに移行するのに人を遠のかせてるのかなというふうなことも思いますが、その点についてどういうふうにお考えか尋ねました。","respondent":"秋山情報システム課長","answer":"交付に関しての事務については、国からまだ詳細なものが出てきておりません。それから出向いてというのができるのかできないのかという形についてはまだこれからの検討かなと考えていますので。","id":"exchange-029"}]},{"id":"topic-04","title":"土木工事等の契約に係る前払金対象の拡大","agenda":"土木工事等の契約に係る前払金対象の拡大","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"たくさん、ほとんどがあると思いますが、その辺についてバランス的にどのようにお考えでしょうか。見解だけ説明を求めました。","respondent":"立川経理課長","answer":"事前に資材の購入とか準備が必要であるために、そうした資材購入費等の準備資金としてもらうということで考えて、前払いをしています。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"大半の民間企業にはないんだけど、そのバランス的に、公共事業だとしなきゃいけないというふうに考えてどんどんしていくということですかね。どうか尋ねました。","respondent":"立川経理課長","answer":"昨今、労務単価等につきましても単価改定等をいたしまして、事業者としましては、資金繰り等がやはり前払金により安定するといった、そういったところに行政としては配慮していかなければいけないと考えているところです。","id":"exchange-031"}]},{"id":"topic-05","title":"品川区施工能力等審査型総合評価方式の評価項目等の変更","agenda":"品川区施工能力等審査型総合評価方式の評価項目等の変更","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"こういうふうな枠をどんどんつけていくと、ちょっとそういうことを思いますので、果たしてどうなのかなというのはちょっと疑問を投げかけします。これをやっていくんでしょうが、今後の入札状況も踏まえながら、見ながらまた次に質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"あまり変わらないのかとか、そこら辺がちょっとまるきりわからない、この４点ということに対して。大きな、ざっくりでいいので、そういうのは増えるんですかね、過去の実績をとると。","respondent":"立川経理課長","answer":"価格点につきましては、最低制限価格というのを現在区では１０分の８から３分の２の範囲内で実施していますが。それで、やはり価格点が、例えばいわゆる予定価格に対して９９％の価格で入札を入れると、これは価格点が実は１点しかつかないということになります。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/531035?Template=document&Id=1980#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":40009,"voices":101}},{"id":"h26-20140416-14","meetingId":"h26-cm04","date":"2014年4月16日","dateIso":"2014-04-16","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"受益者負担に関すること","agenda":"受益者負担に関すること","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"その中で、聞き方が難しいのですが、それぞれ聞いていくと大変な量になってしまうので幾つか例としてというか、選んだ形で伺いたいと思います。３番目に多い、まずそれを１点、伺わせてください。","respondent":"安藤文化スポーツ振興課長","answer":"区民を対象とし、かつ、区長が必要と認めた事業を実施するために利用するときというものが全額免除となります。そして、２つ目のご質問ですが、見直しの規定の整理のところですが、特にここのところは見直し等はしてございません。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"もちろんお１人で使うわけではないケースがほとんどですから、免除というのは逆になかなか理解が難しくなっているのかなという思いがあります。ですから、あるいは税外収入の点からも、これだけランニングも含めてコストがかかっているのだよというものが表現されることも必要かなと。","respondent":"柏原行財政改革担当課長","answer":"そういうわかりづらさとかというのはあって、区民の方からすると、どういうことなんだという声もあるというのは認識しています。少し選別しなくてはいけないと思いますけれども、その減額と免除の考え方というのは、一定程度整理が必要なのかなと思ってあります。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"しかし今度逆に言うと、１つの例として６割を切った場合というのは、いろいろ課題があるよねと。利用を変えるときに役立つのではないかと思ったので、ちょっと関連するこの２点、考え方をお知らせほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"利用料金を考える際に、少し検討する課題ではあるかと思うんですけれども、今のところそれを具体的にするというものを持っているわけではないです。考え方としては、当然あるべきものだと思いますので、その分析の部分と合わせながらの検討だろうと考えています。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"意見","question":"限られた施設をより効率よく、あるいは有効にするという中で、利用者のモラルとか意識も並行すべきだと思うんです。利用率のところで、利用率もあるしという思いがあったので、ぜひご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"私は利用率をどうやって上げるかという角度でちょっと質問したいと思います。聴覚障害者、この際ちょっとそこも含めて聞いておきたいと思うんですけれども、どの程度進んでいるのか尋ねました。","respondent":"安藤文化スポーツ振興課長、久保田地域活動課長、米田商業・観光課長、白鳥高齢者いきがい課長、伊崎子育て支援課長","answer":"私どもの所管の施設につきましては、例えば平成２２年１０月にオープンいたしました五反田文化センターの音楽ホールがあります。そして… バリアフリー化のほうもほとんどのところでは進んでおり、エレベーター等もほとんどの地域センターのほうで設置はされております。… 中小企業センターですけれども、いわゆる身体障害者の方への配慮、スロープですとか多目的トイレというものについては整備しています。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"音楽ホールだけしか使わないわけではないわけですから、スタジオ等々も含めて、どこの施設でもやはり進めていく必要はあるのではないかと思うんです。そういう点についてちょっと伺いたいし、お金だけではないと思いますので、そういう意味での角度からの見解をちょっと伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"でどんな方でも使えるような形というのは目指すべきところでもあるとは思ってあります。ですので、それはもろもろありますので、必要に応じた形でそういったものも進めていくとう考え方は基本的には持っているものです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ持っていただいて、具体的に整備計画をつくってほしいと求めました。整備させていくということが大事だと思いますので、冒頭でも言ったように、ぜひそういう意味での整備を計画的に早くつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤委員","kind":"意見","question":"本格的にどうあるべきだろうと考えていく原点が、そのあたりについて、お考えをお聞かせください。この３点との意見を述べました。","respondent":"柏原行財政改革担当課長、白鳥高齢者いきがい課長","answer":"先ほどの冒頭の説明でもちょっと申し上げたのですが、それから、土・日・祝日の使い方も違っていると。今後こういったところを検討する際に、区民の方の声を聞くとか、いろいろな分析が必要なのだろうとは思っております。 あるいは趣味等の中で、外部のほうから講師をお招きしてという場合には、そのグループの中で区民以外の方が入るということはあります。","id":"exchange-008"},{"speaker":"須藤委員","kind":"提案","question":"そのあたりを今後、僕らもしっかりこの数値を見ながら提案していきたいと思うんですけれども、考えておいてほしいと求めました。どうしてもあそこはこっちから行くと、年に何回かしか使っていないというのでも、８人ぐらい入る大きなスペースが空いているとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"これまでの質問と部分的に似ているところもあるのですが、幾つかお伺いしたいと思います。高齢者の団体をここまで広範に免除ということにしていいのかどうかについて、この辺についての区のお考えを説明を求めました。","respondent":"柏原行財政改革担当課長、安藤文化スポーツ振興課長","answer":"３点のご質問の部分で、全体にかかるところで、私のほうからお答えします。それぞれの目的に応じた減免の考え方というのを持っているというところが、その減額・免除の考え方というのが、深く追究すべきだと考えています。 全体的には体育館の会議室ということ自体が、あまり普通の会議ができないという枠になるみたいに認識されているような状況で聞いています。だから、このような状況になっていると考えます。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"利用率に入っていなくて、料金も払わなくて、その場所を自由に利用しているという状況なんでしょうか。料金として発生するかどうかはともかく、きちんと手続を踏んだ上で使うべきではないかと思うんですけれども、そこはどのようにお考えか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"それと、目的外利用ですけれども、区立体育館も区民の体育、スポーツおよびレクリエーションの振興を図るという目的の区立施設です。そのために、それについて利用するという形で、スポーツ以外のお話だとか、そうしたものはうちは受け付けてはございません。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"きちんと手続を踏んで使って、利用率としても挙げてくるべきだと考えるのですが、いかがでしょうか。今のご説明を聞いていると、何か記録が残ったり、何で体育館の会議室はそのようになっているのかなというのをもう一度わかるように説明を求めました。","respondent":"安藤文化スポーツ振興課長","answer":"事務局としてはすぐレスポンスよく受け付けをして、それでそんなに頻繁に限られた３時間の貸出し時間をフルに使うということもございません。そんな中でのミーティングというようなものも、そこでも利用しているという形で利用しています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"最初のご説明だと、わかれば使いたいという人も出てくるかと思いますが、区民からの要望があれば使えるという意味でよろしいんでしょうか。区の施設ですから、なぜ体育館だけそういうイレギュラーな運用になっているのかがちょっとまだわからない。","respondent":"安藤文化スポーツ振興課長","answer":"今後、会議室の利用率の確保のためには、さまざまな観点から検討が必要ではありますけれども、今のところそんな形でなってあります。それは使っている形で先ほど説明させていただきましたけれども、次の方が来て、連盟の方が来て。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"今、座敷だけというか、畳の部屋だけのシルバーセンターというのは幾つぐらいあるんでしょうか。わかりますか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"昨年度から、この和室につきましては使いやすい形で持っていかなければならないだろうということで、私のほうとしましては検討をしています。あるんですが、一概に和室がどうかというような議論につきましては、今後詰めさせていただきたいと考えています。","id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"大きな改装だけではなくて、ちょっと高さのある机や椅子を入れるだけでも大分改善はあると思いますので、その辺はぜひご検討くださればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"施設的なそういう状況も含めて、土・日・祝日のところは八潮は全部ゼロになって、スポーツ室が夜間２ということで、５.４％になっている。そのあたりのカウントの仕方がどうなっているのか、やはりちょっと性格的に分けたほうがいいのかなと思いますとの意見を述べました。","respondent":"久保田地域活動課長","answer":"昼間は児童専用で開放していますので、一般利用がございませんので、ここはカウントとしてはゼロになっているということです。ですから、そういう形で表現していますので、夜間については貸出し等を行っていますから、貸出しの数はカウントされているということです。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"スポーツ室・遊戯室・談話室は児童センターの管理する施設ですから、改めて確認したわけですけれども、意味が違うのではないかと思うんですけれども。施設の一つ一つの部屋の利用状況だから別にいいですけれども、その辺がちょっと正確ではないかなと思って、気になったので。","respondent":"久保田地域活動課長","answer":"〔「その説明がなかったから、ごめんなさい」と呼ぶ者あり〕はい。","id":"exchange-017"},{"speaker":"井上副委員長","kind":"質問","question":"資料ありがとうあります。ここを見直すに当たって、そういうところの分析も含めてやらなければいけないと思うんですけれども、その辺の問題意識はお持ちか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"数字の部分で回数だとか率とかというのは見えてきて、高い低いというのがトータルで見えてきたところがあります。ほかの近くにある施設だとか、それから地域の方の団体の状況だとか、そういったところをトータルにもう少し深く調査をすべきだと思ってあります。","id":"exchange-018"},{"speaker":"井上副委員長","kind":"意見","question":"割合だけではなく、そういった分析を含めて、ぜひ見直しの参考にしていただくようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-02","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"それを踏まえて質問をさせてほしいと求めました。４年間やってこられたと思うんですけれども、４年間試行をされた評価というのはどのようなことをお考えになっているのか、説明を求めました。","respondent":"立川経理課長","answer":"これまで４年間に、件数といたしましては１件から２件という少ない件数で実施してまいりました。実施によって他団体の動向であるとか、今回の本格実施に向けて、その少ない機会というのが有効に活用できたと考えております。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"確認","question":"その中で、原則として１件２,５００万円以上の工事というのがあるのですけれども、これは年間で何件くらいを予定されているのか。これは、もういわゆる建築、土木、設備といった、これは全ての分野にわたるのか、それについての確認をお願いいたします。","respondent":"立川経理課長","answer":"平成２６年度につきましても同等数を見込んでいるところです。２,５００万円というのが、２,５００万円というところがきりのいいということで、この金額になっております。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４年間の試行期間で、先ほどの話だと５０件前後予定をしているということで、かなり評価が大変になってくるのではないかと。これを今から始めるということですから、やはりその中で公正な評価を求めているというところがあると思うんですけれども。","respondent":"立川経理課長","answer":"先ほどお話ししたのは、２,５００万円以上の工事が何件くらい見込まれるかということで、５０件前後かなというところをお話ししました。まず契約担当者と、いわゆる工事主管課のほうと協議して、実際に適用するかどうかというのは決めていきたいと考えております。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ということは、全てに適用ということではなくて、１件ごとにいろいろ検討しながらということになるわけですか。そういうところで点が入らないということなのか、実績というのは何を指すのか、教えてほしいと求めました。","respondent":"立川経理課長","answer":"現在考えている実績ですが、こちらにつきましては、いわゆる災害時、またゲリラ豪雨や台風のときに災害対策本部ができます。そうした中で、災害対策本部の要請に従って対応していただいたというところを、実績として評価していこうと現在は考えてあります。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"確認","question":"もしかすると所管が異なってしまうので、私が知っている企業でも、それについてはちょっとまた防災課のほうとも私も確認したいと思います。これはどういうものを参考にされたのか、言える範囲で、教えていただける範囲で教えてほしいと求めました。","respondent":"立川経理課長","answer":"何点にするかというところは非常に大切な部分だと考えましたので、他区の調査を実施しまして、導入区が千代田区を除いて試行または本格実施です。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員会でもこういうことも求めていましたし、調査もされたということなので、流れとしてはよくわかりました。そういったものを支店としてみなすのかどうかというところで、そういったものを排除するという考え方なのかどうか、教えていただければ。","respondent":"立川経理課長","answer":"事業所としてその届け出た住所等が実際に機能しているかどうかというのは、経理課の職員が実態調査を実施しているところです。当然連絡がとれない、品川区としては、そういった場合は区内業者として認定しないという扱いをこれまでも実施してまいりました。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"経理課のほうで確認をされていらっしゃるということなんですけれども、本店とか支店の所在の年数によって点数を変えたりしているんですね。品川区は、そこはしっかりと実体があるのかどうかという調査をやられているということで、よろしいか尋ねました。","respondent":"立川経理課長","answer":"まずはそういった業者については排除できると考えていることと、あと、やはり経理課のほうにもご連絡いただいているというところがあるんですね。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それは区民のためになるということでありますので、しっかりそこは立入調査も含めて、引き続き行ってほしいと求めました。契約というものにはもちろん求められますし、それと、ここのところはしっかり事業者が感じられる適用をしていただきたいとお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"原委員","kind":"意見","question":"２２点という何とも表現がしにくい数字を出した、その辺のところについて、そこをご説明ほしいと求めました。","respondent":"立川経理課長","answer":"そうすると、実際にこの計算式に合てはめると、理論値の満点が２０点となります。その他で２２点ということになりますので、５０％ずつという配点ですので、理論上は技術と地域貢献の割合を多くしたというものです。","id":"exchange-028"},{"speaker":"原委員","kind":"意見","question":"外していくという表現がよくないのかな。これからだよというのであれば、それはそれで結構なんですけれども、もしお考えがあればとの意見を述べました。","respondent":"立川経理課長","answer":"一事業者として当然これからも実施していく考えであるということは聞いているところですが、最近はエコアクション２１というのが環境省の推奨とか。","id":"exchange-029"},{"speaker":"原委員","kind":"質問","question":"これに関しては逆に言うと評価を出すほうですから、内部で要は考え方として、品川区はＩＳＯではなくて今度独自のものでいくわけでしょうから。現実に所在がなければだめなのかどうなのかというのは、どうかなという思いがあるものですから、もう一回お考えをほしいと求めました。","respondent":"立川経理課長","answer":"区の考え方としましては、やはり品質というものがそれに伴わないということになりますと、かえって利益を損なうということになります。今回の総合評価方式を実施していくわけですから、品川区のある土地のところで活動してもらうということが大切なことだと考えているところです。","id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうは要望だけにしておきますけれども、どうかなという、私個人としてはクエスチョンマークなんだよという。ですから、ほかの業者は全部ネットでつながっているわけですから、その辺をお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"１つ目、２,５００万円以上の工事が５０件前後ということで、何か基本的な考え方があるんでしょうか。その3)、これで０.５点とって、これでもう０.５点丸々よという形になるのか尋ねました。","respondent":"立川経理課長","answer":"昨年から工事実績の評価を実施して、工事成績評定を実施しておりますので、実績がないと７.５点という点数になります。考え方としましては、この辺の改正されました育児・介護休業法の内容についてはしっかり実施していただきたいというのが、こちらの考え方です。","id":"exchange-032"},{"speaker":"あべ委員","kind":"確認","question":"１つ目のほうの協議の上というのは、不利なところが出ないような場合には適用するというようなイメージでよいのでしょうか、確認です。3)のほうはどれか一つというよりは、要求が高まっていけば、そういうのは自動的に応じていくことになっていくのか尋ねました。","respondent":"立川経理課長","answer":"１点目の、法律が改正されるごとにこちらも連動していくのかですが、こちらは現在、当然法律に従ってハードルというのは上がっていくと考えています。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その成果がこの４月からもう出てくるということで、これが成り立ったというのは、委員会として非常にすばらしい形になったと思います。その上で、苦情審査の関係が出ていると思うんですけれども、そこら辺はどういうふうに考えているのか、その１点だけもう一回確認したいと思います。","respondent":"立川経理課長","answer":"苦情につきましては、実際に工事成績評定において、苦情の申し入れにつきましては取り扱いが決めてありますので、その中でしっかり対応していきたいです。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう一度すみませんけれども、外部委員の加入とか第三者評価委員会という話も出ていたと思うんですけれども、その辺は検討状況だけで進めていくんか尋ねました。","respondent":"立川経理課長","answer":"こちらのほうにつきましては、もし苦情があった場合には、苦情審査委員会というのを副区長をトップに実施していくとなっているところです。必要に応じて専門の臨時委員ということで、外部の方をお招きするということを現在考えているところです。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"１１月に審査したときにそういう趣旨の発言をしたんですけれども、テーマでしたので、そんなふうに振り返ってみて思うわけです。どういうふうにこれが次期のときに持っていかれるかは議会運営委員会の議論なんですけれども、その辺について正副の考え方を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"今回はまとめ、提言ということなので、そこには持ち込まなかったというのはそういうことで、議長への報告には載せていったということで確認をしておきたいと思ったのですけれども、そういうことでいいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"意見","question":"行財政改革特別委員会の活動現況についてがある。議題になっている部分の契約のあり方に関することは、これで十分まとまっているのではないかと私は判断して、これに賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"}]},{"id":"topic-03","title":"(1)の御殿山小学校西側敷地の活用計画（案）","agenda":"(1)の御殿山小学校西側敷地の活用計画（案）","exchanges":[{"speaker":"南委員","kind":"提案","question":"２点目は、１万m2くらいの建物が可能だという中で、もう漠然として何も区のほうとしての意思はここには入ってこないんですか。図書館も今度指定管理者制度になりますので、いわゆる公が直営する施設というのは何も想定していないのか、その辺についても伺いたいと思いますとの意見を述べました。","respondent":"柏原行財政改革担当課長","answer":"説明のほうがちょっとはしょるような形で申しわけございませんでした。この部分につきましては区立大崎図書館という考え方をそのまま維持しますので、その部分については公設のものという捉え方をしています。","id":"exchange-039"},{"speaker":"南委員","kind":"提案","question":"ですから、もう一度検討するべきだと思っていますので、住民サービスの関係で見解を伺いたいと思います。しかし平成３０年ですからあと数年先なので、その辺についての考え方、ぜひ私はいろいろな角度から検討していただきたいと思うんですとの意見を述べました。","respondent":"柏原行財政改革担当課長","answer":"大崎図書館につきましては、委員から今ご案内いただきまして、区の中でも利用率はかなり高いほうだと私のほうも認識はしています。そうなってきた場合、それ以外に残りの部分を別のところにお貸しするという考え方を持たず、１つの事業者のところにお願いしようと思っています。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"この地域にない特別養護老人ホームも視野に入れていけるのかなとすごく期待を私はするわけなんですけれども、そういうふうに捉えていいんですか。ですから、そういうことをしっかり見ていただいて、残すからいいんだということにはしないでいただきたい。","respondent":"桑村企画部長","answer":"どういう施設をお願いするかということがありまして、一定の検討の中で、やはり教育の中では図書館が有効であるという考え方がまず一つありました。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"新たな事業が展開できるということですから、やはり、しっかりと住民要求を最大限の一番中心に置いて捉えていただきたいと思うんです。もう最後にしますけれども、やはり特別養護老人ホーム、これはしっかりとつくっていくという角度で、強くお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これから委員会のほうにまたいろいろな話も出てくると思いますけれども、次の委員会あたりには基本的な考え方が出てくるんでしょうかというのが１点。賃貸していく中でどのぐらいの金額になってくるか、それも次の時点ぐらいに出てくるのか、その２点だけ教えていただきたい。","respondent":"柏原行財政改革担当課長","answer":"次回の委員会ぐらいの時期には公募の案ということでお示しをさせていただいて、ご意見等をいただければと考えています。賃料等々につきましても、現在ちょっと精査していますので、そういったところも含めた形で、ご報告できるようにと考えています。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今度の件に関しては、行財政改革特別委員会の判断でいいんですか。それともやはり厚生委員会と、その辺の絡みだけは確認を。","respondent":"桑村企画部長","answer":"これはもちろん議会側とご相談しなくてはいけないです。今の区のほうの考えでは、調整がつけば３つの委員会でかけさせていただきたいと思って、ご意見をいただきたいと考えているところです。","id":"exchange-044"},{"speaker":"あべ委員","kind":"提案","question":"この建物でなければいけないとは言いませんが、このエリアにあるべきではないかと、あってほしいと考えています。そういったものも、ぜひ活用の計画を検討する中では考慮に入れていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"１点目のほうです。この施設でできるかどうかというのはちょっとありますけれども、周りの施設も含めて、そういったことにも考慮はしていきたいと考えています。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。それが今は区の土地ということになっておりますけれども、ぜひまた住民の人たちがいろいろ広く使えるところにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"提案","question":"１点だけ確認なんですけれども、ほかの事業者と組んで別のものをご提案するということも考えられると思うんですが、もうこれは現段階でそういうことは考えられるんか尋ねました。","respondent":"柏原行財政改革担当課長","answer":"いろいろ考え方はできるとは思うんですけれども、あまりその権利関係を複雑にしたくないというところが片方ですので、今、公募条件は最終的に精査をしていますけれども、余りそういった形で転貸であるとか、そういったところは今のところは想定はしていないということです。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"確認","question":"リニア新幹線の出入口のすぐ近くということもありますし、いろいろな可能性が考えられると思うんですね。公募というのはそういうことなのかどうか、もうそういうことで考えが決まっているかどうかというのは確認したかったんですけれども。","respondent":"柏原行財政改革担当課長","answer":"基本的な考えというのは、まず、まずそれができる事業者ということが大前提であります。ただ、今のところ想定していますのは、そういった介護老人保健施設がきちんと運営できるところをまず前提に考えるというものです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"確認","question":"確認できました。一定方向性があるということは確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"井上副委員長","kind":"質問・要望","question":"この定期借地の契約で成功事例というか、品川区が検討するにあたって参考にしているようなところの事例があれば、紹介をしてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"それからあと、東京都のほうでも事例が幾つかあるということで、調べて調査しているところです。そういったところも参考にしながら、今回の公募の要件も詰めていきたいと考えています。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/705937?Template=document&Id=5964#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":51378,"voices":137}},{"id":"h26-20140417-17","meetingId":"h26-cm04","date":"2014年4月17日","dateIso":"2014-04-17","committee":"震災対策特別委員会","time":"午後１時００分～午後２時５４分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"国道１５号線徒歩帰宅者支援対策の実施","agenda":"国道１５号線徒歩帰宅者支援対策の実施","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そうなると、初めの３日間はどうなるのか、それともかかわって４日目以降という意味合いというのはどういうことなのか、そこも伺いたいと思います。逆に「今日は無理して来なくていいです」と、いろいろな体験をこの間積んでいるわけですけれども、そことの兼ね合いで伺いたいと思います。","respondent":"鈴木防災課長","answer":"それぞれのどの時点に対応するかですが、協議会を設置して事前の取り組みをする部分が、まさに予防の対策です。ただし、直接被災をしなくても同様の状況が起きた場合には、当然この対応が応用できるという考え方です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここも大きな柱になってくるのかと思いますけれども、その点改めて伺いたいと思います。そして４日目以降、モデル実施の対象としているのがどういうスキームなのか、そこをご説明ほしいと求めました。","respondent":"鈴木防災課長","answer":"この対策の想定としてピークとなる３日目以降というご説明をしましたが、これは人数を具体的に想定しているものではございません。一番多いときに対応できる体制を組んでおけば、またスムーズに通過して徒歩帰宅者が減ってきたときにも十分対応できるという意味で。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＪＲが責任を持って対策すべきだと思いますけれども、必要な対策を求めていくのか、そこを伺いたいと思います。それが発生抑制につながっていくと思いますけれども、この点についてはどうお考えなのか、伺いたいと思います。","respondent":"鈴木防災課長","answer":"配布したりする件についてですが、これにつきましてはまだ協議会が設立されて、これからさまざまな対策や取り組みについて検討します。その様子を見ながら、今後の啓発、情報提供については検討していきたいと考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ改めて現状も伺いたいと思いますし、どういう支援が必要なのか、トイレについて伺いたいと思います。平成２６年度この協議会が動き始めますけれども、パブリックコメントをぜひ位置づけてほしいと求めましたけれども、いかがか尋ねました。","respondent":"鈴木防災課長","answer":"もちろんどういう支援が必要かという視点では、直接ここに入っていただくという予定は、今のところ協議会のほうでは意見は出ておりません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"今は総合車両センターですか、鉄道事業者は乗客の方々が初めの３日間、その点改めて伺いたいと思います。鉄道事業者のほうだけ、改めて伺います。","respondent":"鈴木防災課長","answer":"委員おっしゃるように、鉄道事業者の役割、また事業者としての責任は大きなものがあると、区としても考えております。この協議会は、この中で関連する鉄道事業者に伝えて対応をとっていただく必要があるものが出てきた場合には、連携していきたいと考えております。","id":"exchange-005"},{"speaker":"伊藤副委員長","kind":"確認","question":"ここは１,１００名ぐらい入るスペースがあるので、相当大きな協力を得られる可能性があると思うのですが、そのことのお考えを確認したいのと。例えばホテルだとかありますけれども、どういうお声がけをして、企業なり協力者を集めたのかということを説明を求めました。","respondent":"鈴木防災課長","answer":"これは区のほうで設置しています地域と事業者と行政機関でつくる防災の訓練やいろいろな対策を考える会議です、この方にまずはお声かけをして。ご指摘がありましたような、今後しっかりとお声かけをして、協力いただける場合には参加をしていただくということで考えております。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"単純に場所として提供していただくだけなのか、その辺のところもちょっと教えていただきたいので改めて。大田区の協議会との連携のあり方とか、その辺についてはどのような考えになっているのか、それを説明を求めました。","respondent":"鈴木防災課長","answer":"国道１５号線の徒歩帰宅者の支援ですが、また緊急車両や本来の道路としての機能に影響がないかというようなところもこれから検討してまいりますので。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"その辺、もし何か情報があれば教えていただきたいのと。もう既にそういうお声をいただいたようなところとかは、今現在どのぐらいあるのか、わかったら説明を求めました。","respondent":"鈴木防災課長","answer":"具体的にはこれから対策を考えてまいりますので、協力いただく内容が確定した時点で、協定でお願いするようなことになるかとは予定しております。そういう支援をしていただくときの協定、またそのために区が支援なり負担するべき内容も、ぜひお願いをしたいと考えております。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/865934?Template=document&Id=6450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":16672,"voices":38}},{"id":"h26-20140512-6","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"区民委員会","time":"午後１時００分～午後１時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"のふれあい掲示板の建て替え","agenda":"のふれあい掲示板の建て替え","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"ガラスですが、ガラスの強度はどうなのかというのが１点お聞きしたいのと、名前だけ書いてあってもわからないのではないかと思うのですよね。その２点をお聞きしたいと思います。","respondent":"久保田地域活動課長","answer":"一般のガラスよりも割れにくい状況になってございまして、業者とも話をしておりますが、そういった意味では強度は十分あるということです。いろいろな分野の、そういった中での活用が図れればということで、まずはこういう形で学校名を表示させていただいたというところです。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問・要望","question":"強度があるということで、安心しました。これは要望なのですけれども、せっかくここに避難所を挙げたので、工夫していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域情報の発信拠点としての機能向上というふうに理由の１つ目にありますけれども、この意味合いというのはどういうことなのかを伺いたいと思います。財源ですけれども、４,９００万円という予算ですが、これは一般財源か尋ねました。","respondent":"久保田地域活動課長","answer":"防災等の面でも今まで以上の情報発信の機能を向上させていきたいと考えてございまして、今回集中的に建て替えを行っていくところです。財源ですけれども、こちらは一般財源ということです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"通常４８３カ所あるわけですけれども、町会にお願いするとどうしてもタイムラグがあるから、いろいろなこと。あらかじめ計画を立てて、同時に進めていただきたいと思うのですけれども、その辺はいかがか尋ねました。","respondent":"久保田地域活動課長","answer":"これに一斉に張るのは難しいということは我々も十分認識しているところでございまして、段階的な対応はとっていきたいと考えています。ＱＲコード等についても我々は十分認識していますので、ＱＲコード等も活用しながら、そういった形で展開していきたいと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"ＱＲコードは、もちろん震災が起きたときもそうですけれども、日常的にいろいろなイベントだったり企画だったり、そういう要素があったり、逆にちょっと場所がわからなくなったときの地図だったり、いろいろな情報で活用できると思いますので、幅広くご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"山元委員","kind":"質問","question":"１つ目は、それから先ほど、町会とも相談しながら移転するというお話がありました。そうした場合、移動しましたよというのをどんなふうにお知らせするのかというのをお聞きしたいと思いますけれども。","respondent":"久保田地域活動課長","answer":"先ほども言いましたように、大規模な建設工事等があると、そこに置けなくなると、より近くのほうに移動するという形では対応しています。数ｍとか数十ｍ程度の移動と考えていますので、こちらに移りましたという方法については、何か工夫ができないか考えていきたいとは思います。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"そのようなお知らせをしていただくと、特にお年寄りは結構見ていらっしゃいますので、その辺をちょっと工夫してほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"の近隣セキュリティシステム「まもるっち」","agenda":"の近隣セキュリティシステム「まもるっち」","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"その考えを教えていただきたいのと、彼らが２年生になったときに、どういう扱いになるのかと。それを１年生用に戻して、２年生にはマモリーノ２を改良したものになるのか、説明を求めました。","respondent":"上垣外生活安全担当課長","answer":"これはおっしゃるとおり、協力者の拡大は当然必要なことだと考えておりますので、努めていくべきだと考えています。新しく入ってきた１年生に対して、あるいは音を制限するという機能を備えたものを、どんどん新１年生に貸与していくという計画であります。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問","question":"協力者の部分ですけれども、確かにお子さんが２人、３人いて保護者がという、保護者は２名、お父さんとお母さんがいる可能性もあるわけですね。会社が近くてとかいう可能性もあるわけですから、保護者というのはお子さんに貸与するわけですから、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、要するに導入してから、平成１７年以来、何回ぐらい変わっているのか伺いたいと思います。誤解のないように、随分変わるというところを伺いたいのですけれども、いかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"それ以降、ＫＤＤＩに入ってからは、今回が初めての機種変更ということになります。こういう体制そのものが、もちろん機種の変更については、このシステムそのものは引き続き継続していく必要があるのではないかと考えております。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"携帯１つとっても、気になってしまうから見てしまうというのもあるわけで、何かもっといろいろ考えられないのかと思ったのですよね。すぐわかる機能を伺うけれども、どんなふうにお考えなのか伺いたいのと、いかがか尋ねました。","respondent":"上垣外生活安全担当課長","answer":"これはこのまま継続していく必要がありますし、あるいは子ども１１０番であったり、悪い人間が品川区から退散していくというところにつながってくるのではないかと考えております。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"それがなかったら、これはどういう情報からわかったのかということをお聞きしたいです。お願いします。","respondent":"上垣外生活安全担当課長","answer":"例えばＰＴＡの会合等で、こういった危険があるのですよという話を伺いまして、そういったことで把握しております。加えまして、町会長あるいは町の方の声からこういった話を伺いまして、把握しております。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう情報というのはとても大切にしていただきたいので、そういうネットワーク的なことはどうなっているのでしょうか。そういう情報はどうなっているのか、横のつながりというのを教えてほしいと求めました。","respondent":"上垣外生活安全担当課長","answer":"町会長ともふだん接点がありますので、こういったところから情報を仕入れているところであります。私どものほうで子ども１１０番の事業だとか、教育委員会でやっております８３運動とあわせまして、ご協力いただいております。","id":"exchange-013"}]},{"id":"topic-03","title":"の品川パビリオン共同出展事業","agenda":"の品川パビリオン共同出展事業","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"というようなことをされているのかどうかというのを１点と、１１月なので何とも言えないと思うのですけれども、その点を説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"２,０００社ほどありまして、４月に宛名を出力して封書で全事業所に送らせていただくようなことで、ＰＲに努めているところです。１１月まで動向を見きわめますけれども、安心・安全の部分もしっかり念頭に入れて、この事業に対応していきたいと思ってあります。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"前と全く同じですけれども、品川とわかる独自の装飾を施したブースということですが、どんな工夫をされているのかというのを伺いたいと思うのですね。まいど１号だったか、しっかりと伝わるようなものが私は必要なのではないかと思うのですけれども、その辺はどうなっているのか伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"共同出展ということで８社のブースのスペース以外に、区の産業への取り組み、私どもの取り組みのＰＲをするようなブースもつくっております。","id":"exchange-015"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"中小企業センターまつりと、この非核平和都市品川宣言制定３０周年記念の関係がよくわからないのですけれども、３０周年ということでいろいろやるというお話を伺っていますが、どういう関係なのか尋ねました。","respondent":"米田商業・観光課長","answer":"非核平和都市品川宣言が制定されて３０周年ということで、この趣旨なり、広くＰＲしていきましょうということになっております。あるいはパネル等でそちらの取り組みについて、これは総務課との連携になると思いますけれども、ご覧いただければと思います。","id":"exchange-016"},{"speaker":"向副委員長","kind":"意見","question":"青森にどうしても行きたかったとか、この１年間の間にオリンピックの開催が決まったりですとか、違う場面でかかわれたらいいなと考えています。本当にありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248984?Template=document&Id=2694#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":18183,"voices":59}},{"id":"h26-20140512-7","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"厚生委員会","time":"午後１時００分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)の御殿山小学校西側敷地の活用","agenda":"はじめに、(1)の御殿山小学校西側敷地の活用","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ここは厚生委員会なので2)が中心だと思うんですが、その辺は全体としてどういうイメージなのか、ということが一つ。それから、今回、定期借地というところでは、第三者のメンバーがそこに入るのか、その辺はどういうイメージを持たれているのか尋ねました。","respondent":"大串福祉計画課長","answer":"それ以上のことについては、ちょっと私のほうからお答えはしかねるといったところです。定期借地５０年間ということの中でということで、何かできるものがあるかどうか、この辺も検討していきたいと考えています。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"設計に１年以上かかっているということで、５の(3)のところで、具体的にどういうイメージをしているのかということ。年間１回みたいなことを聞いているのですが、これは案ですから、その辺の状況を説明を求めました。","respondent":"大串福祉計画課長","answer":"６月上旬に公募を行い、１０月下旬までには事業者を決定すると考えておりますので、今後詰めてまいりたいと考えています。このスケジュールでいけば、この設計期間をある程度取ったうえで、平成３０年度の開設が無理のないスケジュールということで考えているものです。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"区施設および老健施設等の専有部分は２分の１減額とするというのは、応募がないだろうということなのか、ここの判断の根拠を説明を求めました。","respondent":"大串福祉計画課長","answer":"その際にも、貸付料につきましては２分の１減額といった手法を投じてやっているという形です。２分の１の減額を行うことによって、こういった形態をとっていると、このように考えております。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"当初、定期借地を使うときから、そういうことだったということでよろしいのでしょうか。そこら辺をちょっと、わかれば、ご説明をほしいと求めました。","respondent":"大串福祉計画課長","answer":"こういった形で５０年間の定期借地権を設定して、それをさらに他の行政需要に振り分けるということで、この手法を導入しております。２分の１の減額といったところで、区の大きな役割だと思いますし、この事業を円滑に進めていくためには必要な方法だと考えているところです。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"提案","question":"２点あるのですけれども、活用計画の(1)の3)のその他施設で、事業者提案に基づき検討、とあるのですけれども、これを取り入れたねらい。","respondent":"大串福祉計画課長","answer":"建築基準法の第８６条第２項にある制度でございまして、こちらにつきましては、近くにある建物を同一の敷地と見なして建設ができるという制度です。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"提案","question":"それをあえてこの事業提案ということにした考え方というのですか。いろいろな提案があると思うのですけれども、どういう考え方なのか、もうちょっと教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"これの２カ所目を整備したいといったところで、まずは老健施設を設置していただきたい、これが大前提になってまいります。そういったことを期待して、このような形で自由提案とさせていただいているといったところです。","id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も、活用計画の(1)の3)のその他の施設というところで、今のお話だと、特に区のほうから、こういうものというのは考えていないと。どういったものになるのかということもあると思うのですけれども、ここの面積がどれくらい余るのかというのは全く検討つかない状況か尋ねました。","respondent":"大串福祉計画課長","answer":"そうした中で、事業者のほうでまた上乗せが出てくるかもしれませんし、また、１００床よりはちょっと下回るような形で出てくるかもしれません。今の段階で、どれくらいの面積になるかというのは、ちょっとお答えはしかねるところです。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"老健も待たれていたものですけれども、ここに一緒に特別養護老人ホームがあるというのは、ほんとうに魅力的だし、これも待たれていることだと、私は思いますので、どんな提案が出てくるかわからないですが、そういった中でも、区としてぜひそういった方向で考えてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-02","title":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","agenda":"の品川区立高齢者住宅（借上型）グレースマンションの貸主の変更等","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"念のため確認なんですけれども、場所は２９号線がすぐに通っているところですか。所管が違うかもしれないですけれども、すぐ際になるかなと思うので、一応確認です。","respondent":"白鳥高齢者いきがい課長","answer":"住所からしまして、ちょうど横須賀線のところで、ここは当たってないかと思います。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"よくわからないのですけれども、平成６年に２０年間の賃貸借契約を結んで、新は平成３６年５月３１日までというのは、契約が間違っているのですか。突然１０年間契約期間が増えてしまっているようになっていますけれども、間違いということか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"これまでの２０年間、今年の５月３１日までの契約期間満了によりまして、こういった変更が生じたものです。今回、前倒しによって新しく貸主が変更になったということと、今後の再契約ということで、新たに１０年間を追加したということです。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"１０年間の契約変更というほうが随分大きなことというふうに捉えるのですが、契約期間が突然１０年間更新されたというのは、どうか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"この高齢者住宅の貸主が変更になったということで、資料的には、今後の入居者がどういう状況で住まわれるのかということも踏まえた中での契約期間というものを入れさせていただいたものです。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"前回は２０年間の契約を結びました、今回は１０年ですということについては、何か理由があるのか。その辺については、また契約を１０年しましたというところをどこかで報告をする予定で、このような形なのか、その辺の経過を説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"その辺のところは報告をさせていただきたいと考えていますが、これまで３棟、借上型の高齢者住宅の更新手続を終えてあります。今後につきましても、このグレースマンションにつきましても１０年間ということで、そういった根拠の中でお示しをさせていただいたものです。","id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"４番の理由のところに、２０年間契約をしたけれども、都合で１９年１０カ月で契約が終わってしまったということなのでしょうか。それから、都合により、ということは、どうしてこういうことになったのかわかれば、伺いたいのですけれども。","respondent":"白鳥高齢者いきがい課長","answer":"大体半年から１年くらい前、家主のほうから何らか区側のほうに、いろいろなことでご相談があるものだと考えているところです。私のほうでは承知しておりませんが、これから、こういうような状況につきましては生じてくるものだと認識しているものです。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうしたら、新しく株式会社カーマトラストになっていくというところでは、住民の皆さんにとっては、何も変更はないと考えていいのか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"現在、全てのお部屋につきましては、満室状況です。ここの巡回管理とあわせて夜間の管理人の設置ということで、入居者にとっては、より安心して生活できる環境を築いているものだと認識をしています。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"１年であろうと、何らかのペナルティがあるのかどうか、ということ。ちゃんと契約をしているのですから、説明が適切ではないのではないかと思うんですが、いかがか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"高齢者住宅の２０年前の契約書につきましては、きちんと取り交わしを、条文の中に入れさせていただいているところです。家主側とその辺の事情聴取は行った中で、きちんと引き継げるかどうかということを判断した中で、今回の変更ということで承認をしたものです。","id":"exchange-015"},{"speaker":"井上委員","kind":"確認","question":"ここについて、ちょっと確認なんですが、こういった場合の譲渡という場合には、貸主の双方のやり取りだけで区はオーケーをするのか、そこについて、どういうふうな区の関与の仕方、あるいは、そこに責任というものはあるのか尋ねました。","respondent":"白鳥高齢者いきがい課長","answer":"その辺のところにつきましては、やはり借地借家法という法律に基づくというものが大前提にあろうかと思います。特にひとり暮らしの高齢者住宅政策を進めるにあたっては、これによって今後の高齢者住宅を維持していくかどうかというところを判断するものです。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"最後に一つだけ確認させていただきたいのですけれども、要は貸主が変わるわけですが、今回契約の更新をされています。２０年前の契約があって、もしくはこういうふうに変わったところが何かあるのであれば、そこだけちょっと説明を求めました。","respondent":"白鳥高齢者いきがい課長","answer":"この変更に伴いまして、貸主が変わることによって、区のほうに何ら負担になることはございません。東京都が設置している要綱の趣旨に基づいた運営で、区に対する損害ですとか、そういったさまざまな問題は生じてこないという状況です。","id":"exchange-017"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"視察のところで、ちょっとだけ確認をさせていただきたいのですが、ここでよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"井上委員","kind":"意見","question":"２番の鮫洲なぎさの家のところで、外部サービス利用型指定共同生活援助というのは、どういうものか説明をしてほしいと思いますとの意見を述べました。","respondent":"中山障害者福祉課長","answer":"その中で、２種類あるのですが、一つが外部サービス利用型というものです。その２種類があった中で、今までグループホームの指定を受けていたところにつきましては、大方外部サービス型のこういった形態をとっているものです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"こういった品川区の名物というか、特産品というか、あると。もちろん、品川区の庁舎に来ればそういうものがあるというものを、ぜひ今後開発をしていっていただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"厚生委員会として要望してきたことが、私も一部だと思っていますが、ほんとうに嬉しく思っています。これからも、議会として区民サービス、そして利用しやすい事業なども一緒に提案しながら進めていけたらいいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/363412?Template=document&Id=3384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":15010,"voices":58}},{"id":"h26-20140512-8","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"建設委員会","time":"午後１時００分～午後４時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"」を聴取いたします。 初めに、(1)「東京港第８次改訂港湾計画の策定","agenda":"」を聴取いたします。 初めに、(1)「東京港第８次改訂港湾計画の策定","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"簡単に意見が述べられるということなのですけれども、このパンフというのはどこまで配られているのかということと、意見を募集するに当たってどういう周知がされているのかというあたりを説明を求めました。","respondent":"中村都市計画課長","answer":"東京都からこのパンフレットを余分にいただいておりまして、今品川区の都市計画課の窓口のところにこれをストックをしているというところと、それからホームページのほうでも当然のことながら周知をしているです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり関心を持っていただくというのは大事なので、ぜひ区民の皆さんの目に触れるようにしていただきたいなと思うのが一つです。品川区としては、都と連絡調整をするのがどこの部署なのかというのを教えていただきたいのと、交流ができる場がどのぐらいあるのかも説明を求めました。","respondent":"中村都市計画課長","answer":"一時、都のホームページのトップページにもあったようですけれども、その辺はホームページとあと各都内の行政庁のほうへ配付をしているです。それは今、現状ではこの１回の会ですが、また状況で港湾局と協議をしてまいりたいと考えております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つ要望なのですけれども、また道路計画とかもすごく品川区にとっては今回の第８次の中身というのは物すごく影響していく中身だと思うのですね。建設委員会の中で議論していくと思うのですけれども、ぜひ固まる前にきちんと話ができる場を設けていただきたいのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"都との役割分担的なものはあるのかどうか。品川区として独自に何かこういう要望等々が受けとめられるような、そういうことを展開する予定はあるのかどうかをお聞きしたいと思います。","respondent":"中村都市計画課長","answer":"ですので、今回の協議会と意見交換会の場が発言を、あるいは相手というか東京都港湾局に対して要望を上げていく唯一の場ということになってあります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"ここの品川区内での考え方というものも周知していく必要があるし、区民の皆様方からの要望なども今まで過去においてもあると思うのですね。そこをやはりまとめた形で、その部分についてはいかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"そういう中でこのバース等も含めて東京都の施設等を抱える区としてしっかりとこの計画に発言をしていく必要があるだろうと考えています。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから、それはぜひ今の話からすれば品川区長を通して都なりに対してご指摘いただきたいのが１点と、それから。その整合性等についてどこまで活かしていくかは別としても、やはりこういう席上で対処していただきたいと思うのですが、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"さらに規制緩和等を進めて、港湾計画等に少しでも水を有する品川区が主体的に物を考えて発信するようにできないか、このように常に考えております。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"大井のグラウンドが品川区からなくなることは事実でしょうから。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さまざまな意見をそういうところで伝えてくださるということを伺ったのですけれども、かなりあちこちで増えていくというところで受けとめていく。ぜひその辺を区長を通して風通しよく、お互いの意見を交流し合うというところをぜひ実現をしてほしいと求めましたが、いかがか尋ねました。","respondent":"松代防災まちづくり事業部長","answer":"そういうような中で、または国家戦略としての東京湾の中での位置づけ、そういったものを十分検討する中で進めてもらえると考えています。それを港湾局もまた警視庁もしっかりと受けとめて対応してくれています。","id":"exchange-008"}]},{"id":"topic-02","title":"中延一丁目区営住宅の建替えについて","agenda":"中延一丁目区営住宅の建替えについて","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ちょっとそこをお伺いしたいのと、ちょっとその辺を伺いたいのと、その辺も含めて説明を求めました。","respondent":"矢木住宅担当課長、品川木密整備担当課長","answer":"２１戸の住宅数のうちどれぐらい埋まっているかというお話なのですが、２０戸現時点で埋まっております。１戸はあきが出ておりますので、それはちょっと準備ができ次第募集をかけさせていただきたいと考えています。それから、同潤会、本当に近くで今やっているところですが、当然そこの受け入れ先としても考えております。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"同潤会のところはこの間質問した、ほとんど地権者の方のように私は受けとめていたのです。ちょっとこの辺を説明をしてほしいんですけれども。","respondent":"品川木密整備担当課長","answer":"同潤会の地区ですが、ほとんどは所有者の方と思っていただいて結構だと思います。しかし、一部にはあの手の住宅ですね、一戸建てで貸している部分もごく少ないですけれども、あるというような状況です。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今ご答弁いただいた一部住宅を貸していると、そういう人のためなのですか、ここに書いてある「借家人の移転先や仮住まい」と。ちょっとここにかかわってくるのかどうか教えていただきたいのと、それは近くに住めるということなのか、その辺の対策も説明を求めました。","respondent":"品川木密整備担当課長、矢木住宅担当課長","answer":"どちらかに出ていくというような形になるかもしれませんし、また新しい建物に居住するというような考え方もあると思います。今先行実施地区でやっている地区ですので、この地区の中でも移転があるかというところも… ２点目のご質問、近くに住めるのかということに対して回答させていただきたいと思います。そちらが要は基本的には受け入れ先となってまいりますので、ただ、お話は十分聞かせていただきたいと思います。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"最後ですが、説明会、本件報告後というのですが、もう大体決まっているのでしょうか。ちょっと、いつごろだとか。","respondent":"矢木住宅担当課長","answer":"私どもとしてはなるべく早く、５月末ぐらいまでにとは思っておりますが、そういった次第でもう少し先になってしまうかもしれません。ただし、遅滞なく行わせていただきたいと思いますので、よろしくお願いします。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"それが、それプラス２０から３０戸となっているのですけれども、さっきの区民住宅の募集もありましたけれども、やはり競争率高いんですね。そういう人たちを含めると、要望を聞いてからではなくてもう既にほかの要望もあるわけだからということを考えると、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"そもそも従前居住者住宅という考え方なのですけれども、例えば所有権者でないと入れないとか、そういう仕切りは特にはございません。規模のほうですけれども、その辺はちょっと今後ニーズ調査をしてから従前居住者部分に関してはやっていかなければいけないかなと考えております。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり借りている側がうまくいかない、どうしても折り合いがつかないよねという場合には、ある程度かかわって解決策を見つけていただきたい。改良というか少し要望がかなえられるような状況にもなるので、広い意味で考え直していただきたいなと思いますが、あれば。","respondent":"矢木住宅担当課長、品川木密整備担当課長","answer":"何度かこの委員会でもご説明申し上げているとおり、私どもの住宅施策のほうが居住環境の向上であるとか、現時点で増設等は考えてございません。よろしくお願いします。先ほどの借家人の問題なのですけれども、今ちょうど区で初めての防災街区整備事業をやっている荏原町の部分でもこういった例がございました。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"借家人に対しての対応については、介入できるものならばしていただきたいなと思っています。これからの区営住宅のあり方であるとか密集市街地の整備に関しても含めて一応考えていただいての建設をぜひお願いしたいと思います。","respondent":"藤田都市環境事業部長","answer":"ただ、耐震補強で区営住宅にもともと住んでいる方々の安全を高めるためのことで考えてございましたが、プラスで区としても考えるところです。こういうような考え方で木密地域の安全性を高めるため、この辺の事業を引き続き展開をしていきたいと考えています。","id":"exchange-015"}]},{"id":"topic-03","title":"木密地域不燃化１０年プロジェクトの推進～西品川２・３丁目地区での不燃化特区本格実施について～","agenda":"木密地域不燃化１０年プロジェクトの推進～西品川２・３丁目地区での不燃化特区本格実施について～","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとどういう状況で申請が出されるのかという基準を教えていただきたいのと、この西品川２丁目・３丁目、ここには住宅がどれぐらいあるのか把握をしていたら説明を求めました。","respondent":"品川木密整備担当課長","answer":"大体３から５％上げるぐらいの住宅の棟数を訪問していくというような、大きく条件を言いますと、大体そのところになります。住宅のほうは１,６４０棟となります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もしわかったら教えてほしいのと、その辺を教えていただきたいのと、昼間の１回だけですか。ぜひ複数回、それもお仕事をされている方が参加できるような状況にぜひ拡大をしてほしいと求めましたがいかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"地区につきましては、品川区としましても検討しまして、今後出すか出さないかも含めて考えていっている最中です。説明会ですが、まずは第１回目説明をしまして、まちづくり協議会とかもつくっておりません。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まちづくり協議会がまだないということなので、ぜひ地域の方との話し合いを密にしていただいて、安全な地域を作ってほしいと求めましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"西本委員","kind":"確認","question":"確かに木造ではなくなるので耐火性という形にはなってくるのでしょうけれども、それはそれとして、耐火性だからいいでしょうという考えなのですかね。中延のほうだと１つにまとめていこうという動きが出ていると思うのですけれども、更地だとありがたいですけれども、いかがか尋ねました。","respondent":"品川木密整備担当課長、藤田都市環境事業部長","answer":"何というのですかね、１つ１つの建売住宅が準耐火建築物で建てておりますので、防火性については非常に高いと考えています。ですので、そういった意味では… もう一つ、まちづくりを地域の皆様と一緒に考える中で、地域の皆様の声を聞きながら進めていく必要があるかなと考えています。トータルで燃えないまち、燃え広がらないまちをやはりつくっていくべきだと考えています。","id":"exchange-019"}]},{"id":"topic-04","title":"「品川駅南地域 まちづくりビジョン」について","agenda":"「品川駅南地域 まちづくりビジョン」について","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"Ａ４のところにまず、地元町会長連名により区へ要望書提出とか、あと構想の提案が住民から出されたとよくありますよね。まず大もとのところをどう捉えているのかちょっとお伺いしたいとの意見を述べました。","respondent":"溝口都市開発課長","answer":"一応区域内の町会長さん全てに１２月の意見交換会についてはお声かけをして、そういったところの対応をしていただいて開催しているものです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いつも同じ答弁を伺っていますけれども。区が自らやはりこのまちづくりビジョンに対して責任を持って説明をするというのはこの間ずっと求めているのですけれども、この辺、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"は区営住宅に住まわれる、その中からご意見等をいただきながら今回つくっておりますので、改めて説明会等を開催というふうには考えておりません。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そのこともきちんと位置づけてほしいなと思うのと、何ていうのでしょうか、その辺の必要性とか需要をどう考えているのか。公園もつくってほしいとか、地元の企業を育て発展させるような姿勢をぜひ持ってほしいと思うのですが、その辺はいかがか尋ねました。","respondent":"溝口都市開発課長","answer":"再開発事業等は進めてきておりますし、さらにこのプラン等、そういったものはしっかり説明しながら進めていきたいと考えているものです。実際どういう形での需要があるのかというのは細かくは検討していく形になるとは思いますが、羽田空港の２４時間化ですとか品川駅関連の強化。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"羽田２４時間で、もう品川はどんどんそういうのに求められていくのだというのに乗っかっていいのかという思いがすごくするのですよね。ちょっと大きなところだったのですが、その辺、ぜひ立ち止まって考えていただきたいなと思うのですが、いかがか尋ねました。","respondent":"溝口都市開発課長","answer":"そういうできるところであれば、まちの方針等を図っていく上での一つの解決策としては再開発事業というのは非常に有効な手段だと考えております。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何ていうのですかね、あとリニアの中央新幹線の開発もそうですけれども、こういうものに乗っかったときに便乗開発と言えると思うのですね。私はもうこれ以上の大型の再開発はやめていただきたいという意見を申し上げて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"やはり東京都との関係が当然出てくるのだろうなと思っているのですが、予算規模をどのぐらいの考えでこのビジョン策定になっているのでしょうか。どうやってって、何でしょうかね、何か興味がなかったら北品川のほうに来ないですよね。","respondent":"溝口都市開発課長","answer":"今後どういう事業が起きてくるのかというのが想定できませんと、ちょっと一概にこのまちづくりを全部やって幾らという形までの試算は出していません。このビジョンを策定するだけでいきますと、大体１,５００万円ぐらいの予算を使わせていただいてつくっているものです。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"１,５００万円かかるでしょうね、大体。ここの、こういうものができたのかなというところの経緯だけちょっとお願いしたいと思いますとの意見を述べました。","respondent":"藤田都市環境事業部長、溝口都市開発課長","answer":"品川区の景観計画、こういったものの中で旧東海道の重要性については十分認識をし、今後のまちづくりについていろいろ検討を進めているところです。その段階では、自主的なまちづくりの支援事業みたいなものも区の中でやっておりますの… １０ページに書かれている絵ですが、そういった中でこういったまち並みをつくれないか、そういったふうに考えているものです。","id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"ああいう事例をやはり伝えていただいて、ここの旧東海道だけではなくて、ほかの地域での成功例はあると思うのですね。いずれにしても、そういう意味ではつながっていくような形で回遊性を広く持たせるような形にぜひ実現していってもらいたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"失敗というイメージがもう私の中にあるものですから、それについてお答えいただきたいのと、前のページの９ページ。この辺をどういうふうに考えておられるか、初めに２点、お願いします。","respondent":"溝口都市開発課長","answer":"９ページのいろいろなゾーン分けの件ですが、当地域につきましては多種多様な顔があると考えております。大きくは５つ、それがちょっと入り組んだ形での配置になるというのがこの地域の、逆に特徴だと考えているものです。","id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"そういった中において、ただコンサルを使って地元の方々、当然地元が第一です。今後ですね、今すぐということではありません、今後においてのお考えがあったらば説明を求めました。","respondent":"溝口都市開発課長","answer":"もう一つ、まちづくりの地元の推進協議会の中にやはりディベロッパー等も入っています。特に重点計画地域についてはどのようなまちづくりが行われるのか、そういったものも一緒になって検討していきたいと考えているものです。","id":"exchange-029"},{"speaker":"原委員","kind":"質問・要望","question":"ですから間違いではないのですけれども、特にここは大事なスポットになってきますので、ビジョンを出していっていただきたい。ですけれども、行政、自治体として品川区の考えも出していっていただきたいので、その辺のところのご意見を伺いたいと思います。","respondent":"溝口都市開発課長","answer":"再開発事業というのは、再開発、特にまちづくり、それぞれ地域の特性等を踏まえて、いろいろさまざまな手法、さまざまな考え方等あると思います。","id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"あれば、そうしていけということではないのですけれども、そういった形のもののご意見があればいただきたいなと思ったので、その辺だけお願いします。一言で構いません。","respondent":"溝口都市開発課長","answer":"空中権の話もそうですし、容積の話とかいろいろさまざまな事情、またはその資金調達の仕方等はあると思います。そういったところも踏まえてこのまちづくりが力強く進むように、そのほうは今後検討していきたいと考えています。","id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問","question":"地域の方々は、当然商店街ですから、たくさんお客さんに来ていただいて、コストを回収したい。では東海道をどうするか、もう少しハードルを下げていくことも考えてはいかがでしょうかというのが１つと、あわせてご答弁ほしいと求めました。","respondent":"藤田都市環境事業部長","answer":"その辺の動きとも連携しながら、また進めていければと考えています。いろいろな情報収集をしながら、地域のまちづくりが一層進むように努めていきたいと考えています。","id":"exchange-032"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ちょうど今オリンピックが来たわけですから、やはりもう少し都市マスタープランの中で具体的にどう鮫洲、ぜひ将来に向けて検討してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-05","title":"しながわＥＣＯフェスティバル２０１４の開催について","agenda":"しながわＥＣＯフェスティバル２０１４の開催について","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"何でこの２体だけなのかなと。〔「３体です」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"これは何でしょうかという質問と、朋優学院だけではなくて、ほかのところもやっていたと思うのですよね。４番の自家発電というのはすごくいいことだと思うのですけれども、このチラシでエコ活用のことは書かれているのか、いかがでしょう。","respondent":"三ツ橋環境課長","answer":"３点目なのですが、この右の上に使用済み天ぷら油を回収しますということで、これがバイオ燃料のきっかけとなっております。この廃油を集めて、それを燃料にしております。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"一番上のイベント実行、３回やるようになりました、リーダー方式にしましたよと、今まではそうではなかったのですか。いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"１点目の、その中でやはりいろいろな議論があった中で、リーダー方式にしてもっと積極的に活用していこうということからリーダー方式にいたしました。申しわけありません、広げてこちらの右側の３段目なのですが、そのような形になっております。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"過去の３体はかなり全国的にも有名な３体になっていると思うのですね。そういうことも含めて活用できるものは活用していきたいと思いますので、意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"木村委員","kind":"質問","question":"それはどのようにしてまたその結果がわかるのか、感じ取れることができるのか。もしそれがわかれば説明を求めました。","respondent":"三ツ橋環境課長","answer":"そして、最後の区民の環境に対する認識ですけれども、そこで皆さんのＥＣＯチャレンジ宣言というものを書いていただいております。一人ひとりのＥＣＯに対する思い入れを書いていただくのと、またアンケートも行っておりますので、そちらで周知を図っております。","id":"exchange-038"}]},{"id":"topic-06","title":"焼却灰溶融処理施設の稼働休止について","agenda":"焼却灰溶融処理施設の稼働休止について","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"灰溶融処理施設の溶融炉休止ということですが、溶融しなくとも最終処分場の延命は可能だという判断なのですかということの質問が一つと。ランニングコストのカットになるわけだから、そのことについてのコストの考え方は何かあるのでしょうかということを、答えるよう求めました。","respondent":"小林品川区清掃事務所長","answer":"その後は２.４万トンぐらいに平成２８年以降は減ってしまいますので、それから逆算すると、６万トン弱の埋め立ての増が見込まれます。逆に、それがもしなくなったとしたら負担がその分かなり減るわけですけれども、経費想定からすると６０億程度の負担軽減が見込めます。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"意見","question":"それから、あと６万トンの埋め立て増になるのですよねとの意見を述べました。","respondent":"小林品川区清掃事務所長","answer":"承知いたしました。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"休止の捉え方を教えていただきたいのと、そういったもろもろの理由で灰溶融をやめてほしいなというところをずっと言ってきたので、その辺を聞かせてください。","respondent":"小林品川区清掃事務所長","answer":"今まで投資した設備を無駄にすることなく、場合によっては必要ならば稼働の余地を残した含みだというご説明を受けておりますが。具体的には平成２１年、これが１万３,０００トンぐらいに減るということでは、逆に環境負荷の低減効果もあると聞き及んでおります。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"役割が小さくなっているということですけれども、基本的には燃やすごみを、大もとを減らしていく、処分場の延命にかかわるあらゆることで本当にごみを燃やす部分を減らしていくというところをぜひ追求をしていく一環として考えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-07","title":"補助１６３号線（東急大井町線ガード下区間）事業説明会の開催について","agenda":"補助１６３号線（東急大井町線ガード下区間）事業説明会の開催について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"交通の混雑をする場所でありますし、あと区役所に来庁される区民の皆さんのことも考えると、かなり周知を丁寧にしてほしいと求めました。回覧、もうちょっと広範な皆さんに状況がわかるようなお知らせをきちんとしていただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"稲田道路課長","answer":"これも３商店街ありまして、大井一本橋商店街、大井サンピア商店街というところの方たちと事前に話はしながら回覧等は回していこうと考えております。何らかいい表示の仕方があればと考えておりますが、一応チラシのポスティング、このように考えております。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"裏面には、平成２６年度事業実施及び予定区間ということで赤い表示がありますけれども、重なるような開発とか工事とかがないのかどうか。そういうのも工事車両の回しや何かもすごく影響するので、その辺の把握とかはされていますか、どうか尋ねました。","respondent":"稲田道路課長、溝口都市開発課長","answer":"現在進めております再開発の交通関係におきましては、本当に事故が起こってはどうしようもありませんので、その辺はしっかりやっていきたいと考えております。今回、再開発でやっている、特に西品川一丁目地区の再開発事業に伴って１６３号線の整備というのを要求しております。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"高さがどのぐらいになるのか、それから工事中も、交通量も多いし人もたくさん通るし、どういう形になりますか。具体的にわかれば説明を求めました。","respondent":"稲田道路課長","answer":"これを今回解消しまして、完成時には４.７ｍを確保していきたいと考えております。交通の関係におきましては、十分注意して、検討しながら、並行しながらやっていきたいと考えております。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"そうならないように図っていただきたいのと、５差路になるのですかね、通りにくい。道路幅は今よりも大分広がるという認識でよろしいか尋ねました。","respondent":"稲田道路課長","answer":"道路幅員なのですが、都市計画道路の幅としては１６ｍなのですけれども、あそこの２６号線につながる部分が約３０ｍほど広がった形になる予定です。ただ、完成時はそういうところなのですけれども、現状が１２ｍという狭い道路ですので、十分交通の回しは慎重にやるようにします。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"１点だけ。あれはああいう形で大井町から来られる方が濡れないような形で行けるというふうに配慮できるようにはなるのか尋ねました。","respondent":"稲田道路課長","answer":"ただ、工事の状況状況によっては、ちょっと皆さんに周知しながら、ちょっと屋根がないですよという形になると。その辺は十分に現場を見ながら検討したいと考えています。","id":"exchange-047"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"２点ほど確認させてください。そこら辺の進め方の姿勢というか、そこら辺を確認しておきたいと思います。","respondent":"稲田道路課長","answer":"着手の予定なのですが、都を通じて国のほうへその前に申請していきたいと考えております。東急電鉄に委託して工事に入る前の段階におきましては、また工事説明会というのをやっていきます。","id":"exchange-048"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"当然区役所のすぐそばで、地域の皆さんのお顔もすごくよくわかるところだと思うので、そういった姿勢でやっていただきたいと。皆さんがここは希望するところだと思いますので、この長い期間工事が行われて無事故で進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-08","title":"しながわ水族館経営改善検討委員会取りまとめについて","agenda":"しながわ水族館経営改善検討委員会取りまとめについて","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"そこの検討会と、それからこの作業部会の関連と言ったらいいのですか。まず確認したいのが、その整合性について、まず説明を求めました。","respondent":"多並公園課長","answer":"昨年度、平成２５年度に経営改善委員会ということで、できることは平成２５年度から取り組もうということで検討してまいりました。今後このような改善の取り組みを行いながら、最終的なあり方検討というのをまとめていきたいと、そういうところで今考えているところです。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問","question":"だからといって、あそこでまさに再開発をすることは当然時間的に難しいです、できないでしょうから。それからあと、ここにある飲食店がないということについての対応をとるべきだと思うのですが、それをこれから検討していくということなのか尋ねました。","respondent":"多並公園課長","answer":"今回の連携策の中でも、商店街と連携を図りながら、各商店街を回りながらＰＲイベントをして盛り上げていこうと。そういう考えのもとに現在企画しています。","id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問","question":"もう少しビジネスモデルを検討していったらいいのではないでしょうかと思うのが１点と、それから、先に聞けばよかったのですけれども。最も基本的なベースが何となくぼやけている感じがするのですが、いかがでしょう。","respondent":"多並公園課長","answer":"まずはちょっとここから着手して進めていきながら、できる部分は今後もモデルとして、今進めているところはあります。ただ、今回まずはやってみようと思ったところが、先ほどちょっと申しましたようなところで順次進めていきたいと考えているところです。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"そうしたら、予想外に人が来てしまったというほうもあるわけではないですか。ビジネスモデルは最大限確保していくといったりということが、そういう方向に進めていかないと厳しくなってくると思うのですが、いかがか尋ねました。","respondent":"多並公園課長","answer":"もちろん教育施設から出発して、当時のモデルとして今のような形で民間に任せながら成功した事例だと思います、進めてまいりました。今進めているところでいうと、そういう取り組みがあるので、それも終わった後に貸し出すということでやっている事業です。","id":"exchange-053"},{"speaker":"伊藤委員","kind":"意見","question":"それぐらいの思いでやっていただいて、十分検討していただきますようお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どうしたら来たいというところにかみ合うのかなという工夫がいろいろ要るのだろうなと思いますが、不便なのですよね、あそこまで行くのに。この間コミュニティバスの運行とかもいろいろ区民の皆さんから願いが出ていますけれども、いかがか尋ねました。","respondent":"多並公園課長","answer":"ただし、実態の中で、荏原の巡回のほうの利用が非常に低く、平成１１年にはそのルートを廃止するような形になった経緯もあります。現在も運行をしながら進めているところですので、なかなか過去の経緯と今も含めても、今のような形で進めていきたいという考えです。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"過去の経緯はこの間も１回お伺いしたので、行きたいけれどもなかなか行けないという方たちのために、ちょっと工夫を考えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"西本委員","kind":"提案","question":"先ほどからの飲食物の販売に対して改善提案というのが出ていますけれども、サンシャインから言われているこれはどういうことを想定しているのかな。施設的にどうなのだろうなという部分があるのですけれども、そこらを検討材料に入れてもいいのではないかなと思うのですが、いかがか尋ねました。","respondent":"多並公園課長","answer":"そこと今詰めている段階ですので、今日いただいた意見も含めながら、もうちょっと検討を深めていきたいと考えています。考えたところでしたので、それについてはアイデアをいただいて、もうちょっと検討の中で入れながら進めてまいりたいと思います。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"割引券ですからいい宣伝材になると思いますので、そういうことも考えていただきたいと思って、これもお願いいたします。人寄せパンダではないですけれども、なるのではないかなと思うのですが、いかがか尋ねました。","respondent":"多並公園課長","answer":"そことの関係とサンシャインとの関係がある中で進めているところですので、だめではないですけれども、今のところそういう形で進めているところです。","id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"それになるように、ちょっと行政側としては配慮していかなければいけないのではないかと思いますので、ぜひ研究をしてほしいと求めました。意見だけちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"}]},{"id":"topic-09","title":"平成２６年度の水防訓練の実施について","agenda":"平成２６年度の水防訓練の実施について","exchanges":[{"speaker":"西本委員","kind":"質問","question":"訓練内容は、新たに加わったものというのはどれになりますか。いつものですけれども、今回新たに取り入れられるというものはありますか尋ねました。","respondent":"加藤防災安全担当課長","answer":"どちらかというと消防のハイパーレスキュー隊が行います救助、つるべ式という、そこに隊員が行って溺れている方を助けるという工法を展開します。これは去年ない訓練です。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"毎年ちょっと内容が違うのですよね。ボランティアの方々も増えるのではないかと思うのですけれども、その辺の通知とかＰＲとかは何か考えてあるのか尋ねました。","respondent":"加藤防災安全担当課長","answer":"水防訓練を実施するということはお知らせはしておりますけれども、特段会場の関係で見に来てくださいという形ではご案内はしてない状況です。そういったことをあわせて見ていただければと思いますけれども、現在のところは町会長を通していただくという形をとってあります。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"何かもったいないなと毎年と見ていると思うのですよね。私たちもなかなか伝え切れない部分があるので、ぜひこちらからも積極的にしていただきたいなと思いますので、今後考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/978343?Template=document&Id=4104#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":64326,"voices":180}},{"id":"h26-20140512-9","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"文教委員会","time":"午後１時００分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"平成２５年陳情第９号「子宮頸がんワクチン接種事業の見直しと、健全な教育を求める」陳情","agenda":"平成２５年陳情第９号「子宮頸がんワクチン接種事業の見直しと、健全な教育を求める」陳情","exchanges":[{"speaker":"本多委員","kind":"意見","question":"結論を出すべきだと思います。性道徳につきましては、現行でやっていることを継続していただければいいと考えていますので、強化するという部分は必要ないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"塚本委員","kind":"意見","question":"結論としては、不採択です。その点については現状されているもので、子宮頸がんワクチンを勧奨するかどうかということにつきましては、不採択としたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"大倉委員","kind":"質問","question":"態度は不採択でお願いします。先ほどから皆さんあるとおり、強化というところでは現行どおりされているというところで、不採択でお願いいたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"その不採択の理由は、健康の問題と性道徳の問題は別次元の問題だと思っています。したがって、この趣旨には賛同しかねますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"高橋委員","kind":"意見","question":"結論を出すということで、不採択です。そういった教育活動全体の中でそういうことを実施されていると思いますので、強化云々というところについて、やはり不採択という形になると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-02","title":"(1)平成２６年度新入学学校別増減要因一覧","agenda":"(1)平成２６年度新入学学校別増減要因一覧","exchanges":[{"speaker":"南委員","kind":"質問","question":"１点だけ、私立よりも公立を選んでほしいということが言われたかと記憶しているんですけれども、どんな感じなんでしょうか。公立学校を選んでいただけているという効果、あるいはそのあたりのことをちょっとお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"例えば小学校は区立でも中学校は私立に行かせるような意志の親御さんも、例えば第１志望は私立でも、何が何でも私立ではないよと。やはり公立、私どもの中学校を選んでいただけるというのが、年々人口の増加とともに増えてきているという傾向はあるのかなと捉えているところです。","id":"exchange-006"}]},{"id":"topic-03","title":"平成２７年度品川区立学校教育職員採用候補者選考日程","agenda":"平成２７年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"後のところでも質問するつもりだったんですけれども、採用のときにもやはりそのことをきちんと問うという場面が必要なのではないかと思うんです。教職教養等々のあれなんですけれども、どういうふうに入るかはわからないんですけれども、位置づけていただきたいと思いました。","respondent":"渋谷指導課長","answer":"これは固有教員に限らず、品川区で採用する教員については全て指導課で面接をしております。こういった服務事故、そういった部分の資質については必ず質問をして確認をして、またさらに徹底してまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"高橋委員","kind":"質問","question":"前にもお尋ねしたんですけれども、模擬授業か、あるいはそれに類するようなことはやはり導入されていないんですね。そういう授業とか教科の力に関するものさしは、どのようにされる状況なんか尋ねました。","respondent":"渋谷指導課長","answer":"この第二次選考では、人物というよりも主に教科としての指導力等々がどの程度あるのかということについては、確認をして聞き取るようにしています。","id":"exchange-008"},{"speaker":"高橋委員","kind":"質問・要望","question":"幾つか必要な質問の中の、初めから授業をもうずっと４月から持たなくてはいけないということなので、そこを面接のほうで見てほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"一般選考ということですから、この経験者採用ということで、もうちょっと年齢のいった方で教職の経験のある方と。こういう採用の立て分けをしている考え方というのをまず最初にお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"特に経験者選考については、実績のある力、即戦力を求めたいということで、経験者選考の枠を広げているものです。一般選考はいわゆる新規卒業を対象として、約３０歳までの若い先生たちの補強という意味合いで、これは通常の採用という例年のことです。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"一般選考が未経験ということなので、そういう意味ではもっと若い、それこそ学校を出てすぐ新卒の方というのはあえて対象にせずに、昭和５８年、３０歳ぐらいということで切っているということは、そういう意味ではないんか尋ねました。","respondent":"渋谷指導課長","answer":"３０歳が上限ということになります。２２歳から３０歳までの方が対象ということです。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、新卒で未経験の方も採用されるということで、大体人数的には何かバランシングというのはあるんですか。一般選考と経験者選考で６人程度を採用しようという中で、それはその実際の応募を見ながらいろいろ決まっていくことになるんか尋ねました。","respondent":"渋谷指導課長","answer":"大学出たてが１人で、１人が講師経験のある方で経験者で、新規採用枠として採用しています。昨年度の申込み実績で見ますと、７６人申込みがあって、一般選考で４６人、経験者選考が３０人というような申込み区分になってあります。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、やはり品川は品川で、そこの教育環境にうまくなじめない方もいらっしゃるという話を時々聞くこともあります。そういう意味では、定員６名の中ではやや多目というようなことを志向されているのかどうかというところをちょっと最後にお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"やはり実際現場で１年、２年講師をやっていらっしゃるという形の方が多いですので、現場の経験があるということは非常にこれは有利です。ただ、その辺は柔軟な、今まで過去採用された方たちは非常にお力を発揮していただいているということが現状です。","id":"exchange-013"}]},{"id":"topic-04","title":"平成２５年度品川区立学校における体罰等の実態把握","agenda":"平成２５年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"南委員","kind":"質問","question":"実践されている先生の中で起きている問題ですから、研修し直すということは、同時に２回の調査の中でこれだけの実態が明らかになってきていると。教育委員会としては、こういう２回の調査を受けた結果をどういうふうに見ていらっしゃるのか、その辺をちょっと知りたいと思います。","respondent":"渋谷指導課長","answer":"皆さんもご経験があるとおり、やはり体罰というものに対する世間の認識そのものが大きく変わってきているというところが大きいのではないか。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"私は現場の先生方に、ぜひ研修の際でもいいですから、やはり教育委員会の側としては率直に聞いてあげるということをやってほしいと求めました。それから、そういう部分からでもいいですから、やはり現場の実態というのを状況把握するべきではないかと思います。","respondent":"渋谷指導課長","answer":"先ほど、体罰の研修の徹底についてご説明したところですが、実際該当した先生が２４名おりました。今年度新たに研修等を実施して、そういった角度からの体罰根絶を目指して、指導をしていきたいと考えているところです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"今、そういう説明があったから手を挙げたんですけれども、そういう指導の中で、忙しかったからと率直に言える人がどれだけいるでしょうか。そのことをちょっとお願いして、終わりたいと思います。","respondent":"田村教育次長","answer":"体罰については学校教育法の第１１条で、ただし、教員が多忙感があろうがなかろうが体罰はいけないことなのです。大人と子どもの関係なので、絶対にやってはいけないことだという形で強く指導しているので、引続き徹底させていきたいと考えております。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、建設的な意味でやってほしいと求めました。そういう角度でお願いしたいというつもりで、今までも質問をしていたつもりですので、その辺はよろしくご理解をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"高橋委員","kind":"質問・要望","question":"この１２月のときに報告したということは、なぜしたときに、そのときに言わなかったのかということを聞かせてほしいんです。周りの先生方が見られていたとしたら、なぜ１２月になってからここで言っているのかというところについて、ちょっとお尋ねしたいのが１つ。","respondent":"渋谷指導課長","answer":"その１２月の調査まで寝かしておくということではなくて、わかり次第、学校のほうは随時報告を上げてきているというものです。目安箱だったり、今後はそういった体罰の一つの抑止力として、そういったものも十分に活用できるのではないかと考えております。","id":"exchange-018"},{"speaker":"高橋委員","kind":"質問・要望","question":"改めて東京都のほうにここで整理してみたというような形でよろしいですか。それならば、やはり事件があったときに、そのまますぐ対応するのが一番だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"児童・生徒に質問用紙調査を行っているということなんですけれども、それを先生が回収するのか、どういったやり方なのか教えてください。そういうことはないと思いますけれども、そういうのをしっかりと明確にするために、違う回収の方法を考えたりというのはあるんか尋ねました。","respondent":"渋谷指導課長","answer":"それぞれ１年生から３年生、４年生から６年生、中学校用というように、発達段階に応じて質問用紙を配って対応しております。３０人のクラスで質問用紙が欠席者分以外足りないとかいうことになれば、今、委員のほうでご心配になるような点はないと考えているところです。","id":"exchange-020"},{"speaker":"大倉委員","kind":"確認","question":"再度確認なんですけれども、では例えば、欠席していたり何か事情でその調査票に記入できなかった子がいれば、改めてその用紙に書いてもらって、全ての子どもたちからの調査票がちゃんと人数分あって、それをもとにこうした報告書をつくっているということでよろしいか尋ねました。","respondent":"渋谷指導課長","answer":"はい、ご指摘のとおりです。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"細かいところなんですが教えてほしいんですけれども、小学校で４人（４件）とあるんですけれども、どういうことを指していらっしゃるんか尋ねました。","respondent":"渋谷指導課長","answer":"これは正当防衛と書いてあると、子どもが殴りかかってきた、身の安全を守るためというような感じに受け取られるんですが、例えば指導の中で、暴れた子の体を押さえつけたりする、そういった正当な行為がこれに当たるものです。","id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"残りについて、そういう体罰ではなくて、これは学校指導の中で必要な行為だったのかということがあると思うんです。そういうことはされておりますかとの意見を述べました。","respondent":"渋谷指導課長","answer":"こんなのもあって４９件と上がってきていますので、その辺の認識が必ずしもきちんとしていなかったという部分はあろうかと思います。ですから、これはいわゆるよくない先生の行為なんだよということをきちんと映像で理解させて、ということは今回全校で一律実施するところです。","id":"exchange-023"},{"speaker":"塚本委員","kind":"意見","question":"しっかりお互いが納得できて、これは体罰ではないというような形にちゃんともっていけるようなフォローも必要かと思いますので、そういった点を含めてお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-05","title":"品川区立幼稚園・品川区立小中学校における指導要録の取扱い","agenda":"品川区立幼稚園・品川区立小中学校における指導要録の取扱い","exchanges":[{"speaker":"本多委員","kind":"質問","question":"この指導要録の２０年保存、５年保存とあるんですけれども、この指導要録の項目というのがどういうものがあるのか。普通に考えるのが出欠状況とか成績とか、そういったところだと思うんですが、その項目を説明を求めました。","respondent":"渋谷指導課長","answer":"指導要録につきましては、学校教育法施行規則第２８条にきちんと残さなくてはならないという、国の法律的な位置づけに基づいて定められた文書です。進学先、当時の学級担任の名前、それから当時の校長名等々を記録するものです。","id":"exchange-025"},{"speaker":"本多委員","kind":"意見","question":"当該校で収集をされて、ある程度もうこの４３９名分全部可能な作業になってくるのか、これからその取組はやるということなんですけれども。","respondent":"渋谷指導課長","answer":"先ほどご説明さしあげました様式２に相当する指導に関する記録の部分については保存をする必要がないものですので、それに対応できるものについては、今現在ある資料で十分復元できるものと考えています。","id":"exchange-026"}]},{"id":"topic-06","title":"浅間台および上神明小学校特別支援学級（固定級）新規開設","agenda":"浅間台および上神明小学校特別支援学級（固定級）新規開設","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ずっと児童数が増えてくるというところの対応では、それはそれとして必要なことだと受けとめています。これはどういうことなのか、ちょっと説明をしていただきたいと思っているんですが、その辺の仕分けも含めて教えていただきたいと思うんです。","respondent":"村尾学校支援担当課長","answer":"特別支援学級においても、特別支援学級で教える内容についても、より充実を図っていく。特に今度固定級が２つ増えることによって充実、個に応じた指導もより適切にできるのではないかと考えております。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"そういう４・３・２の括りがあって、どういう効果を期待してどういうふうになっていくのかなということが、ちょっとあまりよく見えてこない。難しいと、どういうふうに捉えたらいいのかというのがちょっとわからなくて聞いているんですけれども、質問したいことわかりますか。","respondent":"村尾学校支援担当課長","answer":"２点目、これはやはり小学校で特別支援学級で担任がいろいろな指導したことを、ここまでの学習をしている。当然その小・中が一貫というか連携をした教育によって、または適切な学習、生活が身につくということで考えているところです。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"当初からそういう目的を持ってやってこられたのかというところをちょっと確認したいです。そのことも含めて教えてほしいと求めました。","respondent":"田村教育次長","answer":"その基本方針の２に、小中一貫教育を推進し、質の高い義務教育を実現する、という項目があります。新しく改訂したものも旧も説明し、今回、その方針に沿って継続的な事業として取り上げた内容とご理解いただきたいと思います。","id":"exchange-029"},{"speaker":"南委員","kind":"意見","question":"ちょっと私もしっかりと事務事業概要をそこまで読めていなかったので、ありがとうあります。もちろん目標を定めていると思うし、そういうことなんだろうと思うんですけれども、そのことは改めて意見として言っておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]},{"id":"topic-07","title":"御殿山小学校西側敷地の活用","agenda":"御殿山小学校西側敷地の活用","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"確認をしたいと思うので、もう一度、申し訳ないんですけれども説明していただきたいというのが１点です。そのこともちょっと表明しておきながら、さっきの質問を伺いたいと思います。","respondent":"中元品川図書館長","answer":"こちらはものづくり経営支援課との連携事業でございました。この産業支援交流施設のほうに移されるという計画がありますので、その部分で、私のほうでは認識をしております。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"その理由としては、ですから全部の移転ではなくて対応していただきたいということを再三行財政改革特別委員会でも申し上げてきたし、そういう点で。取り上げるという表現は何ですけれども、なぜそういう選択にならなかったのかと思うので、そのあたりのことを教えてほしいと求めました。","respondent":"中元品川図書館長","answer":"行財政改革特別委員会での答弁の中でも、西口にそのまま何もないということでは企画部のほうでも回答はしていないかと思います。委員がおっしゃるように２つつくるという選択肢は、現状の区の施設展開の中ではなかなか厳しいものがあるのかなと考えています。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"それはどうなんでしょうか。地域の方々への理解を求める説明というのはされる予定があるんですか、ないんか尋ねました。","respondent":"中元品川図書館長","answer":"地域の方への説明ですけれども、今後の検討の中で考えていきたいと考えています。今のところ予定はございません。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"ビジネス関係の９,３００冊を引いても２１万冊ということで、もう少し練り上げる必要があるのではないかと思いますので、意見として申し上げたい。終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"大倉委員","kind":"質問・要望","question":"もしかしたら同じ質問になってしまうかもしれないんですけれども、その移転に変わった検討の経緯というのを教えてほしいと求めました。こちらの移転先になるほうとなくなるほうと、その辺について今後検討されていくのかなと思いますけれども、そこについてお知らせください。","respondent":"中元品川図書館長","answer":"今回のこのお話は、行財政改革特別委員会のほうでこういう話が議論・検討されているというところで私のほうにお話があって、それは区の方針として。地域への説明については今後企画部のほうとも調整しながら、どういう取扱いになるか、区で考えていきたいと思います。","id":"exchange-035"},{"speaker":"大倉委員","kind":"質問・要望","question":"うまくそういったことがないような連携をとっていただきたいというのと、いろいろな検討をして、説明はぜひしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-08","title":"東京都ひきこもりサポートネットによる訪問相談申込み窓口開設","agenda":"東京都ひきこもりサポートネットによる訪問相談申込み窓口開設","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"こういう事業を始めますよというのはどういう形でというのは、説明がなかったように思ったんですけれども、どういうふうになるんでしょうか。そういうことも含めて、ちょっと教えていただきたいという、２点です。","respondent":"福島青少年育成課長","answer":"できたらもっと早目に対応したほうがいいということは明らかだと思いますので、その辺は受け付ける段階では柔軟に対応していきたいと考えています。私どものほうも区報等を使いまして、ＰＲを６月に向けて行っていく予定です。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"じゃあ、その際、相談の受付電話番号のご案内を知りたいと思ったので、広報を見て知ろ、わかれ、そういう感じなんですけれども、教えてほしいと求めました。","respondent":"福島青少年育成課長","answer":"広報のほうでは、今ある電話、青少年育成係の電話番号をお知らせする予定です。ただ、これが専用ダイヤルということではありません。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"つなぐということですけれども、その後のフォローについて、区としてはどのような捉え方をされていらっしゃるんですか。ある程度連携をとって、東京都ひきこもりサポートネットから状況等の連携みたいなものはされるんか尋ねました。","respondent":"福島青少年育成課長","answer":"そういうことをやりますので、最終的にどうなったのかということは、ちゃんと東京都と連携して把握していきたいと考えております。","id":"exchange-039"}]},{"id":"topic-09","title":"平成２６年４月の入園状況","agenda":"平成２６年４月の入園状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"入園できた方が１,７０６人ということで、これは入園率というのはちょっと計算がすぐできないので、何％ぐらいなんですか。それと、その方々が３月３１日までに何らかの形で、その結果が７７２人と理解していいのかどうかをちょっと確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"父母や祖父母、職場のほうで見ていらっしゃるところが８人、それから認可外の保育施設が４０人弱という形になっております。内定者率は、子どもの児童数が、今、乳幼児人口が１万８,３５９人が４月１日ですので、在園児率は３５.９７％になっております。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"入園できた１,７０６人は、申請者の数の何％かというのをちょっと知りたかったので、それを質問したところですので、後でいいので、すみません。知人だとか預け先のことを教えていただいたんですけれども、もう一つ伺いたかったのは、教えていただきたい。","respondent":"今井制度改革・待機児童対策担当課長、竹田保育課長","answer":"１２８人の方の就労の形態です。１２８人のうち、常勤の方が５９人、パートの方が２８人という形で確認しております。 入園申込みに対する入園決定した者の率というお話ですが、６８.７％になっております。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"品川地域等々幾つかあると思うんですけれども、その地域で分類してみたときに、一番厳しかった地域というのは１カ所なのか。あるいは１カ所というのも面的に大きいと思いますけれども、そのあたりのことをちょっと教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、品川区では待機児童が２倍になったことからもわかりますように、全地域で待機児童のほうは、八潮地域以外いらっしゃる状況です。その中でも、やはり荏原地域のほうが待機の人数が半分程度を占めている状況になっておりますので、お答えとしましては荏原地域です。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"その辺をはっきりさせておきたいと思っているんですけれども、改めてそこを伺いたいと思います。荏原地域でずっときているのか、あるいはほかの地域もあったのか、大崎地域はどの程度なのかというのを教えてほしいと求めました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"地域的な割合ですけれども、今お答えしておりますのが地区別の待機児童数の割合の中で、今、半分程度が荏原地域です。八潮と分けますと、荏原地域がいつもこの筆頭で、４割程度の待機児童数の数を占めているところです。","id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"株式会社立、１人少ないというようなマイナスのところが１園あったんですが、プラス４人ということで定員をオーバーしている実態があると。４園は開園していただいたけれども、３歳以下の子どもさんに対応するには、そのあたりについての見解というのはどうなんか尋ねました。","respondent":"竹田保育課長","answer":"定数のご質問ですが、保育の定数の弾力化、それから既存施設の有効活用、それから民間活力の有効活用など、さまざまな施策をミックスしながら、今、この事態に対応しておりますので、今後もこの方向性で進めていきたいと考えております。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"区の見解を聞きたいのは、４月に入れなかった状況の中で、その辺を端的に伺いたいと思っています。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、この荏原地域がやはり待機児童が多い中を受けて、保育ママの開設を６月に年度途中ですけれども早めていくということを一つ検討しています。","id":"exchange-045"},{"speaker":"南委員","kind":"質問","question":"保育ママが６月にオープンするにしても、５０人を吸収できるぐらい保育ママをつくるんですか。やはり一定の規模の認可保育園をつくっていく必要があるのではないかと思うんですけれども、そういう認識はないか尋ねました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"やはり０歳から２歳児というのはそれぞれの定員枠がありますので、保育ママと同じような人数配分になってくるかと思います。それから１５人という形で、定員３３名という形ですので、引き続き今後も開設については前向きに検討してまいります。","id":"exchange-046"},{"speaker":"南委員","kind":"確認","question":"したがって、やはり認可保育園ということが最低の品川区の責任でやるべきなのではないかと思うので、私は保育ママでは十分ではないと思うんです。その辺についてはどういうふうに親の不安を解消する立場に立っているのかというところは、改めて確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"入ってから２歳で満期になるまで、途中で１年で退所するということは、区または事業者からはやっておりません。いわゆる０歳、１歳、２歳の３年間の保育です。","id":"exchange-047"},{"speaker":"南委員","kind":"意見","question":"その９人というのは年齢ごとの定員と考えていいのか、３年間で９人ではないということですよね。ちょっとこの辺を整理してくださいとの意見を述べました。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ですので、０歳児が９人の場合もありますし、０歳、１歳、２歳とバランスよくなる場合もあります。大体年度当初４割近くの方が在園継続しますけれども、６割ぐらいは新しい方を受け入れているというのが、ここ数年の現状です。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"そういう方向も含めて検討するべきではないでしょうか。やはりしっかりと子どもを保証し、親の就労を保証するという本来の役割を大事にしていただきたいと思うので、そのことを強く求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋委員","kind":"意見","question":"１つお尋ねしたいんですけれども、時間的にどうしても家庭訪問できないという場合には、どのように対応しているかということです。２点ですとの意見を述べました。","respondent":"渋谷指導課長","answer":"それは適宜ご希望に応じて三者面談等の対応をというふうにさせていただいているところです。時間外にどうしてもという場合については、出たものについてはそういったもので補償するような形の対応をさせていただいているところです。","id":"exchange-050"},{"speaker":"高橋委員","kind":"質問","question":"そうではなくて、その時間に実施するかどうかというところの共通認識というか、その辺はどんな形で小・中学校のほうに徹底されているんでしょうか。それとも学校ごとの判断か尋ねました。","respondent":"渋谷指導課長","answer":"授業をカットしてやりますので、その中でお願いしていくというところまでしか、教育委員会としてはお願いできないかなというのが限界だと考えています。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/510624?Template=document&Id=4822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":47847,"voices":145}},{"id":"h26-20140512-5","meetingId":"h26-cm05","date":"2014年5月12日","dateIso":"2014-05-12","committee":"総務委員会","time":"午後１時００分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"平成２６年度区政モニターの委嘱","agenda":"平成２６年度区政モニターの委嘱","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２期までは延長可ということなんですが、そこの中身も教えていただきたいのですが、そこら辺の応募の状況についても教えてほしいと求めました。モニター集会の５回はどういう中身でされてきたのかということを教えていただきたいのと、その点についても教えてほしいと求めました。","respondent":"荒井広報広聴課長","answer":"４回目は高齢者施策についてということで、主にこちらは元気な高齢者対象事業についてということで行いました。１つ１つについてのご意見というよりは、そこで出された意見の概要といいますか、代表的なものについてはご案内させていただいているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"要望、提案等を区政モニター通信用紙で寄稿するということになっているのですけれども、そのことについてもお聞かせほしいと求めました。応募者が７２名で委嘱数が５０名なんですけれども、どこでどういう形で選んでいるのかということについても教えてほしいと求めました。","respondent":"荒井広報広聴課長","answer":"２カ月に１回あるモニター集会などのアンケートを通じてお声をいただくこともありますので、そのくらいの感じであるかなと受けとめているところです。先ほどご説明させていただきました地域別、荏原、モニターを決めていくという形をとらせていただいているところです。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"今回このアンケート調査に対してそういうふうに思うのですが、いかがでしょうか。その辺のお考えを説明を求めました。","respondent":"荒井広報広聴課長","answer":"生活状況とモニター集会の実施状況がなかなか一致しにくいというところがあるかと思っています。２期まで延長についての考え方なんですけれども、１期でおりるには、また様子を見ながらそういったことを検討していきたいと考えているところです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうしてほしいということと、できるだけ幅広くアンケート、モニターに参加してほしいと求めました。人口が今３６万人いて、５０でさらにこういう年代別で分けると、この５０という数字の根拠は何なんですかね。","respondent":"荒井広報広聴課長","answer":"そういったときの運営のことを考えますと、５０人くらいが、そういう意味では最大限かなと考えているところです。それが１つの根拠となって進めているところです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"一生懸命モニターの調査をされているのはわかるのですが、１歩でも２歩でも幅広く、もしいただけるようなシステムをつくれればありがたいと思います。要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"１つお伺いしたいのと、こちらと同じような年代の人数と構成ですか、何か作為的なところを感じてしまう。この２点、まずお願いします。","respondent":"荒井広報広聴課長","answer":"平成２６年、平成２７年につきましても、日曜日の開催を１回、平成２７年は未定ですけれども、ウイークデーの昼間以外の開催を予定しています。今後工夫してまいりたいと考えています。","id":"exchange-006"},{"speaker":"浅野委員","kind":"意見","question":"それで、ホームページを見ますと、区政モニターを引くと、更新日が２０１２年１月１０日になっているんですね。ホームページの件だけは、ぜひとも更新を、新しくしていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"私も伺っただけなんだけれども、そのモニターの方から言われたのは、もうちょっと直接区長と話ができる機会があってほしいなと。年に１回か２年に１回か、そういう場面をつくってほしいと言われたのだけれども、どういうふうに位置づけていらっしゃるのか説明を求めました。","respondent":"荒井広報広聴課長","answer":"その後、それから最後の離任式のときも区長が話をさせていただいて懇談する機会というのが、年に最初と最後の１回ずつ設けているところです。今後、工夫していきたいと考えています。","id":"exchange-008"},{"speaker":"つる副委員長","kind":"質問","question":"幅広い１つの場所というか、触発というか、そのアプローチの仕方はもう少し工夫していく必要があるのではないのかなと思います。２０代の声、またそれをどういうふうに反映していくかということにもつながると思うのですけれども、それを説明を求めました。","respondent":"荒井広報広聴課長","answer":"２０代の声、２年前になりますが、タウンミーティングの小規模の形での実施というのを行いました。私どもの所管ではありませんが、２０代、学生の世代の声を受けとめていきたいと考えているところです。","id":"exchange-009"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今ご答弁いただきましたので、そういったところを含めて、ぜひモニターとして参加できるように工夫していっていただきたいなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"品川区電子メール配信システムの充実","agenda":"品川区電子メール配信システムの充実","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"ある意味拒否するというような形をとったほうが、使ってもらえるケースも多いのかなという気もするのですけれども、この点はいかがでしょうか。特にそのまま移行することに問題がなければ、このような手法を使っていただければと思うのですけれども、その点を説明を求めました。","respondent":"荒井広報広聴課長","answer":"登録の仕方ですが、こちらは今１９種類の情報を用意させていただいたところです。大変お手数なところもあるのですけれども、緊急情報あるいは防災気象情報等の配信をさせていただきたいと考えているところです。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"その他の気象情報にしても、かなり要望というのでしょうか、そういうのを希望される方は多いと思います。減らす方向ではなくして、増やす方向で考えていただけないかなということですが、いかがでしょう。","respondent":"荒井広報広聴課長","answer":"お手数をおかけいたしますけれども、ご自分の必要な情報は何なのかということを選んでいただくのが、やり方としてはいいのかなと考えているところです。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/531035?Template=document&Id=1982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":15995,"voices":40}},{"id":"h26-20140513-14","meetingId":"h26-cm05","date":"2014年5月13日","dateIso":"2014-05-13","committee":"行財政改革特別委員会","time":"午後１時００分～午後２時２８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"御殿山小学校西側敷地の活用","agenda":"御殿山小学校西側敷地の活用","exchanges":[{"speaker":"南委員","kind":"提案","question":"本当に強い要望のあるところだったので、もう少し空きスペースはあるわけですから、そういうことで提案するのであれば。４点目になってしまうのかしら、募集要領が６月上旬には公表になるわけですけれども、まだ発表していないのですから十分内容の変更はあり得るとの意見を述べました。","respondent":"柏原行財政改革担当課長","answer":"ビジネス支援部分を除いて１,３００m2ということでありますから、面積的にも逆に充実を図るようなイメージを持ってあります。利用率も高いというところではありますので、今後、所管部門と調整をしながらそういったところは詰めていきたいと思ってあります。","id":"exchange-001"},{"speaker":"南委員","kind":"提案","question":"今の説明では事業者がどんな提案をしてくるのか期待したいという話なんですけれども、そういう状況ではあるのではないかなと思っているんです。特養と保育園、この２つに限って聞きますけれども、住民のニーズがどういう状況になっているかという区の認識を伺いたいと思いますとの意見を述べました。","respondent":"柏原行財政改革担当課長","answer":"それから保育園、待機児童の関係であるとか、そういった課題があるといったところは認識しています。特養とか保育園を排除するということではなく、そういったところも含めて事業者の提案を受けていく中で進めていきたいといったものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、やっぱり重く受けとめて、事業者に期待をするのではなくて品川区のほうから発信していくということをやっぱりやるべきだと思うんです。そこをもっとしっかり受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"提案","question":"だから、それはぜひ１００床を越えての提案もスムーズにできるような形を工夫してほしいと求めましたし。そういった意味では、現段階で何か考えていることがあれば教えてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"書き方になるのか、説明会のときのしゃべり方になるかはあれしまして、そこはきちんと伝えていきたいと思っています。文化教育的な部分で何かできないかという検討はしていますけれども、セットのというお話もありましたけれども、何かお話しできる状況ではないです。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"ああいったものもぜひ、そういったところで活動されている方をさらに育てるような形でも図書館については考えてほしいと求めました。ほかのご質問もあるでしょうから、私からは以上で失礼します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"基本的にこの考え方は進めていっていただきたい中で、地域の方からお話があったのが、会合ができる部屋がほしいということが伝わってきました。ただ、そういう要望に応えるためには地域貢献の中での部屋が多分出てくると聞いているんですが、その点だけ１点説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"やはり同じように、そういった会合等々ができるような部屋があったらいいというお話は聞いてあります。それから運用関係とも調整しながら、そういったところで何か工夫はできないかという部分は所管部門ともあわせて検討しています。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、せっかくすばらしい施設をつくってくる中で、地域の方から、後でそういう問題が残らないようによく考えておいていただきたいというお願いをして、これは要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"提案","question":"先ほどの自由提案のところなんですが、これは近隣の状況から好ましくないとか、そういったものが現時点であれば教えていただきたいのが１つです。その点を考慮いただけるかどうか、考え方とですね、２点伺えればと思いますとの意見を述べました。","respondent":"柏原行財政改革担当課長、桑村企画部長","answer":"それからあと、図書館の部分です。その建てる建物の地域の特性とかいうのを考えながら、図書館の所管の部隊とどういった工夫ができるかというのは考えていきたいと考えています。ビジネス図書館の部分は品川地区の産業支援交流施設としていきますので、そういうようなお話をさせていただいているので。","id":"exchange-008"},{"speaker":"井上副委員長","kind":"意見","question":"すいません、図書館の件についてなんですけれども、今、移る側の声は聞いているようですけれども、新規のほう。現在の大崎図書館の利用者と近隣の住民の方たちの反応について説明を求めました。","respondent":"柏原行財政改革担当課長","answer":"ただ、利用者が多いというところがありますので、そういったところは考慮していかなくてはいけないだろうとは思ってあります。今後、どういった形で周知等々についてはやっていくかというところも含めて、検討していきたいと思ってあります。","id":"exchange-009"},{"speaker":"井上副委員長","kind":"質問・要望","question":"２０１３年の予算特別委員会で、ＰＴを立ち上げ、準備をしていますという答弁をしています。プロジェクトの議論と、また全体の議論をどうされてきたのか、説明をしてほしいと求めました。","respondent":"柏原行財政改革担当課長","answer":"主に企画部門で検討を進めてきたところではありますけれども、ほかにもこの敷地についてはいろいろな検討をしてきたところですけれども。","id":"exchange-010"},{"speaker":"井上副委員長","kind":"質問・要望","question":"せっかく新しい施設をつくっていくという意味では、当然行われるべきことだと思いますので、それはお願いをしたいと。資料はまた改めて違う部分で請求をさせてほしいと求めましたけれども、時間がないので、お伝えをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"質問するつもりはない、本当は質問したいんだけれども、でもこのメンバーでの委員会は今日が最後じゃないですか。２時半ぐらいには帰ってくることになっているので、それで質疑を継続できるようにしていただけないかと思っているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"山元委員長","kind":"質問・要望","question":"〔「賛否というよりも、時間があるかどうかだけ。当初は終わるのが２時半ごろということでありましたので、南委員からもう一度というお話があったものですから、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須藤委員","kind":"意見","question":"予定どおりで。３０分、４０分もかかっているんだから、終わってからやる必要はないと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"南委員","kind":"提案","question":"私がそういう提案をさせていただいたのは、先ほどの発言の中にも、４５分という時間しかとっていなくて非常に短いと。ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"１人ずつお願いしていいですか。〔「１人ずつだよ、あそこ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"私は予定どおりに進んでいただいて。ですから、具体的なことが出ていないのに、これ以上のことを話し合っても私は意味がないと解釈しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/705937?Template=document&Id=5966#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":17563,"voices":50}},{"id":"h26-20140515-17","meetingId":"h26-cm05","date":"2014年5月15日","dateIso":"2014-05-15","committee":"震災対策特別委員会","time":"午後１時００分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/865934?Template=document&Id=6452#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":1926,"voices":8}},{"id":"h26-20140609-6","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"区民委員会","time":"午後１時００分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この事務事業概要の本といいますか、冊子についてお伺いしたいんですけれども、今回こういう形の印刷物で出てきましたけれども、前回か前々回ぐらいのときはちゃんとした本みたいな形で出てきたと思うんですけれども、これは年度によって変えていくというのはあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"もう一点お伺いしたいんですけれども、改めてオリンピック・パラリンピック担当もつくって担当課長も置いたわけですけれども、改めましてその辺の区の考え方等についてお伺いしたいんですけれども。","respondent":"小川オリンピック・パラリンピック推進担当課長、中川原地域振興事業部長","answer":"そして地域振興事業部のほうにオリンピック・パラリンピック推進担当課長が設置されたものです。周知活動を実施していたんですけれども、本年、品川区としては万全の体制の組織体制にしたです。先ほど私のほうからご説明しました長期基本計画の改訂の中で、オリンピック・パラリンピックを２０２０年に控えたということも、議論がされました。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"個人番号カード担当ですか、どう充実されているのかをひとつお聞かせいただきたいのと、もう一回教えてほしいと求めました。本当にごみ屋敷の問題はこういう形で取り組んでいただきたいと思っているところですが、あわせてお聞かせほしいと求めました。","respondent":"久保田地域活動課長","answer":"この係長１人で全てのことをやることはできませんので、当然地域支援係との連携、そうした課題に対応していきたいと思ってあります。例えばごみ屋敷の課題を１つ挙げますと、それぞれセクションごとに対応していましたので、なかなか遅々として進まないといった現状もあります。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"体制のところは、そうしますと、去年からはそういうふうに新たな部署が設けられたということなんですけれども、職員の人数そのものの体制というところでは、増えているのか、変わらないのか、その体制についてもお聞かせほしいと求めました。","respondent":"中川原地域振興事業部長","answer":"そして検討していくんですが、区民の方にとって、区がこういう課題に積極的に取り組みますという１つのメッセージになります。今回新しい設置した係は、そういった意味でのこの問題に取り組む象徴的な係ということで、ご理解いただければと思います。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一体どういうふうになっていくのか、どうその個人情報が守られていくのかというところがすごくわかりにくいものだったんですね。今日は事務事業概要ということなので、これだけのものですけれども、そこのところはこの委員会でご説明いただけるということになるのか尋ねました。","respondent":"井浦戸籍住民課長","answer":"個人番号制度全体につきましては全庁での横断的なプロジェクトチームを組みまして、全庁的に進めていくということで、区として取り組んです。このカード交付につきましては来年の１０月から具体的に日程が組まれてありますので、区民委員会に報告したいと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは本当にさまざまな問題が想定されるものですので、ぜひこのところにしっかりとご説明いただきたいということは要望させていただいて、とりあえず終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"当初予算一覧のところなんですけれども、予算書との関係で、歳入とかどういうものを拾って、ここに入れてあるのか。歳出だと事業費だと思うんですけれども、この一覧がどういうところなのか、ご説明をほしいと求めました。","respondent":"久保田地域活動課長","answer":"これは予算書の中から引っ張ってきますが、歳入の主なもので言えば、例えば集会所の使用料が入ったり、あとは総務費の中の手数料が入ってきたり、それぞれの所管の中で歳入として調定しているものを、この中では歳入という形で入れているものです。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"歳入は使用料とか負担経費とか、そういうところで実際に得た収入ということで、あとは歳出のほうは、事業に合わせてというもので拾ってきてあるということで理解をすればいいのか尋ねました。","respondent":"久保田地域活動課長","answer":"予算書のほうは款別のほうで作成していますけれども、こちらのほうはその事業部、課別でやっておりますので、書き方としてはそういう書き方で、私どもの事業部で主に言えば、その使用料とか手数料とか負担金等の歳入がありますから、それらを収入として載せているというものです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、最大で２,０００万円までということで先ほどご説明があったんですけれども、町会の数は今２０４ということでいいのでしょうか。そこの２０４町会のうち、町会会館があるのは幾つぐらいなのかを教えていただけますか尋ねました。","respondent":"あべ委員長、久保田地域活動課長","answer":"その前に、本日の議題は事務事業概要の説明ということですので、個別の事業については、また別途ご議論いただければと思いますが、簡潔にご答弁をお願いします。 実際に実態調査ですけれども、地域のほうの説明も一緒に行って、町会・自治会の方々にご協力をお願いして、もう実際に動いているです。そのうち自治会が８ですので、町会としては７３町会が会館を持っているということです。","id":"exchange-009"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"結局、昨年の場合は、マイナス１５％を目標にということなんですけれども、昨年はどのくらいのマイナスになったかということは、行政の中ではおわかりか尋ねました。","respondent":"久保田地域活動課長","answer":"昨年の節電目標は１５％ということで掲げましたけれども、最終的には目標は達成できずに、１２.６％の節減だったです。","id":"exchange-010"},{"speaker":"井上委員","kind":"意見","question":"やはり平成１０年ぐらい、もう既に同じ事業が１０年以上たっているというところで、委員会としてもすべき項目ではないかと思います。何とか問題意識は共有されていると思うんですが、そこで、現状とかについての検討・調査が必要だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日ご説明をいただいた中身をもとにしながら、ちょっと時間をいただいて検討させていただいて、出させていただきたい。ちょっと時間的な余裕をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"やはり町会の支援についてのあり方というのは、いろいろ各委員から出てくると思うんですが、私はそこは入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本当に必要かどうかというところをもっと検討して、私はそんなに２泊３日で遠いところにこだわることはないと思うんですね。私は初めに遠いところに日にちを決めて２泊３日で行くのではなくて、必要性に応じてそういう考え方でいいのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"本多委員","kind":"意見","question":"仮に遠いところになれば２泊とかになる場合は、希望としては９月８日の週がありがたいです。別にこだわりませんが、希望だけちょっと言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"けれども、この２３区の中とかでもありますよね。場所はということで、２人の意見を伺って納得したという思いで、改めて言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あべ委員長","kind":"質問・要望","question":"この考え方はご理解いただけますでしょうか。例えば１週間がいいとか言われても、それはちょっとご希望には沿いかねるかなと、常識的なところでご理解いただけるかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"先ほど、本多委員のほうからもありましたように、やはり所管事務調査について議論をして、それからそれを深めるという形になっていくのがいいのかなという思いがあるので、ちょっと今どこにというのは、次回にちょうどそこを議論するということなので、そこのところで議論をするかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"やはりここにどうしても委員会としてはこれを深めるために委員の行政視察が必要だというところで初めて行政視察というのがあると思いますので、そういうことではない視察にしましょうということですから、可能なところに日帰りで行くということでいいのではないか尋ねました。","respondent":"あべ委員長","answer":"いろいろな考え方があると思います。情勢で時間切れになって行けなくなるということも、また皆様の全体の希望するところではないのかなと思います。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"所管事務調査が決まって、決めればいいのではないですかと言ったんですから、それでいいではないですか。せっかく言ってくださったんですから、それに照らし合わせてやればいいじゃないですかと私は思うんですけれども、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248984?Template=document&Id=2696#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":43274,"voices":93}},{"id":"h26-20140609-7","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"厚生委員会","time":"午後１時００分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"公明党のたけうち忍です。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"値上げの周知などはされているのか、どのようにされているのかを、ちょっと伺いたいです。去年伺ったときには、また引き下げますというような情報というのは入らないのかどうなのか、ちょっとお伺いしたいです。","respondent":"高森国保医療年金課長、永尾高齢者福祉課長、伊東生活福祉課長","answer":"平成２６年度のご通知ですが、６月１２日に発送予定です。周知につきましては、新しい冊子なんですけれども… ４月から６月まで、ひとり暮らしの高齢者、また高齢者のみの世帯の実態調査を行っております。世論調査も、今後、広報広聴課で計画をしておりまして… 基準額のお話ですけれども、国のほうは３カ年ということで、今、２回目ということです。","id":"exchange-002"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"区民に対してどういうふうにサービスをしていくのかというところでの重点課題と考えているものと、主なところでいいのですけれども、昨年から変わってきているサービス内容や利用料などの変更があった部分などを教えていただけたらと思います。","respondent":"榎本健康福祉事業部長","answer":"法制度等いろいろ検討されたうえで、法律が決まって、それを実施していくという段階になりますので。それからきちんと周知をして、区民の方に説明をしたうえで、諸々の事業の実施に当たっていきたいと考えております。","id":"exchange-003"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"なかなか今までにない観点で、こういう施策をやっているのはすばらしいのではないかということの勉強をするよう提案をします。これはまだなかなか資料がそろってはいないのですけれども、そのことも含めてご提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"提案","question":"地域包括ケアシステムの事例として、厚生労働省の地域包括ケアのホームページの自治体の事例として出ておりますので、そこをひとつ提案いたします。それから同じ障害者の芸術支援では、西宮市で社会福祉法人の一羊会、あとりえすずかけ、このあたりを一応ご提案させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"私どもとしては、今年度の厚生委員会の所管事務調査としては、障害児支援について、が１点。それから、介護予防を含む地域福祉について、ぜひ勉強していきたいということで提案しますので、よろしくお取り計らいのほどお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"提案","question":"障害者の芸術活動、もしくはアール・ブリュットというのですか、そういうこと。第二次プランが策定されますので、主にその部分についての調査ということで、一応三つ提案させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"意見","question":"病気がない健康な人に対してもいろいろと検討するという点では、まだやりがいややりようがあると思うので、健康づくりもぜひ入れてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"向委員","kind":"意見","question":"精神疾患等々と、障害者の支援、特に就労支援等に重点を置いて研鑽を深められたらいいということ。実際は結構大変なこともあるので、そのあたり、最後の１年でもう少し勉強ができたらいいかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"障害者も高齢化されているというところで、就労支援と、やっぱり生活支援のところができたらいいかなと思っています。国会でも議論されている部分で変わってくると、やっぱり高齢者福祉の日常生活総合支援といったところも、細かく見ていけたらいいかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/363412?Template=document&Id=3386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":46585,"voices":81}},{"id":"h26-20140609-8","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"建設委員会","time":"午後１時００分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目なんですけれども、どう受けとめていらっしゃるのか教えていただきたいのと、問題点があったら教えていただきたいと思うのがまず１点です。事業の評価をお伺いしたいのと、危険度の高い品川のまちをどう守っていくのかという立場でどう捉えていらっしゃるのかをお伺いしたいと思います。","respondent":"中村都市計画課長、品川木密整備担当課長","answer":"国家戦略特区、これからいろいろと具体的な検討に入っていくところですけれども、マスタープランはその基本になるところだと思います。全域の中で実際に品川区が国際化、あるいは… ５から４に落ちている地区等もかなり出てきておりますし、そういう面では、評価のほうもそういう形で出ているのかなというふうに思います。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はすごいその点が心配で、区民の要望との関係をどう調整をしていくのかなというところがとても心配なので、その辺の関係を教えていただけたら。例えば２９号線だったら６００億円、常にそう思っているんですけれども、そこのところはいかがか尋ねました。","respondent":"中村都市計画課長、品川木密整備担当課長","answer":"検討もこれからですけれども、それから純粋な観光者の誘致というように、さまざまあると思います。これから検討していくという中で、国益も非常に大切ではあるとは思いますけれども、しっかりと見定めていく必要があると考えております。あくまでも木密１０年プロジェクトというのは、それから特定整備路線という形で、あわせて進めていくような事業です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区の意向ということですから、その意見をしっかりと伝えてほしいと求めましたので、その点をよろしくお願いしたいと思います。補助２９号線の事業認可の取り消しを求める国土交通省への異議申し立て、１０１名の方、その辺を今日はお伺いしたいなと思います。","respondent":"中村都市計画課長","answer":"区も東京都に協力する形で、まちの人たちの意見なども十分汲み上げて、沿道のまちづくりなどを一緒に考えていきたいというふうに考えてあります。これはちょっと私ども区のほうでは、今のところ判断がまだできませんので、注視をしていきたいと考えています。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今年１年間、建設委員をやらせていただくので、まず今日は宣言をしておきたいと思っていますが、ぜひ、これからもたくさん声が出ると思うんです。東京都の求めに対して、ぜひ地域住民を第一にする考え方にぜひ切り替えていっていただきたいと、今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"」を聴取いたします。 初めに、(1)の「区営住宅入居者募集","agenda":"」を聴取いたします。 初めに、(1)の「区営住宅入居者募集","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"要綱を見たら、同居者が要件に入っているんですが、１人でも可能というか、そういう部屋が幾つかあるんですか。そこの要件がどうなのかということを一つお聞きしたいのと、もうちょっと早くお知らせをするということはできないのかどうか、いかがか尋ねました。","respondent":"矢木住宅担当課長","answer":"７月と１月に募集するということの中で、原状回復工事などを迅速に行いまして、地味ではありますが続けております。今後も続けていきたいと思います。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ努力を続けてほしいと求めました。その辺に対してどう考えていらっしゃるのか、どう改善をしようと考えていらっしゃるのか、一言聞かせてください。","respondent":"矢木住宅担当課長","answer":"町会、自治会から上がってきた情報、本日まで大体５００戸ぐらいあるやに聞いております。あき家であった場合、こういった民間のまだ十分に活用されていないストックを利用していければいいなというふうに私は考えてあります。","id":"exchange-006"}]},{"id":"topic-03","title":"の「「木密地域不燃化１０年プロジェクト」新規地区申請について」","agenda":"の「「木密地域不燃化１０年プロジェクト」新規地区申請について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"資料２のところで、これまでの取り組みが進まない理由というところが書いてありますけれども、アンケートをされたんですか。そこのところを、この地域の住民の意向をどう把握したのか、その辺を説明を求めました。","respondent":"品川木密整備担当課長","answer":"いわゆるまち歩きです、そういったもの等も進めておりまして、住民の声の中の一つを取り入れたという点です。それからあと、地区指定としましては、この地区、非常に不燃領域率が低いというところで、この地区を指定しています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"的に決めないでほしいという意見を伺ってきたので、専門家と区の職員だと、課長のところの担当の方がいらっしゃるんですか。なぜこの地域に広げるのかというあたり、不燃領域率が低いからだけか尋ねました。","respondent":"品川木密整備担当課長","answer":"そういうようなことを言うことはできませんので、我々の制度、この制度の内容のご説明をします。一部３という地区もありますが、４ということで非常に高いという面、そういった面を総合的に勘案して地区のほうは指定しています。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろ手立て、内容的なものを教えてくれるんですが、老朽木造建築で除却費用の助成しかないですよね。ぜひそういうふうにしていただけたら、少しでもいいのではないかなと思っているんですが、いかがか尋ねました。","respondent":"品川木密整備担当課長","answer":"専門家等も派遣していろいろなアドバイスをするだとか、そういう建て替えに向けての対応策というのも、このメニューの中には入ってあります。その新しい建物について、建て替えに対して特に何もしていないというようなことではございませんので、ご理解いただけたらと思います。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"耐震化をしていきたいとか、燃えない家づくりに寄与すると思うので、ぜひそういう検討もしていただきたいなというのは今後のことなんですけれども。補助３１号線道路計画がありますけれども、ここの沿道開発も含めて見越しているのかどうか、その辺もお答えいただきたい。","respondent":"品川木密整備担当課長","answer":"補助３１号線の沿道というようなお話がありますが、補助３１号線については、やっていくという意向のほうはございません。ここを不燃化特区にしまして、とにかく現行の制度を入れて対応して不燃化を進めていくです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"意見","question":"考えを変えるようなときは、事前に十分住民の方の意向を聞いて、拙速にやらないようにお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"西品川二丁目・三丁目地区、私も昔から木密整備事業の網をかけてほしいということを何回か質問してきたんですけれども。本当に狭い道が多かったものですから、西品川二丁目は、ちょうど……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"済みません、ちょっと忘れていましたけれども、ここの大井五・七丁目と西大井二・三・四丁目の、ここの地域の方々に対しての説明というか、途中経過も含めて、説明はどのようにされる見通しなのか説明を求めました。","respondent":"品川木密整備担当課長","answer":"説明のほうは、今までの特区の指定の経緯をなぞりますと、特区に指定されてから住民の方の説明会というものを開いているような形をとってあります。ここにつきましても同様な形で進めていこうかというふうに考えております。","id":"exchange-013"}]},{"id":"topic-04","title":"武蔵小山パルム駅前地区再開発事業について","agenda":"武蔵小山パルム駅前地区再開発事業について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"全般に上から伺っていきますけれども、認可の要件を雑駁ながら教えていただきたいのと、権利変換にかかわる方々が何人なのか。店舗を借りているだけの方と、土地の権利を持っていらっしゃる方の数がわかるのかどうか、その辺も説明を求めました。","respondent":"溝口都市開発課長","answer":"まず住戸系が６５名、店舗系が１３６名ですから、大体合わせますと２０１名の方が間借りないし借家という形で当地区に入っているという形になります。さらに、この数に間借りしているものをさらに転貸というか、貸し出している方が７名いるというふうに聞いております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"いつまでに立ち退いてほしいという、そういった方向が出ているのかどうか、それがわかっていたら教えてください。総事業費が３３６億円見込みと出ていたんですけれども、補助金のところもはじかれているのか、その数字も説明を求めました。","respondent":"溝口都市開発課長","answer":"ですから、目安としましては、平成２７年３月の権利変換認可後が一応立ち退きの時期という形になるものと考えております。総事業費としては約３３６億円、これの補助金といたしましては、約５７億円ほどの補助金を事業資金計画の中では組んでいるものです。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺、幾つか道路があるんですが、説明をしていただきたいのと、この区画道路３－２は一番通りなんですが、これは変化するんですか。３－２のところが拡幅と書いてあるんですけれども、これは今のままだと思うんですが、これはどういう意味なのか説明を求めました。","respondent":"溝口都市開発課長","answer":"ただ、工事等の影響がありますので、これについては将来的にはもう一度再整備という形で考えているものです。一部、区画道路５号線との重なる部分の交差点部分が広がるということで、今回の表記としては拡幅という形での表記をさせていただいているものです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"商店街、車も回るようになるということは、地域にも安全性にかなり影響するなというふうに捉えています。どこが管理をする駐輪場になるのかどうか、その辺をお伺いしたいのと、まずはそこをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５月３０日に再開発組合の設置認可というので、東京都の発表なんですかね、この周知をどのようにされるのかということが１点。誰がつくられているのか、財源的にはどういうふうになっていて、どの範囲で配布をされているのかということを説明を求めました。","respondent":"溝口都市開発課長","answer":"事業が入ってくる段階で事業説明、また工事説明、これまで４号発行しております。新聞につきましては、朝日新聞、読売新聞、毎日新聞の３紙に折り込みをさせていただいて地域に配っているものです。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"４者でつくっているということで、新聞折り込みということですけれども、新聞折り込みだけですか。財源的にどのぐらいかかっていて、どこが負担しているのか説明を求めました。","respondent":"溝口都市開発課長","answer":"約１０万円ちょっとぐらいの金額になっておりまして、それをそれぞれの４者で割って、それぞれ負担している。大体２５万円から３０万円ぐらいをそれぞれの地区が負担して新聞折り込みについての費用というのはまかなっているという形になると思います。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"役割的にも、財政的にも負担をしているのかどうか、その辺を教えてください。最後にします。","respondent":"溝口都市開発課長","answer":"大崎６０ヘクタールの全体の再開発事業を円滑に進めるために、また、開発事業者を集めて会議等を開いてやっているところです。３地区集まって連絡会を開き、そういったものが一番有効ではないかということで、今現在やっているものです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひこれだけニュースを出しているんですから、あと、今後この地域はこういう計画があるんですよというのを早め早めに周知するのが大事かと思います。なので、ぜひ目に見えるような周知方法をぜひ工夫していただきたいんですが、最後、しつこいですが、お願いします。","respondent":"溝口都市開発課長","answer":"再開発準備組合３地区と品川区の４者で話をしていたんですが、今年の４月からちょっと会員を拡大しまして、そういったものを図っていかれるかと。","id":"exchange-021"}]},{"id":"topic-05","title":"平成２６年度電力節減方針について","agenda":"平成２６年度電力節減方針について","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"前に予算委員会のときに質問しかけたことがあるんですが、やっぱり入り口に、なかなか涼しくない場所が多いというようなご意見も聞いたりもします。何かそういったお考えがあるのか、また、こういったなかなか涼しくないよというようなご意見があるのかどうか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"わりと利用は、利用率は出ないんですけれども、約２カ月で６７施設で２２万人以上の利用がございました。ただ、ミストなどの考えというのは、今現在のところは考えておりませんので、またいずれ研究してまいりたいと考えています。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２２万人ですか、そういったお声があるということをここでお伝えさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"不足をするというあたりの中身を教えていただきたいのと、２番目の「平成２２年度と比較しマイナス１５％を目標」ということなんですが、平成２２年度をベースにしているあたりの根拠を説明を求めました。","respondent":"三ツ橋環境課長","answer":"これは最終的には平成２５年度が１２.６％の節減結果が報告されております。したがいまして、今年は昨年より電力供給量の大幅減が予定されておりますため、１５％の節減率達成を目標としております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"平成２５年度よりもちょっと頑張って削減をしていくというところでは、具体的にどこをという、頑張るところというのが決まっているのか。公園が暗くて危ないとか、そういった声が聞かれたんですけれども、その辺は大丈夫か尋ねました。","respondent":"三ツ橋環境課長","answer":"どこの部分を頑張るところですが、全体におきましてマイナス１５％と考えております。しかしながら、昼の時間帯について中心に行っておりまして、また、公園など施設が暗くなってしまうというのは極力避けてまいりたいと考えています。","id":"exchange-025"}]},{"id":"topic-06","title":"の４「所管事務調査について」","agenda":"の４「所管事務調査について」","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"木密１０年プロジェクトはじめ、この委員会でするべきではなかろうかということで、防災対策に関することが１点。まちづくり全般、今のまちづくり、内陸と水辺という両方を兼ねて総論的にまちづくりに関することということで出させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"５００ですか、上がってきているという注目すべき空き家ということで。空き家対策、そういったこともしっかり研究していきたいと、こういう思いで出させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"大倉副委員長","kind":"意見","question":"本当に水辺はオリンピック、さまざまこれから活用また利用を考えていかなければいけないというところで出させていただきました。安全な交通ができるようにするかとか、その辺を考えていければなというところで出させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"意見","question":"防災訓練とかが一つと、あと、災害者要援護者支援のところを話し合えたらいいのではないかなと思っています。なかなかいろいろできないので、それが一つでいいかなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"大沢委員","kind":"提案","question":"９月８日の週のほうが皆さんいいんじゃないかと思います。９月８日の週のほうを自民党は提案したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"内容が決まる前に２泊３日というところで決めてしまうのでしょうか。９月の初めというのは大変厳しい中なので、皆さんの一致で、どうしてもここに行くという中身が決まってから２泊３日なのか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"意見","question":"その週で。〔「重なっているかどうかだけ見てくれればいいんだよ、まとまっていなくていい」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"私は、この時期はすごくタイトだなと思っているので、これ以外はないのでしょうか。もっと後というのは難しいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"提案","question":"皆さんがぜひというのでしたら、行き先も決まらないうちからここで委員長提案が２泊３日ということだったので、ちょっとそれはどうかなと。〔「３泊４日にしたいんですか」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"先ほどほかの会派が提案したような災害対策についてというような調査項目で、受け入れも、被災地の視察ということをご提案したいのが一つです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"避難状況とか、その辺もぜひ委員会で行けるのだったら、訪問していろいろご意見を聞きたいなと思っているところが１点ありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-08","title":"の６「その他」","agenda":"の６「その他」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"どう影響するのかなということをお聞きしなくてはいけないなと思っているのと、今後どういうふうに進むのか、経緯のところも教えていただきたい。","respondent":"中村都市計画課長","answer":"ここでは１,５００フィートと、１,５００フィートと書いてありますけれども、これは上空約５００ｍぐらいなのかなというふうに思います。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"とにかくこの件に関しては、知識もないので、調べてみたいなと思っていますので、ぜひ次回なり、またその後なり、お時間をとってほしいと求めましたので、そういう方向でよろしいか尋ねました。","respondent":"中村都市計画課長","answer":"今、まだ先週、数日前の情報提供ということで、今後また動きがありましたら随時報告をさせていただきたいと思います。お気づきの点がございましたら、私のほうでお調べをしたいと思いますので、随時お問い合わせをいただければと思います。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/978343?Template=document&Id=4106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":53424,"voices":155}},{"id":"h26-20140609-9","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"文教委員会","time":"午後１時００分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"改めて具体的にどういう意見が出て、その事業効果というのは１年たたないとわからないわけですけれど、もう一度伺っておきたいと思いました。この間２回の実態調査をしてみて、主体的な権利者というところの啓発というのでしょうか、どういうふうに行われているのかということを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"もちろんそのつもりで、だから深く関わらないで、しかしこれを事前に読んできたとき、ちょっと見えない部分を質問しているつもりなので、そういうふうに受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"この学校に配置している基準というのですか、それはどういうふうになってこの学校に配置されているか、ちょっと教えてほしいと求めました。つまり栄養士の配置の基準、考え方がどうなっているか、最後に伺いたいと思います。","respondent":"野呂瀬学務課長、田村教育次長","answer":"就学援助の単価表ですけれど、先ほど私が申し上げたのは平成２５年度の分で、２６年度の新たな分についてはまだ決まっていないということです。 ただし、この５７ページを見てもらって区費のところをごらんください。さらに給食業務で退職したりした場合には、民間のノウハウを活用して栄養士としての委託も開始していると、そのようにご理解いただければと思います。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"私も質問してきて「今、平成２６年度は決まっていないということなので、まだ検討の最中だというふうに理解していいのでしょうか。考え方としてどうなのかというところをさっきから聞きたいと思って質問しているので、そこに触れた答弁をお願いしたいと思います。","respondent":"田村教育次長、野呂瀬学務課長","answer":"栄養士は２校に１校配置、先ほど言った栄養士のノウハウを持っている民間に委託していると、そういうふうにご理解いただいて結構です。 考え方としては、品川区の考え方としては、そういう考え方のもとでやっているです。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つだけ確認させていただきたいのですけれども、我が品川区では、こういうお子さんに対しての把握をなさっていらっしゃるのでしょうか。していないわけはないと思いますが、ちょっと確認だけさせてほしいと求めました。","respondent":"伊崎子育て支援課長、野呂瀬学務課長","answer":"厚生労働省から調査の依頼が来ておりまして、その報告に向けて現在、改めて平成２４年度からの分の調査中です。その結果につきましては、ご報告できる時点でまたご説明したいと考えています。 ただ一番多いのは、いわゆる二重国籍で持っている方で、出国してしまったとか、そういう方が多いです。ちゃんと、書類と合わせてそのお子さんの住所に赴いて、実態調査も合わせてきめ細かにやっているところです。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"この人数というのと、４０.９％という数字についての区の見解を伺いたいと思います。この１２６人という状況が今までになく、そのあたりの見解を伺うのと同時に、そのあたりのことを教えてほしいと求めました。","respondent":"伊崎子育て支援課長、今井制度改革・待機児童対策担当課長、竹田保育課長","answer":"一番多うありますのが、幼稚園・保育園の登園前の預かりと送り、加えて帰宅後のお迎え、こちらが一番割合としては多くなってあります。… 重複して開設されているところもありますので全部で２８になるようにご説明いたしますと、学校法人立が１園、そして株式会社立が１５園です。… 一定の心の切り替え等が必要であるという考え方から、この移行期において３日間、インターバルという期間を設けているものです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"今年の４月までの対応をしっかりと継承していただいて、その辺についてどういうふうに考えていらっしゃるか、伺いたいと思います。ですから、そういうことでどういうふうに考えていらっしゃるかを、予測も含めてお話を伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"入園児が１,７０６人、そして待機児童数は１２８人ということで、これは前回も１２８人ということでご説明申し上げたところです。子ども・子育て支援事業計画の中でも、幼稚園そして保育施設、子育て施策を総合的に進めていくという品川区の方針に変わりはございません。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"しっかり重く受けとめるべきだと思いますので、そういう場面をなくす、この努力をしっかりしてほしいと求めました。だからできるだけ早く、またこちらからも積極的に質問は取り上げていただけるような委員会運営をしていただきたいということもお願い申し上げて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋委員","kind":"質問","question":"１つだけ、４ページの職員の配置なのですけれど、児童相談所に区の職員の方が行かれているのは、この中に入っているのか尋ねました。","respondent":"伊崎子育て支援課長","answer":"この中には入っておりません。数字としては人事課付になっております。","id":"exchange-009"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"昨年度ですか、その後の展開の中で検証すべきことが多数あるかと思いますし、いざやってみての変遷があるやに聞いています。次なる展開、拠点となるセンターの検討を含めた提案が自民党の中でも根強くあったものですから、項目として上げさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"南委員","kind":"提案","question":"これから品川区としても条例を提案されたりすると思っているのですけれども、待機児童対策ということで、一点入れるべき時期ではないかと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"これは国のモデル事業でしょうか、スーパー食育スクールとかこの辺を含めて、品川区としての取り組みをどうしていくかというところです。子どもをいかに守っていくかということもしっかり、大切な観点であると思いますので、このあたりについてもできればと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"意見","question":"１つはＩＣＴ活用について、さまざまな運用をされる中で、その活用について調査研究をできたらなと。以上、４点ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"吉田委員","kind":"意見","question":"我が会派では、先ほどからこの事務事業にも入っておりましたけれど、教育の情報化の課題と適応力の推進についてをお願いしたいと思います。書籍や紙媒体もそうですけれども、情報ということに関しても含めて推進してはというこの内容を、項目に上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"高橋委員","kind":"意見","question":"それとともに、今後さらに巡回して指導ができるような形の仕組みづくりなどについて、調査するのはどうかと思いました。自治体の中では行っているところもあるので、課題や成果が出ていると思いますので、その点についてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"意見","question":"前回、きょうお見受けしている中でもかなり調査の希望が多岐にわたっていましたので、正副委員長にお任せをしたいと思います。場所あるいは調査項目も、関連が深いかと思いますので、私も先ほどのあれを踏まえているという認識でいますので、お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"吉田委員","kind":"意見","question":"我が会派でも、視察についてですけれど、やはり品川区と同じ土俵というふうに考えまして、経費もかけずになるべく東京近郊の近いところになるような、視察をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"つる委員","kind":"意見","question":"今、渡辺委員からありましたけれど、基本は正副委員長にお願いしたいと思いますけれど、一応公明党としての案を、ペーパーでも、紙ベースでもつくりましたので、それを改めて提出させていただいて、それを含めて正副委員長で最終的には決めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"もちろんそうなのですけれど、例えば人権とか権利をしっかり守れる、そういう行政をしているところをちょっと見たいとは思っているのです。遠隔地だし、そういう角度でやっている行政があったらぜひ入れていただけないかと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/510624?Template=document&Id=4824#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":45811,"voices":91}},{"id":"h26-20140609-5","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"総務委員会","time":"午後１時００分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ概要を伺ったのですけれども、今年の特徴や重要課題は品川区としてはどんなふうにお考えなのかを伺いたいと思いました。今年の特徴、重点課題また重要課題と言えばよろしいのでしょうか、そこをご説明ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"今年の１年間こういう仕事がありますよという説明があったと思いますけれども、重要課題だったり、質問します。平たく言えば特徴はということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"その金額というのはどういう根拠があるのか、１年間のやりとりの中で必要な金額ということなのか、そこの考え方を伺いたいと思います。具体的に何か代表的な事例などがありましたら、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"例えば２１０億円の歳計現金というのか、これはどういう考え方ですかということを聞いたのです。委員長が個別というのは一体何を指すのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"これがどういうふうに積み上げられているのかと聞いているのではなくて、この考え方は何ですかと聞いているのですね。委員長の概要と個別というのは何が違うのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"そこからどんどん突っ込むかといったら、いつも言われるからその趣旨もよくわかりますけれども、概要について概要を聞いて何が悪いのですか。概要に対して、平たく言えばもっと詳しく聞きたいという質問の何が悪いのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆるやりとりの事情でこれぐらいの規模が必要だという考え方なのか、状況を伺いたいと思います。８月にもご報告があると説明がありましたが、現在ある変更点や傾向、また今後の見通しも含めてご説明ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"逆に外れるのではないかというのが２年ぐらい前から動きがあったり、見通しがあるのか、そこを伺いたいと思います。あわせて伺いますけれども、その趣旨とあわせて伺いたいのと、どういう実形なのか伺いたいと思います。","respondent":"本城企画財政課長、小林施設整備課長、荒井広報広聴課長","answer":"財政調整交付金につきましては平成２６年度予算ということでご説明して、今の時点の傾向というのは特にその時点から変化している部分はありません。… 施設整備課のほうでは、今、不調関係のお話だと考えていますが、去年から大分右肩上がりで基本単価等が上がっているのは現実的にあります。… ２つ目のお尋ね、企画部長が呼びかけをして、関係各課とともにそういった会を設置するというような位置づけになっております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"総務課と経理課に１点ずつ伺いたいのですけれども、今年２年目に入った区長と教育委員との懇談会ですけれども、そこを伺いたいと思います。今年はどういうスケジューリングなのか、どういう対象物というか、今年の状況を伺いたいと思います。","respondent":"江部総務課長、立川経理課長","answer":"区長と教育委員の懇談のお尋ねですが、これはあくまで懇談ですので、ざっくばらんに意見交換をしてお互いに情報を共有するというところにありますので、特に要請するものではございません。 回数等のお尋ねですが、今年度につきましては案件がある程度そろい次第開催するということになりますが、これまで５月に第１回は開催しています。第２回目以降につきましては、今のところスケジュール的には確定はしておりません。","id":"exchange-009"},{"speaker":"西本委員","kind":"確認","question":"その役割をどういうふうに考えていったらいいのかと、すみ分けが、どういうところですみ分けをするのでしょうか。それから、これは、ここに書いてあるものについてはここの委員会で総務課が中心となって報告をなされるという理解でよろしいのか尋ねました。","respondent":"柏原オリンピック・パラリンピック調整担当課長、荒井広報広聴課長、江部総務課長","answer":"組織ということで連携関係の、担当の部分について回答します。推進担当課長、東京都との調整であるとか、主には区の内部と区の外という切り分けをした中で… ホームページ上にはイベントカレンダーというものがありまして、必ずしも全ての情報がそこに載っている状況ではありません。… 他課との連携事業というご質問がございました。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺をもう一度、確認させてください。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"その仕切りの中でやる範囲の中で確認だけさせてください。そうするとこちらで判断できるかという気もあるので、そこら辺のところをちょっと教えていただきたい。","respondent":"荒井広報広聴課長","answer":"これから品川区としては今聞いた話を参考にしながらつくっていきましょうという話をさせていただいたところです。例えば教育であるとか、事務局として、全体的なところを調整して進めていきたいと考えているところです。","id":"exchange-012"},{"speaker":"石田委員","kind":"確認","question":"大枠の話で確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の３「その他」","agenda":"の３「その他」","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"建設委員会所管なので要望にとどめておきますが、子供たちとかが暑さをしのぐとかで水分を補給する、すごくいい取り組みだと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"具体的にあるのですか、どういう状況だと区民サービスの低下を招くだろうという、そういう基準というのはあるのでしょうか。お答えできたらお願いいたします。","respondent":"江部総務課長","answer":"基本的に例えばスポーツ施設とかで照明等がなければできないことになりますので、そういう機能に応じた必要なものというのは最低限守ると。ただ、昼休み消灯につきましても、窓口のところはお客様がいらっしゃるですので、そこは確保するといったような考え方です。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"全館を１つの機能で、要は何度と設定されてしまったりすると、日の当たり具合によると非常に暑くなったりとかするのですね。そこをお使いになっている方々には扇風機をもう１台増やすとか、ご理解を求められるようなことができるのではないかと思いますがいかがか尋ねました。","respondent":"江部総務課長","answer":"直接所管は違いますけれども、きめ細かな対応を区民に対してしていけるように所管に伝えてまいります。","id":"exchange-016"},{"speaker":"石田委員","kind":"確認","question":"１点だけ確認をさせてください。ですから、公園なんかもそういう同じにやってくださったのだけれども、そういう感覚でいいのですよねという確認だけ。","respondent":"江部総務課長","answer":"委員おっしゃる中身で大丈夫だと思いますが、念のため確認はいたします。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"それは所管事務調査として１回しっかり議会もあわせて、総務委員会ですから、そういうことも含めながら考えていったほうがいいのかと思う。財政調整交付金とはという部分のところを１回、さっき言った公金収納とか、私からは計３点ぐらいは委員長にそれをお願いしたいというつもりでいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"やはり１０年、２０年を見たときに、外れたものや縮小されたものの動きをよく捉えていきたいと思ったのです。あまり質問はしませんけれども、逆に対象となっていたのを要するに２階に上げてはしごをとったような形になっていたり、ひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"前回平成２５年も情報受発信というのですか、収納の手法というのですかね、税金の。これは今ここで言うべきかどうかわからないですが、前回の総務委員会のときにナンバー制度というのですか、それはやってもいいのかという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"私はより今後のことを、より特別区民税が入りやすいような、もっと増えるようなことを総合的に考えていくような場になるといいかと。２３区、人が流入してこないようなところではなくて、そういう問題を課題として私はこの総務委員会で皆様と話し合っていきたいと願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"西本委員","kind":"意見","question":"今後どうあるべきなのかというのは当然やっていかなければいけない部分ではありますが、それをまたどうしていくのか、その辺私のほうは決められない。一つの意見としてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"石田委員","kind":"意見","question":"出してどうとかではなくてスタートしていったほうがよっぽどいいし、行政視察もこれからやるのかどうかあれなのだろうけれども、皆様異論はないとは私は思うのだけれどもなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田委員","kind":"意見","question":"区民税という向こうでいう市民税だけれども、ちょっと制度がいろいろ違うから、市だと。そういうのも含めてぜひその中で、一任をしますので、相手のあることも含めて決めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"我々、どうせ行くなら、視察先としてやっていただきたいと思うのです。先ほど申し上げましたけれどもますます高齢化が進むということを踏まえて、真剣に委員長、副委員長には考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"視察をするのであれば、もっとフレキシブルに正副委員長のほうで考えていただいて計画をしていただければ、案を出してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"石田委員","kind":"質問","question":"もう１点、いいですか。これで半年もすれば第１弾の結果だとか、それこそ、それはそれでいいと思うのでそういうこともぜひフレキシブルに考えてもらえばと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/531035?Template=document&Id=1984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":36954,"voices":120}},{"id":"h26-20140610-14","meetingId":"h26-cm06","date":"2014年6月10日","dateIso":"2014-06-10","committee":"行財政改革特別委員会","time":"午後１時００分～午後２時０６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"それぞれの報告から一つ程度、伺いたいと思います。４,０００万円の一部、これも議決が必要になるのでしょうか、説明を求めました。","respondent":"柏原行財政改革担当課長、立川経理課長、本城企画財政課長","answer":"都の未利用地については高齢化に対応していく等との話も出ているのですけれども、財務局が所管していますので、問い合わせ等をしています。一定程度… 三千数百万円にリフォームをして、それが４,０００万円以上の価格である場合は、やはり議決案件ということになります。基金の規模自体は平成２４年度から平成２５年度にかなり大きくなっているということで、現在、変えているわけではございません。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういう意味では、ぜひ検討のスピードを上げるように要望もしてほしいと求めましたので、これは要望にしておきます。おっしゃるように額が大きいものですから、検討のスケジュールですとか、あれば説明を求めました。","respondent":"本城企画財政課長","answer":"規模の大きくなったことによって今後検討していくことも必要だということで認識してはおりますが、具体的なスケジュールを立てて今からいつまでに検討していくとか、そういう形で検討しているということでは必ずしもないです。","id":"exchange-002"},{"speaker":"あべ委員","kind":"質問・要望","question":"これまでに使ってきたものも、やはり意味があって、目的がある中でやってきているわけですから、これはぜひ早急に検討してほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"南委員","kind":"提案","question":"そういう点で、そのあたりについてはどういうふうに区として考えているのか、そのあたりを契約部分では伺いたいと思います。１年間の動きを教えていただきたいし、どうしてそうなるのかというところも改めて教えていただければと思っていますとの意見を述べました。","respondent":"柏原行財政改革担当課長、立川経理課長、本城企画財政課長","answer":"昨年度の中で議論になって一定程度方向性が出たものと、そういったところをベースに概況を説明させていただいて、その後。… 具体的には予定価格の適切な設定であるとか、予定価格の事前公表、契約約款の第２５条にありますスライド条項の適切な運用。そういった意味で… 基金の関係ですが、本日の資料の中では、基金の概要ということで３カ年、見込みも含めて３カ年分を資料としてつけさせていただきました。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"今わかる範囲でもし教えていただけたらという気持ちも持ちつつ質問したつもりですけれども、それはそれでぜひ、それはありがたいことですけれども。そういう点でどういうふうに考えておられるのかという点について、改めてこの際、区の見解を教えてほしいと求めました。","respondent":"立川経理課長","answer":"予定価格の設定の話になるかと思いますけれども、いわゆる最新の労務単価、これは国交省等から示されるものです。そういった常に最新のものを利用して工事の予定価格を積み上げていく、当然、契約約款の中で法令遵守等でお願いしています。","id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"こういう関係を大事にするべきだと思うので、この１年はいきたいと私自身思っているところですけれども、深めていきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"提案","question":"これまで余り行財政改革特別委員会でも扱って大分あいたのでしょうか、契約事務という形でもいいのかと思っていますが、いかがでしょうか。一つの提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"南委員","kind":"提案","question":"今、こういうふうに使ったらどうかみたいな提案もできるようになったらいいかと思っているので、そういう意味での土地の情報提供をしていただきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"契約事務のところで、平成２５年度の決算特別委員会の中で、たしか３億３,０００万円の契約落差があった記憶があるのです。それがどういうふうに工事が保証されているのか、もう少し勉強していきたいと思いますので、ご検討を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員長","kind":"質問","question":"私から少し。議会的に言えば迫り方と言えばいいのでしょうか、この際、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林委員","kind":"提案","question":"まだ始まって１年目という中ですけれども、今の最低制限価格制度のとり方はしっかりと引き続き議論をしなければいけないと思うので、資料を求めます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"基金の目的が明確になっているわけですから、それが資料のお願いができるのかどうかということが１点と、その部署。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"妥当なのかどうかといったことを考えたいと思いますし、検討といったらいいのですかね、その理解をしていけるといいのかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"数年の間の推移を見たいというので情報を出していただきたいとお願いしたのですけれども、果実運用型ですから、そこの利子で使っていくわけですよね。地球環境基金、そういうものであってほしいと思いますので、どのような状況になっているのかがあわせてわかるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"須藤委員","kind":"提案","question":"今、なかなか利益を自分でとってどうのというのはできないというような状況下に置かれて、その振興をしていかなければいけないという環境下にある。そういうことも行政側に提案の中に、どういう基金が必要かということが考えられたら、ぜひその辺も検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/705937?Template=document&Id=5968#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":20183,"voices":55}},{"id":"h26-20140611-18","meetingId":"h26-cm06","date":"2014年6月11日","dateIso":"2014-06-11","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後３時１７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"木村副委員長","kind":"意見","question":"副委員長の木村けんごです。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"全く聞いていなかったことかと思うんですが、区のほうでは、どういうふうな捉え方をされているのか。もし何かお考え等、ちょっとこういう感じで話が来ているとかありましたら教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"昨日の知事の発言につきましては、区としても承知はいたしていますが、詳細にどこの会場をどうのということは全く聞いてございません。これから慎重に情報収集してまいりたいと考えています。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"やはり今品川区で２会場ということになっていますし、区のほうでももっとほかの競技を増やしてもらえるような方向で話が進められるんだったら、そういうこともぜひ進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-03","title":"視察の前に、予定表４のその他","agenda":"視察の前に、予定表４のその他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そういうところで言えば、ご意見をお聞かせいただくとか、そういうふうなところもできるかどうかもご検討いただけたらなというのが１点です。オリンピックの原点というか、そういうところに立ち返ったところをしっかりと確認し合うというか、ご検討いただけたらと思います。","respondent":"渡辺委員長","answer":"では、今後の運営の中で正副で調整させていただき、検討させていただきたいと思います。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"提案","question":"ご提案の趣旨がわかって、会派の中に副委員長もいらっしゃいますし、厚生委員会との絡みという問題も出てくると思います。その辺を十分発言の中でもご注意ほしいと求めましたので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"いながわ委員","kind":"確認","question":"委員長に確認だけなんですが、むしろオリンピック・パラリンピックまでどういうことをするべきか、ちょっと確認をしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡辺委員長","kind":"提案","question":"提案、各委員からいろいろな提案を受けて、品川区の立場で東京都や国への要望というのも一つの目安になるかと思います。要望を形にする際には、またこれも適時、進行上相互にご指摘いただければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この野球場の代替機能の必要性や対策、またこの必要性そのもの、そういったものは地元区と調整を行っていくと都のほうも答えているんですよね。都に対しての要望書も出されているというところでは、やっぱり自分の区ですから考えていかなければいけないなというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"質問なんですが、７番のところの隣に、特区構想と書いてあるんですけども、関連のある項目となっていて、この特区構想というのは、今の時点でどんなものが想定されるのかというところがわかるものがあれば説明を求めました。","respondent":"渡辺委員長","answer":"その辺から関連で、随時という考え方で、現時点でどうこうというのはまだありません。今予定表の中に公式な見解等が出た場合には正副で検討しましょうという、委員長と副委員長の間での検討課題という形になっています。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"提案","question":"逆に言うと、早い時点で委員会として都に対しての意見書ですとか要望書みたいなものを出してもいいんじゃないかと思う、委員会提案で。これも考えておいてもらえれば、全員で検討していきたいと思いますので、委員長のほうで、ご配慮をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/882053?Template=document&Id=6454#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":12732,"voices":49}},{"id":"h26-20140630-6","meetingId":"h26-cm06","date":"2014年6月30日","dateIso":"2014-06-30","committee":"区民委員会","time":"午前１０時００分～午後０時２７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"第５１号議案、指定管理者の指定","agenda":"第５１号議案、指定管理者の指定","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"それとあと、品川ビジネスクラブとマグネットスタジオは、設立もそんなに、若い事業体じゃないですか。その役割というんでしょうか、実務的なこととか、その辺のところを教えていただきたい。","respondent":"山崎ものづくり・経営支援課長","answer":"中身としましては、今ご説明申し上げたとおり、そのときから共同事業体による提案を妨げるものではないというようなことで説明を申し上げました。先ほど説明した資料の１ページの1)で、こちらも当初の事業説明のときには、１社ごとに単体で説明に来ていただきました。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"最後に、細かいことなんですけど、施設のＰＲ用ホームページの開設をやるというのは、どこがやるんか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"指定管理者としましては、施設の開設に合わせまして、平成２７年６月からということになります。今回議決をいただきましたら、事務の中でこの共同事業体のほうがホームページを作成してというようなことで考えてあります。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そういうのが、どういう提案があってこういう判断になったかというあたりを、その点を１点お聞かせほしいと求めました。まず事業運営に関する提案書と産業振興事業に関する提案書というのが出されていると思うのですけど、その事業運営に関する提案書というところではとの意見を述べました。","respondent":"山崎ものづくり・経営支援課長","answer":"区におきましては、指定管理者制度の活用に係る基本方針ということがございまして、指定のほうの議決をお願いしたいということで考えているものです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それと、最終的には多分区と協定を結んで、向こうからの提案と今後の見通しというあたりはどうなのかということも教えてほしいと求めました。区民が本当にこの施設をどれくらいで使えるのかというところの提案というのはどうなっていたのかというあたりもお聞かせほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"例えば１人幾らで親睦会などを実施する場合のパーティープランといったような、さまざまな提案、割引プランをいただいているものです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、その利用料というのは、この条例ではなくて、どういうところに、条例の使用料と、それから何で決まるのですかね。光熱水費だとか、さまざまかかったところから利用料を引いて、足りない分を基本指定管理料という形で区が出すという考え方でいいんか尋ねました。","respondent":"あべ委員長、山崎ものづくり・経営支援課長","answer":"料金体系について、もう少しわかりやすくイメージをお伝えしたほうがいいのではないかなと思います。先ほどの説明だと、ちょっとわかりにくいかもしれません。本年の第１回定例会で施設条例をご審議いただいた際に、その段階で一つ一つの施設特性を踏まえた利用料金の設定について説明を申し上げました。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"きゅりあんと同じようなことで使えるような割引まで下げられるのかというあたりをさっきお聞きしたのと、どういうふうにして指定管理者の利益が出てくるのかというあたりのところを先ほどちょっと質問したので、その点についてもお聞かせほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"区民割引の考え方なども導入しながら、団体割引ですとか、今までにない柔軟な発想と運営を適用してまいりたいというふうに考えているものです。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことではないんですか。独立採算制ということができれば、この指定管理者が利用料金の中でやりくりをしていくと、基本的にはそういう考え方ということになるのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"料金の設定につきましては、先ほど来ご説明のとおり、この施設の主目的に沿う料金の設定をする予定です。それから、指定管理者の導入のときに、なるべくそうした視点を入れて検討していくんだというのが区の基本的な方針の中にありますので。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この委員会でご報告をいただくということで確認をさせていただきたいのと、産業振興事業に関する提案書というのも出されているということなのですけど、区が今回の指定管理者となった事業者をどう評価して判定に至ったかというところについても最後にお聞かせほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"８月に予約が開始されますので、その前、７月の本委員会にもその内容について報告をする予定になっております。機会の創出、大企業の方々との連携ですとかマッチング、そうしたことに取り組んでいってはどうだというような提案もいただいているものです。","id":"exchange-008"},{"speaker":"井上委員","kind":"確認","question":"今、基本的に、こういう資料でそういう議論をしなきゃいけないというのがすごく問題だということだと思います。まずちょっとお聞きしたい、１個だけちょっと確認をしますけれども、そこのまず規模を説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"平成２９年度というような平準化した年度で言いますと、歳入歳出で１億３,５００万円というようなところでシミュレーションをしています。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"指定管理料の委託料ということで、その金額なのか、利用料金制なので、区の負担ということでお答えいただいた金額ということでよろしいんか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"利用料金制で歳入歳出の規模が１億３,５００万円程度です。それをどっちが持つんだということにもよりますけれども、今のところのシミュレーションですと、区の指定管理料は４００万円です。","id":"exchange-010"},{"speaker":"井上委員","kind":"提案","question":"ですから、なぜここにしたんですか、じゃあその３者はなぜいけなかったんですかということがわかりませんので。１５日は何曜日で、１９日は何曜日になっているのかちょっとお伺いしたいということと、ちょっと教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"公的な産業支援機関として、区の産業の活性化のために共同連携をして事業をしていきましょうという協定を、昨年４月の段階で締結しております。ですから、そういうところで支援の関係にあったのはもちろん事実ですけれども、財政運営に努めていただくというふうに考えてあります。","id":"exchange-011"},{"speaker":"井上委員","kind":"確認","question":"品川ビジネスクラブに関連して確認をしておきたいなというふうに思ったのは、収支予算書の受取補助金が３,１３５万円というふうになっています。これは地方自治法第２２１条の２項で、こっちが補助金なので、差異についてご答弁ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"１９日、どういう議論がされたのかという時間だけの問題ではないと、そういったところには問題はないのか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"区の指定管理者制度の活用に係る基本方針というものがありまして、そこでルールが明確化されております。区としましては審査をして、その結果を受けてということでやらせていただいたというふうに思っております。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"当然５年ごとの指定で、指定管理が２０００年の次にやって、今回これはとても違うと思うんですね。そこがなぜそういうふうに、３者に比べてここが優位であって、資料については検討していただかないと議論の俎上にのれないんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議会が認めたということになるわけですから、その指定管理者がやっぱり適切なものであるのかどうなのかというところを議会が判断するわけですよ。だから、なぜこの指定管理者として判断したのかという、ぜひ委員長のほうからも求めていただきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"ある程度必要かなとは思っておりますが、今の状況ですと難しいということもあると思いますが、ほかの質問をさせてほしいと求めました。どのような協定になっているのかというのを教えていただきたいのと、あと、区としてどのような対処をするのか説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"は解散に対する措置というところでございまして、協定で言いますと、第１６条ということになってあります。にお願いするか、区のほうとやりとりをさせていただいて、そうしたことに備えるというような内容になっているものです。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問","question":"じゃあこれはどうするのかということが、それが一つちょっと気になるところでありまして、その点について教えてください。もしこれが途中で１回途絶えてしまって、ブランクがあいてしまうということは、ある程度いたし方ないという考え方でおられるのか説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"そうした危機管理の状況ですとか対応につきましては、もう一つの事業者のほうが代理をするとかということで施設の運営の継続性が保てない場合については、そういう事態にならないように区としては十分配慮してまいりたいというふうに考えているものです。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"一つお伺いしたいのが、これは教えていただければということで、全く知らなかったということもあって教えてほしいと求めました。ここは場所としては知っているのですけれども、どうなっているのかなと気になったものですから教えてほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"一定その際の基本金といいますか、設立したときの基本金を出資したというようなことで、品川ビジネスクラブができたということになっております。その後、区との関係もあって、区が５０％相当額を、昨年協定を結びまして、区としても支援を開始しているというような流れです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"品川区は、ものづくり・工業よりも、商業に力を入れていると私は思っていました。今回、長年の夢であるこういう施設ができるということで、まず品川区のものづくりの担当課長としての意気込みを改めてお願いしますとの意見を述べました。","respondent":"山崎ものづくり・経営支援課長","answer":"まちづくりの進捗に合わせてこういった拠点施設が双方で検討されてきた経緯もありまして、産業分野としますと、そういう思いでずっと来ていました。区として地域特性を踏まえて、品川区としての産業の活力に資する事業展開をしっかりやってまいりたいというふうに思っております。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"ここの６番に選考基準で四つ出ていますけれども、改めて品川区は選考で何を求めたのか。そして、求めた中で、一番高いのがこの共同事業体だったわけですよね。","respondent":"山崎ものづくり・経営支援課長","answer":"長年そうした産業の活性化の分野では、地域経済の活性化などを同じく目標にした相手方の財団法人と組んでというような事業展開ができませんでした。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"代表者の石島氏という方がいらっしゃいますよね。そのときに個人のあれはあまり関係ないかもしれないんですけれども、氏に対しての思いといいますか、その辺はいかがか尋ねました。","respondent":"山崎ものづくり・経営支援課長","answer":"品川区のほうで産学連携を進める上で、高専のほう、それからここの大学とも連携しながらいろいろやってきている。そこの学長として、そうしたところに知見のある理事長ということで、区としても認識をしているということです。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"稼働率がどれくらいでペイできるという状況になっているのかということを一つお聞かせいただきたいのと、近傍に同種の施設が７５施設ぐらいある。稼働率というのがどの程度見込めるのか、そして、ペイできるのかというところについてちょっとお聞かせほしいと求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"今回初年度については６０％弱、平均的には６０％の稼働率をとっていこうじゃないかというようなことでご提案をいただいております。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"口頭でやりとりをするしかありませんので、それを示していただいて、判断をさせていただきたいというふうに思います。その報告があって、判断をしたいというふうに思いますので、そこについて判断できる材料を、示すよう求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"それぞれ３社が連携していますので、少し支援実績などの記述がばらばらの立ち位置で提案がされていたというようなこと、提案の内容も薄く。概要はそういうことです。","id":"exchange-023"},{"speaker":"井上委員","kind":"提案","question":"区の負担とか事業規模を提案によって区ができるのかなというふうに思ったんですけど、今の答弁だとちょっと違うかなと。今そういう理由を伺った中で、3)の順に今答弁いただいたと思うんですけれども、そこを説明を求めました。","respondent":"山崎ものづくり・経営支援課長","answer":"それから、2)の株式会社コンベンションリンケージにつきましては、年２,５００万円程度。それから、3)シグマアテンドサービス株式会社が年８,０００万円程度、品川ビジネスクラブのほうが４００万円程度です。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回の指定管理者の提案の中でも、そこのところが区民のために使えるというふうな施設ではないということが改めて明らかになったと思います。そういうところで、今回のこの指定管理者に対して反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"井上委員","kind":"意見","question":"賛成です。各委員会での指定管理の資料づくりというところでお願いをしたいと、行政に向けても、議会としてもお伝えほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-02","title":"第３５号議案、平成２６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３５号議案、平成２６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"２番の事業目的なんですけれども、周知拡大なんですけど、主語というか、何の周知拡大なのか教えていただけますか。","respondent":"米田商業・観光課長","answer":"その２面を、言葉が足りなかったんですけれども、そういうようなことで記載させていただいているものです。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"消費者センターは。周知拡大でこれ以上相談者が来たときの受け皿が区としてちゃんと整っているかということなんですけれども、その辺についてはいかがか尋ねました。","respondent":"米田商業・観光課長","answer":"そのときになかなか対応しにくかったというところもあるんですが、長い目で見ておりますと、少しずつ消費生活相談員の配置を厚くしておるところです。現状のところ、対応がしきれないということではなく、今のところはあるというふうに考えてあります。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"具体的に一つ教えていただきたいんですけれども、５０代も入っていたかな、一番はアダルト関係でしたよね。何でそれが全年代においてトップに来るのか、その辺についても今区がつかんでいるところを説明を求めました。","respondent":"米田商業・観光課長","answer":"サイトの信用性を、あるいは信用に値する事業者なのかというようなことをきちんと判断した上でクリックをするということが大事であるということです。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"周知拡大していただいて、多分来る方は、わらをもつかむ思いで来ると思いますので、相談員等を含めて、万全の体制でやってほしいと求めましたけれども、最後にその辺について。","respondent":"米田商業・観光課長","answer":"広くこういう事例が発生しているということを消費者センターとしても出前講座や講演会等を通じてこれからも周知を図っていく。それだけの今体制は整っていると思いますので、こういう活性化交付金等を通じてさらなる充実を図っていく、このように考えてあります。","id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"歳入で４２９万１,０００円となっていますけど、これは品川区のほうが歳出などで金額を請求するわけですか。ちょっとわからないので説明を求めました。","respondent":"米田商業・観光課長","answer":"それから、都道府県のほうに対しての内示等もあります。品川区のほうで今年度はこの金額を要求したところ、丸々認めていただいた、そういうようなことです。","id":"exchange-031"},{"speaker":"木村委員","kind":"意見","question":"そんなにしょっちゅう壊れるようなものではないと思うんですけれども、何年に１回かとかということでやっているのかどうか、まさか毎年同じようなものを出しているわけじゃないですよねとの意見を述べました。","respondent":"米田商業・観光課長","answer":"消費者行政活性化交付金自体が平成２１年度から実施されておりまして、当初３年で終わるというようなことでお話をいただいています。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２１年度から消費者行政活性化交付金というのが出されているということですけども、毎年同じぐらいの額だったんでしょうか。それから、どんな成果が上がっているのか、また現状の相談員の体制が何人ぐらいでされているのかということについて教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"一応終わるという予定だったので、平成２４年度の補正では約６０億円の、最終的には６０億円の交付があるというようなことでした。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"国全体の何百億円というのは、この資料にも書かれているのでわかるんですけど、品川区に今までどれぐらい来ていたのかということと、相談員の体制、人数がどれぐらいの体制でやっているのか、その２点だけお願いしますとの意見を述べました。","respondent":"米田商業・観光課長","answer":"今回お認めいただくとすると、４２９万円を含めまして、２,３０４万円余の交付をいただけることになってあります。相談員といたしましては、現状６名体制で月１２日というようなことで、交代で勤務ということになってあります。","id":"exchange-034"},{"speaker":"本多委員","kind":"質問","question":"消費者センターの充実というところでお聞きするんですけども、例えば、区の消費者センターは今１カ所じゃないですか。それをもっと、拠点を細やかに、出張所を配備したり、そういう発想というのはないのか尋ねました。","respondent":"米田商業・観光課長","answer":"１カ所でやらせていただいておりますが、２階に社会福祉協議会なり成年後見センターがありますので、事案に応じて２階との連携もしております。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほどの相談員の体制なんですけど、６名で月１２日というのは、１カ月につき１２日勤務の方が６名いるという考え方なんですか。１日体制というのは、大体３名程度と、そういう感じか尋ねました。","respondent":"米田商業・観光課長","answer":"今大体ですが、１日に２人から３人の体制ということになっています。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"そこら辺の意見を聞いたりとか、せっかくつくるものがその情報じゃないとか、あるじゃないですか。2)ですが、本当はこういった研修をもっと強化してほしいなというふうに、お考えを説明を求めました。","respondent":"米田商業・観光課長","answer":"あるいは学生の目線、保護者の目線から見てわかりやすいパンフレットを心がけていければということで、今後検討してまいりたいと思います。","id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"井上委員","kind":"提案","question":"正副でまとめていただきまして、ありがとうあります。ここのところで二つ提案をさせていただいたんですけれども、その他の部分でもこちらの提案とか、少し事前にお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"前年度、この辺を軽くというか、やっていなかったかな。観光とか商業、中小企業、やっていなかったかなという思いが、やっていないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"じゃあ改めて、やっていて、この辺を選んだあれを、委員長、副委員長、教えていただければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと覆すようで申しわけないんですけど、区民委員会というのは、例えば今日も議案審査があって、午前中で終わりそうな感じがしますよね。４時過ぎまでかかるということが多かったんですけど、もう１項目増やしていただけないか、無理ですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248984?Template=document&Id=2698#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":41329,"voices":135}}]);
